window.BASE={"qcm":[{"id":"bz6f4mgc","t":"Combien de camps romains encerclent le village d'Astérix ?","r":["3","4","5","6"],"b":1,"a":"Chaque album s'ouvre sur la même carte : en 50 avant J.-C., toute la Gaule est occupée… sauf un village d'irréductibles Gaulois.","c":"Arts & lettres","d":3},{"id":"evanmyy6","t":"Comment appelle-t-on les habitants de la principauté de Monaco ?","r":["Les Monacois","Les Monégasques","Les Monaciens","Les Monacais"],"b":1,"a":"Les Monégasques de nationalité sont minoritaires dans leur propre pays, qui accueille surtout des résidents étrangers.","c":"Géographie","d":3},{"id":"ybkk876h","t":"Dans quel film Disney l'héroïne chante-t-elle « L'Air du vent », Oscar de la meilleure chanson originale ?","r":["Pocahontas","Mulan","La Petite Sirène","Hercule"],"b":0,"a":"La chanson est signée Alan Menken pour la musique et Stephen Schwartz pour les paroles.","c":"Musique","d":2},{"id":"y0imecaf","t":"Quel acteur irlandais incarne James Bond dans « Demain ne meurt jamais » (1997) ?","r":["Liam Neeson","Colin Farrell","Pierce Brosnan","Gabriel Byrne"],"b":2,"a":"Pierce Brosnan a tenu le rôle dans quatre films, de GoldenEye (1995) à Meurs un autre jour (2002).","c":"Cinéma & séries","d":2},{"id":"479qnw61","t":"Quel récipient allongé, à bec verseur, sert à présenter la sauce à table ?","r":["La soupière","La carafe","La saucière","Le ramequin"],"b":2,"a":"En anglais, on l'appelle « gravy boat », le bateau à sauce, à cause de sa forme de coque.","c":"Culture générale","d":3},{"id":"0ne4q890","t":"Qui a réalisé le film « Le Pont de la rivière Kwaï », sorti en 1957 ?","r":["Carol Reed","Alfred Hitchcock","David Lean","Robert Stevenson"],"b":2,"a":"Le film a remporté l'Oscar du meilleur film, et Alec Guinness a reçu celui du meilleur acteur.","c":"Cinéma & séries","d":3},{"id":"4xrud6uu","t":"Sur quel petit véhicule à quatre roues, sans suspension, la plupart des pilotes automobiles font-ils leurs débuts ?","r":["Le quad","Le kart","Le buggy","Le side-car"],"b":1,"a":"Ayrton Senna et Michael Schumacher ont tous deux brillé en karting avant d'arriver en Formule 1.","c":"Sport","d":1},{"id":"72ogqns7","t":"Genève, au bord du lac Léman, est une ville de quel pays ?","r":["France","Belgique","Luxembourg","Suisse"],"b":3,"a":"Genève accueille le siège du Comité international de la Croix-Rouge, fondé dans la ville au XIXe siècle.","c":"Géographie","d":2},{"id":"b97dll7x","t":"Comment appelle-t-on les habitants de Marseille ?","r":["Marsiliens","Marseillais","Massaliotes","Marseillois"],"b":1,"a":"Marseille a été fondée vers 600 av. J.-C. par des Grecs venus de Phocée, sous le nom de Massalia.","c":"Géographie","d":1},{"id":"kbm0b687","t":"Comment s'appelle le vieux chevalier Jedi qui prend Luke Skywalker sous son aile dans le premier « Star Wars » ?","r":["Qui-Gon Jinn","Mace Windu","Obi-Wan Kenobi","Maître Yoda"],"b":2,"a":"Il vit en ermite dans le désert de Tatooine et offre à Luke le sabre laser de son père.","c":"Cinéma & séries","d":2},{"id":"bkcnmkup","t":"Combien d'années de règne Elizabeth II a-t-elle fêtées lors de son jubilé de platine, en 2022 ?","r":["60","65","70","75"],"b":2,"a":"Elle est la première souveraine britannique à avoir célébré un jubilé de platine.","c":"Autour de la fête","d":3},{"id":"n60cjyoe","t":"Quel mot désigne la diversité des espèces vivantes, de leurs gènes et des milieux qu'elles habitent ?","r":["Biodiversité","Biosphère","Biologie","Biomasse"],"b":0,"a":"Le mot s'est imposé dans les années 1980 et s'est répandu dans le monde avec le Sommet de la Terre de Rio, en 1992.","c":"Nature","d":2},{"id":"fazafr9j","t":"Quel cofondateur d'Apple a conçu seul l'ordinateur Apple I ?","r":["Steve Wozniak","Steve Jobs","Ronald Wayne","Tim Cook"],"b":0,"a":"Steve Jobs vendit son minibus Volkswagen et Wozniak sa calculatrice HP pour financer les débuts.","c":"Sciences","d":3},{"id":"dm99qj0s","t":"Que signifie « fiesta » en espagnol ?","r":["Sieste","Fête","Repas","Danse"],"b":1,"a":"Le français a gardé « fiesta » tel quel, alors que « sieste » vient d'un autre mot latin, sexta, la sixième heure du jour.","c":"Culture générale","d":1},{"id":"b8d4d75l","t":"Dans « Les 101 Dalmatiens » (1961), de quelle couleur sont les taches des chiots ?","r":["Noires","Marron","Grises","Rousses"],"b":0,"a":"Pour dessiner autant de chiens tachetés, Disney a utilisé la photocopie des dessins sur les cellulos, une première pour le studio.","c":"Cinéma & séries","d":1},{"id":"ftqvpeqp","t":"Dans quelle comédie de 1994 entend-on « Barrez-vous, cons de mimes ! » ?","r":["Les Visiteurs","Grosse Fatigue","Le Dîner de cons","La Cité de la peur"],"b":3,"a":"Écrit par Les Nuls, le film se déroule pendant le Festival de Cannes, où une attachée de presse tente de promouvoir un nanar.","c":"Cinéma & séries","d":3},{"id":"f5ku1b6e","t":"En quelle année Marty McFly est-il projeté, dans le premier « Retour vers le futur » (1985) ?","r":["1945","1965","1955","1975"],"b":2,"a":"Dans la suite, Marty visite 2015, puis 1885 dans le troisième film.","c":"Cinéma & séries","d":3},{"id":"gzeo9hx8","t":"Quelle soupe portugaise mêle purée de pommes de terre, chou vert très finement émincé et rondelles de chorizo ?","r":["Gaspacho","Caldo verde","Minestrone","Garbure"],"b":1,"a":"Originaire du nord du pays, elle se sert dans les fêtes populaires et dans les cafés, à toute heure, avec une tranche de pain de maïs.","c":"Cuisine","d":2},{"id":"kpr4khvy","t":"Quelle matière les enfants utilisent-ils, humide et tassée, pour bâtir des châteaux sur la plage ?","r":["Le plâtre","Le sable","Le ciment","La glace"],"b":1,"a":"Des sculpteurs professionnels bâtissent des châteaux de sable géants : c'est l'eau qui lie les grains entre eux.","c":"Arts & lettres","d":1},{"id":"dycjx574","t":"Sur quel continent vit le tigre à l'état sauvage ?","r":["L'Afrique","L'Amérique du Sud","L'Asie","L'Océanie"],"b":2,"a":"Contrairement à la plupart des félins, le tigre aime l'eau : c'est un excellent nageur.","c":"Nature","d":3},{"id":"gpi5uhst","t":"Sur quel continent se situe la Guyane française ?","r":["Afrique","Amérique du Sud","Asie","Océanie"],"b":1,"a":"Seul territoire français d'Amérique du Sud, la Guyane est couverte à plus de 90 % par la forêt amazonienne.","c":"Géographie","d":1},{"id":"1bjipvb1","t":"Quelle part d'un iceberg est cachée sous l'eau ?","r":["Environ 10 %","Environ 50 %","Environ 90 %","Environ 99 %"],"b":2,"a":"D'où l'expression « la partie émergée de l'iceberg », pour désigner ce qui n'est qu'une petite part du problème.","c":"Sciences","d":3},{"id":"a45pfapy","t":"La bachata, musique de guitares devenue populaire dans toute l'Amérique latine, est originaire de quel pays ?","r":["Cuba","La République dominicaine","Porto Rico","La Colombie"],"b":1,"a":"Longtemps méprisée comme une musique des quartiers pauvres, la bachata a été inscrite au patrimoine immatériel de l'UNESCO en 2019.","c":"Musique","d":3},{"id":"lcs39qdt","t":"Dans quel conte de Perrault une marraine fée change-t-elle une citrouille en carrosse ?","r":["Peau d'Âne","Cendrillon","La Belle au bois dormant","Le Petit Chaperon rouge"],"b":1,"a":"Dans le même conte, la marraine change aussi des souris en chevaux et un rat en cocher.","c":"Arts & lettres","d":1},{"id":"x5c224lj","t":"Quelle civilisation a bâti la cité de Tenochtitlan, au milieu d'un lac ?","r":["Les Mayas","Les Aztèques","Les Incas","Les Olmèques"],"b":1,"a":"La ville de Mexico s'est bâtie sur ses ruines, après l'assèchement progressif du lac Texcoco.","c":"Histoire","d":2},{"id":"guy7ft6y","t":"Comment s'appelle le chat noir de la jeune sorcière Kiki, dans le film de Hayao Miyazaki sorti en 1989 ?","r":["Tora","Jiji","Mochi","Kuro"],"b":1,"a":"Kiki livre des colis à dos de balai pour gagner sa vie dans une ville au bord de la mer.","c":"Autour de la fête","d":2},{"id":"s8jixev5","t":"Quel organe, protégé par le crâne, commande les mouvements et la pensée ?","r":["Le cerveau","Le foie","Le cœur","Les poumons"],"b":0,"a":"Le cerveau adulte pèse environ 1,3 à 1,4 kilo et consomme à lui seul une part importante de l'énergie du corps.","c":"Sciences","d":1},{"id":"jta8q5xc","t":"Quelles sont les trois couleurs du drapeau italien, de gauche à droite ?","r":["Vert, blanc, rouge","Rouge, blanc, vert","Bleu, blanc, rouge","Vert, jaune, rouge"],"b":0,"a":"Le tricolore italien fut inspiré du drapeau français de la fin du XVIIIe siècle.","c":"Géographie","d":3},{"id":"ze6i2un5","t":"Quel pays d'Amérique du Sud a deux capitales, La Paz et Sucre ?","r":["Paraguay","Pérou","Bolivie","Équateur"],"b":2,"a":"Il porte le nom de Simón Bolívar, héros de l'indépendance sud-américaine.","c":"Géographie","d":3},{"id":"pxvarh3h","t":"Quelle est la forme de « tener » à la première personne du présent ?","r":["teno","tiengo","tengo","tenga"],"b":2,"a":"« Tener » a un « g » à la première personne seulement, comme « poner » (pongo) et « venir » (vengo).","c":"Culture générale","d":2},{"id":"63jsac13","t":"Dans la version française de « La Belle et la Bête » (1991), comment s'appelle l'horloge du château ?","r":["Tic-Tac","Big Ben","Coucou","Lumière"],"b":1,"a":"Ce majordome guindé fait équipe avec le chandelier, avec qui il se dispute sans cesse.","c":"Cinéma & séries","d":3},{"id":"k73kjklq","t":"Dans quel royaume imaginaire d'Europe centrale Tintin recherche-t-il le sceptre d'Ottokar ?","r":["La Bordurie","La Syldavie","La Ruritanie","Le Gerolstein"],"b":1,"a":"La langue de la Syldavie, inventée par Hergé, s'inspire du dialecte bruxellois des Marolles.","c":"Arts & lettres","d":3},{"id":"mxh88407","t":"Qui a écrit le roman uchronique « Le Maître du Haut Château », publié en 1962 ?","r":["Toni Morrison","Carl Sagan","Ursula K. Le Guin","Philip K. Dick"],"b":3,"a":"Le roman imagine un monde où les puissances de l'Axe ont gagné la Seconde Guerre mondiale. Il a reçu le prix Hugo du meilleur roman en 1963.","c":"Arts & lettres","d":3},{"id":"o75p7u43","t":"Quelle sélection surnomme-t-on « die Mannschaft » ?","r":["Autriche","Allemagne","Suisse","Pays-Bas"],"b":1,"a":"Le mot allemand signifie simplement « équipe ».","c":"Sport","d":2},{"id":"etlz6vxt","t":"Quelle application de navigation, née en Israël et rachetée par Google en 2013, signale en temps réel les embouteillages ?","r":["Mappy","Coyote","Waze","TomTom"],"b":2,"a":"Ses utilisateurs, en signalant eux-mêmes accidents et contrôles, alimentent les informations de la carte.","c":"Sciences","d":3},{"id":"vzt6kl9h","t":"Comment s'appelle la science qui étudie les fossiles et les êtres vivants disparus ?","r":["La géologie","L'archéologie","La minéralogie","La paléontologie"],"b":3,"a":"Le mot vient du grec palaios, « ancien », et onta, « les êtres ».","c":"Nature","d":1},{"id":"c5rwym1l","t":"En quelle année Henri IV est-il assassiné par Ravaillac ?","r":["1520","1610","1715","1789"],"b":1,"a":"Le roi est poignardé dans son carrosse, immobilisé par un embarras de circulation rue de la Ferronnerie.","c":"Histoire","d":2},{"id":"89tazkhu","t":"Quel instrument réunionnais, fait de hampes de fleurs de canne à sucre garnies de graines, accompagne le maloya ?","r":["Le kayamb","Le djembé","Le guiro","Les maracas"],"b":0,"a":"On le secoue à plat, comme un plateau, pour obtenir un bruissement proche de la pluie.","c":"Musique","d":2},{"id":"4oy5emt6","t":"Quel est le nom de famille de naissance de la princesse Diana ?","r":["Windsor","Middleton","Mountbatten","Spencer"],"b":3,"a":"Son frère, Charles Spencer, a prononcé son éloge funèbre lors de ses obsèques en 1997.","c":"Jeux & pop culture","d":3},{"id":"1b2510lt","t":"Quelle monnaie utilise-t-on à Berne, Genève et Zurich ?","r":["L'euro","Le franc suisse","Le mark","La couronne"],"b":1,"a":"Son sigle, CHF, vient du latin « Confoederatio Helvetica » et de l'initiale de « franc ».","c":"Culture générale","d":1},{"id":"691wyaxh","t":"Quel outil indique, grâce à une petite bulle, qu'une étagère est bien horizontale ?","r":["Le fil à plomb","L'équerre","Le niveau","Le compas"],"b":2,"a":"La bulle flotte dans une fiole légèrement bombée remplie d'alcool, un liquide qui ne gèle pas.","c":"Culture générale","d":2},{"id":"dop7vcae","t":"Quel fromage à l'odeur forte vient de l'Avesnois, dans le Nord ?","r":["Le munster","Le livarot","Le maroilles","Le pont-l'évêque"],"b":2,"a":"Il tire son nom du village de Maroilles, où les moines de l'abbaye l'auraient créé.","c":"Cuisine","d":3},{"id":"zm80ik5p","t":"Quel monstre aux têtes repoussantes Héraclès a-t-il vaincu dans les marais de Lerne ?","r":["La Chimère","Le Sphinx","L'Hydre","Scylla"],"b":2,"a":"Pour la vaincre, Héraclès fut aidé par son neveu Iolaos, qui cautérisait les cous tranchés.","c":"Culture générale","d":3},{"id":"xi3hr7nl","t":"Quelle plateforme de vidéos a pour logo un rectangle rouge avec un triangle blanc ?","r":["Dailymotion","Vimeo","YouTube","Twitch"],"b":2,"a":"Le triangle du logo évoque le bouton « lecture » que l'on trouve sur les lecteurs de vidéos.","c":"Jeux & pop culture","d":2},{"id":"w7hqef49","t":"Le 3 avril 2007, quelle vitesse, en kilomètres par heure, atteint la rame TGV V150 lors de son record sur rail ?","r":["515,3 km/h","603,0 km/h","574,8 km/h","481,2 km/h"],"b":2,"a":"Le record a été établi sur la LGV Est européenne, avant sa mise en service commerciale.","c":"Culture générale","d":2},{"id":"44c3o13i","t":"En quelle année paraît en anglais le septième et dernier tome de la saga Harry Potter, Les Reliques de la Mort ?","r":["2005","2008","2007","2006"],"b":2,"a":"Son titre anglais est Harry Potter and the Deathly Hallows. La traduction française a paru à l'automne de la même année.","c":"Arts & lettres","d":2},{"id":"e12r5ame","t":"Dans quel pays se trouve Agadir, station balnéaire reconstruite après le séisme de 1960 ?","r":["Maroc","Tunisie","Algérie","Mauritanie"],"b":0,"a":"Le tremblement de terre de février 1960 détruisit presque toute la ville, rebâtie ensuite un peu plus au sud.","c":"Géographie","d":3},{"id":"8ax8brqg","t":"Quel signe du zodiaque correspond à une naissance le 15 mars ?","r":["Poissons","Bélier","Verseau","Taureau"],"b":0,"a":"Les Poissons sont le douzième et dernier signe du zodiaque occidental.","c":"Autour de la fête","d":2},{"id":"wggwj1tk","t":"Que signifie « to give up » ?","r":["Rendre visite","Renoncer","Offrir","Se lever"],"b":1,"a":"« Give up » peut aussi vouloir dire arrêter une habitude, comme dans « give up smoking ».","c":"Culture générale","d":2},{"id":"c2r28e8y","t":"Combien de grammes pèse une once, l'unité des recettes anglo-saxonnes ?","r":["14,17 g","28,35 g","113,40 g","453,60 g"],"b":1,"a":"Le mot once vient du latin uncia, le douzième d'une livre romaine.","c":"Culture générale","d":3},{"id":"6dic973v","t":"Quel personnage de « The Big Bang Theory » s'exclame « Bazinga ! » après avoir fait une blague ?","r":["Leonard Hofstadter","Howard Wolowitz","Sheldon Cooper","Raj Koothrappali"],"b":2,"a":"Sheldon utilise ce cri pour annoncer qu'il vient de faire une farce à son entourage, un humour que les autres ne comprennent pas toujours.","c":"Cinéma & séries","d":2},{"id":"3mw1agaq","t":"Dans Lucky Luke, quel est le prénom du plus grand des quatre Dalton, aussi le plus bête ?","r":["Jack","William","Averell","Joe"],"b":2,"a":"Les Dalton de Morris sont présentés comme les cousins des vrais frères Dalton, des hors-la-loi américains ayant réellement existé.","c":"Arts & lettres","d":2},{"id":"rq2pajuz","t":"De quel pays vient le tai-chi-chuan, que l'on pratique souvent en plein air, au ralenti ?","r":["Chine","Japon","Inde","Thaïlande"],"b":0,"a":"Art martial à l'origine, le tai-chi est surtout pratiqué aujourd'hui comme une gymnastique douce.","c":"Sport","d":3},{"id":"mdp1x7jn","t":"Quel révolutionnaire, surnommé « l'Incorruptible », est guillotiné en juillet 1794 ?","r":["Georges Danton","Maximilien de Robespierre","Jean-Paul Marat","Louis Antoine de Saint-Just"],"b":1,"a":"Sa chute, le 9 thermidor, met fin à la Terreur.","c":"Histoire","d":2},{"id":"clpoqdq2","t":"Dans quelle salle parisienne Joséphine Baker a-t-elle dansé sa célèbre ceinture de bananes ?","r":["Le Lido","Le Moulin Rouge","Le Crazy Horse","Les Folies Bergère"],"b":3,"a":"Cette ceinture de bananes est restée l'image la plus célèbre de sa carrière.","c":"Arts & lettres","d":3},{"id":"i4thmy61","t":"En 1934, quel pays organise la première Coupe du monde disputée en Europe et la remporte à domicile ?","r":["Tchécoslovaquie","Italie","Allemagne","Autriche"],"b":1,"a":"En finale, à Rome, elle bat la Tchécoslovaquie 2-1 après prolongation.","c":"Sport","d":3},{"id":"1sigs16q","t":"Quelle est la nature du mot « vite » dans « Il court vite » ?","r":["Adjectif","Adverbe","Préposition","Conjonction"],"b":1,"a":"Un adverbe est invariable : on n'écrit jamais « ils courent vites ».","c":"Culture générale","d":2},{"id":"rccya3q5","t":"Quel instrument à cordes pincées figure sur les pièces irlandaises d'euro ?","r":["Le violon","La guitare","La harpe","La mandoline"],"b":2,"a":"La harpe est aussi l'emblème de l'Irlande sur les armoiries de l'État, et la marque d'une célèbre bière brune l'a adoptée.","c":"Musique","d":3},{"id":"5cmteahp","t":"Quel acteur britannique incarne James Bond dans « Casino Royale » (2006) ?","r":["Pierce Brosnan","Daniel Craig","Timothy Dalton","Roger Moore"],"b":1,"a":"Daniel Craig est le premier James Bond blond de la saga.","c":"Cinéma & séries","d":2},{"id":"0mcrfk02","t":"Quel document trilingue trouvé en 1799 par l'armée de Bonaparte a permis à Champollion de déchiffrer les hiéroglyphes ?","r":["La pierre de Palerme","La table d'Abydos","La pierre de Rosette","La palette de Narmer"],"b":2,"a":"Champollion annonce son déchiffrement en 1822.","c":"Histoire","d":2},{"id":"c9ycavii","t":"Quel coureur est le premier à remporter cinq fois le Tour de France ?","r":["Jacques Anquetil","Bernard Hinault","Eddy Merckx","Miguel Indurain"],"b":0,"a":"Il a aussi remporté le Giro et la Vuelta, devenant le premier à gagner les trois grands tours.","c":"Sport","d":2},{"id":"gldqw078","t":"Quelles créatures menacent les survivants dans la série « The Walking Dead » (2010) ?","r":["Des vampires","Des zombies","Des loups-garous","Des extraterrestres"],"b":1,"a":"La série est adaptée d'une bande dessinée américaine de Robert Kirkman.","c":"Cinéma & séries","d":1},{"id":"v01y8h9m","t":"Dans quel pays Joe Dassin est-il né, en 1938 ?","r":["France","Canada","États-Unis","Belgique"],"b":2,"a":"Son père, le réalisateur Jules Dassin, avait dû quitter Hollywood, mis sur liste noire au temps du maccarthysme.","c":"Musique","d":3},{"id":"qvru6h73","t":"Comment appelle-t-on la radio dentaire qui montre toutes les dents des deux mâchoires sur une seule image ?","r":["Radio panoramique","Radio rétro-alvéolaire","Radio de profil","Radio de face"],"b":0,"a":"Elle est courante chez le chirurgien-dentiste, notamment pour repérer les dents de sagesse incluses.","c":"Culture générale","d":3},{"id":"cxq0k11c","t":"Que signifie « sí » avec un accent, quand on répond à une question ?","r":["Si","Ainsi","Oui","Non"],"b":2,"a":"Sans accent, « si » est la conjonction « si » de la condition : l'accent écrit sépare ici deux mots de sens différents.","c":"Culture générale","d":1},{"id":"39i32wrp","t":"Dans « Mary Poppins » (1964), quel personnage chante « Chem Cheminée » ?","r":["George Banks","Michael Banks","Oncle Albert","Bert"],"b":3,"a":"La chanson a reçu l'Oscar de la meilleure chanson originale. Bert est joué par Dick Van Dyke.","c":"Musique","d":3},{"id":"vana7eb8","t":"Comment s'appelle le lionceau héros du « Roi lion » (1994) ?","r":["Mufasa","Simba","Scar","Nala"],"b":1,"a":"Simba signifie « lion » en swahili.","c":"Cinéma & séries","d":1},{"id":"oc1m00pb","t":"Quel animal d'Amérique du Sud porte aussi le nom de grand fourmilier ?","r":["Le tatou","Le pécari","Le coati","Le tamanoir"],"b":3,"a":"Le tamanoir n'a pas de dents : il capture fourmis et termites avec une langue très longue et collante.","c":"Nature","d":3},{"id":"h5ppt4s8","t":"La feuille de quel arbre figure sur le drapeau du Canada ?","r":["Le chêne","L'érable","Le bouleau","Le platane"],"b":1,"a":"On récolte au printemps la sève de l'érable à sucre pour en faire le sirop d'érable. Le Québec en est le grand producteur.","c":"Nature","d":2},{"id":"ddeclxao","t":"Quels animaux livrent bataille aux soldats de jouet dans le ballet « Casse-Noisette » ?","r":["Des corbeaux","Des chats","Des souris","Des serpents"],"b":2,"a":"Le ballet s'inspire d'un conte d'E. T. A. Hoffmann, adapté en France par Alexandre Dumas, qui servit de base au livret de Petipa.","c":"Arts & lettres","d":2},{"id":"ol3ie35e","t":"Qui a écrit « Émile ou De l'éducation », traité pédagogique de 1762 ?","r":["Laurence Sterne","Jean-Jacques Rousseau","Denis Diderot","Henry Fielding"],"b":1,"a":"Le livre fut condamné à Paris et à Genève peu après sa parution, et son auteur dut s'enfuir.","c":"Arts & lettres","d":2},{"id":"z54dogtf","t":"Le marché de Noël de Strasbourg s'installe au pied de la cathédrale. Combien de mètres mesure sa flèche ?","r":["142 m","112 m","172 m","96 m"],"b":0,"a":"La cathédrale a longtemps été le plus haut édifice du monde, du XVIIe au XIXe siècle.","c":"Autour de la fête","d":2},{"id":"m5tpo1oc","t":"Quelle entreprise édite le navigateur web Safari ?","r":["Google","Apple","Microsoft","Mozilla"],"b":1,"a":"Safari est fondé sur le moteur WebKit, dérivé du moteur KHTML.","c":"Jeux & pop culture","d":2},{"id":"dd75si90","t":"Quelle ville française est desservie par l'aéroport Saint-Exupéry ?","r":["Toulouse","Marseille","Lyon","Bordeaux"],"b":2,"a":"L'aéroport porte le nom de l'auteur du « Petit Prince », aviateur né à Lyon.","c":"Culture générale","d":3},{"id":"7daixjfd","t":"Dans « Encanto » (2021), comment s'appelle la seule enfant de la famille Madrigal à n'avoir reçu aucun don magique ?","r":["Isabela","Luisa","Mirabel","Dolores"],"b":2,"a":"Le film se déroule en Colombie et ses chansons sont signées Lin-Manuel Miranda, le créateur de la comédie musicale Hamilton.","c":"Cinéma & séries","d":3},{"id":"ncka1gjw","t":"Dans quelle mer le Danube se jette-t-il ?","r":["Mer Noire","Mer Adriatique","Mer Baltique","Mer Égée"],"b":0,"a":"Le Danube traverse ou longe dix pays, plus que n'importe quel autre fleuve au monde.","c":"Géographie","d":3},{"id":"ju7ysdfu","t":"Sur un circuit automobile, quel drapeau signale un danger et interdit de dépasser ?","r":["Le bleu","Le blanc","Le vert","Le jaune"],"b":3,"a":"Agité deux fois de suite, ce drapeau signale un danger plus grave : les pilotes doivent être prêts à s'arrêter.","c":"Géographie","d":3},{"id":"m2g7evy7","t":"Comment qualifie-t-on une habitation creusée dans la roche, comme celles du Val de Loire ?","r":["Lacustre","Mégalithique","Troglodytique","Pavillonnaire"],"b":2,"a":"Dans le Val de Loire, de nombreuses maisons creusées dans le tuffeau gardent une température presque constante toute l'année.","c":"Arts & lettres","d":3},{"id":"pouo71qk","t":"Quel joueur lança à un arbitre de Wimbledon, en 1981, le célèbre « You cannot be serious! » ?","r":["Jimmy Connors","Ilie Năstase","Ivan Lendl","John McEnroe"],"b":3,"a":"La formule est devenue si liée à lui qu'il en a fait le titre de son autobiographie.","c":"Sport","d":3},{"id":"m1tml875","t":"Combien de kilogrammes y a-t-il dans une tonne ?","r":["100","500","1 000","10 000"],"b":2,"a":"Le mot « tonne » a d'abord désigné un grand tonneau, d'où l'idée d'une cargaison.","c":"Culture générale","d":1},{"id":"qkauf2i5","t":"Dans quel pays est née la danse classique kathak, aux clochettes de chevilles ?","r":["L'Inde","Le Pakistan","Le Népal","Le Sri Lanka"],"b":0,"a":"Ses danseurs portent des clochettes aux chevilles, les ghungroo, qui soulignent le rythme des pieds.","c":"Musique","d":1},{"id":"o0lo25m2","t":"De quelle région la quiche aux lardons est-elle originaire ?","r":["La Lorraine","L'Alsace","La Champagne","La Franche-Comté"],"b":0,"a":"Le mot quiche viendrait de kuchen, « gâteau » en francique lorrain.","c":"Cuisine","d":2},{"id":"qnzxi57l","t":"Quel tissu bouclé et absorbant sert à faire les serviettes de bain et les peignoirs ?","r":["Le satin","Le velours","Le tulle","L'éponge"],"b":3,"a":"Les petites boucles du tissu éponge multiplient la surface en contact avec la peau, ce qui l'aide à boire l'eau.","c":"Jeux & pop culture","d":2},{"id":"heeof4wp","t":"Quelle application de messagerie, créée par Jan Koum et Brian Acton, Facebook a-t-il rachetée en 2014 ?","r":["Telegram","Viber","Signal","WhatsApp"],"b":3,"a":"Son nom est un jeu de mots sur l'expression anglaise « What's up ? », qui signifie « Quoi de neuf ? ».","c":"Sciences","d":3},{"id":"taox2jwo","t":"Quelle ville est la capitale de Cuba ?","r":["Santiago de Cuba","Varadero","La Havane","Trinidad"],"b":2,"a":"Sa vieille ville et son système de fortifications coloniales sont inscrits au patrimoine mondial de l'Unesco depuis 1982.","c":"Géographie","d":2},{"id":"udyk9lpc","t":"Que signifie le mot espagnol « vaso » ?","r":["Vase","Bouteille","Verre","Tasse"],"b":2,"a":"Le vase se dit « jarrón » ou « florero » en espagnol.","c":"Culture générale","d":1},{"id":"m2ordghp","t":"De quelle couleur est le carton que brandit l'arbitre pour expulser un joueur ?","r":["Jaune","Blanc","Vert","Rouge"],"b":3,"a":"Les cartons sont apparus en Coupe du monde en 1970, sur une idée de l'arbitre anglais Ken Aston, inspiré par les feux tricolores.","c":"Sport","d":1},{"id":"xuez6uaj","t":"Quelle ville est la capitale de la Turquie ?","r":["Istanbul","Izmir","Ankara","Antalya"],"b":2,"a":"Mustafa Kemal Atatürk en fit la capitale en 1923, à la place d'Istanbul, l'ancienne capitale de l'Empire ottoman.","c":"Géographie","d":3},{"id":"82hwf0w7","t":"En 2019, quel capitaine sud-africain soulève la Coupe du monde de rugby au Japon ?","r":["François Pienaar","John Smit","Siya Kolisi","Eben Etzebeth"],"b":2,"a":"Siya Kolisi est le premier capitaine noir des Springboks ; il a grandi dans un township près de Port Elizabeth.","c":"Sport","d":3},{"id":"kdwl4dkn","t":"De quel pays viennent les loukoumades, petits beignets ronds arrosés de miel ?","r":["La Grèce","L'Italie","Le Portugal","L'Espagne"],"b":0,"a":"Ces beignets de pâte levée, frits puis nappés de miel, sont souvent saupoudrés de cannelle ou de noix concassées.","c":"Cuisine","d":3},{"id":"au5ujk2d","t":"Quel rapace est l'emblème des États-Unis ?","r":["Aigle royal","Pygargue à tête blanche","Condor de Californie","Faucon pèlerin"],"b":1,"a":"Malgré son nom anglais « bald eagle », il n'est pas chauve : sa tête est couverte de plumes blanches. Il figure sur le Grand sceau des États-Unis depuis 1782.","c":"Nature","d":3},{"id":"0kuy3pp3","t":"Environ quelle distance sépare l'équateur du pôle Nord, en kilomètres ?","r":["5 000 km","10 000 km","20 000 km","15 000 km"],"b":1,"a":"Le mètre a d'abord été défini comme la dix-millionième partie de cette distance, mesurée le long du méridien de Paris.","c":"Sciences","d":2},{"id":"6cmcoudw","t":"Quelle chanteuse galloise a chanté « Total Eclipse of the Heart » en 1983 ?","r":["Kim Wilde","Bonnie Tyler","Annie Lennox","Kate Bush"],"b":1,"a":"La chanson a été écrite et produite par Jim Steinman, l'auteur des grands succès de Meat Loaf.","c":"Musique","d":3},{"id":"8kiw34w0","t":"Quel préfet de la Seine impose, dans les années 1880, l'usage de récipients pour les ordures ménagères, qui portent son nom ?","r":["Georges Eugène Haussmann","Claude-Philibert Rambuteau","Eugène Poubelle","Louis Lépine"],"b":2,"a":"Les chiffonniers, privés de leur tri dans les tas d'ordures, protestent contre la mesure.","c":"Histoire","d":3},{"id":"w1u17mm8","t":"Dans quelle poubelle jaune, en France, jette-t-on en général les emballages en plastique et les cartons ?","r":["La poubelle des ordures ménagères","La poubelle de tri","Le composteur","Le conteneur à verre"],"b":1,"a":"Le verre, lui, ne va pas dans la poubelle de tri mais dans des conteneurs à part, car il se recycle dans une filière distincte.","c":"Nature","d":1},{"id":"9kyevtbe","t":"De quelle couleur est le fond du drapeau de l'Organisation des Nations unies ?","r":["Blanc","Vert","Bleu clair","Bleu foncé"],"b":2,"a":"Cette couleur a aussi donné leur surnom aux casques bleus, les soldats de maintien de la paix de l'ONU.","c":"Géographie","d":2},{"id":"a4yk1h37","t":"Quelle grande ville d'Alsace donne son nom à une saucisse de porc fumée, la knack ?","r":["Colmar","Mulhouse","Haguenau","Strasbourg"],"b":3,"a":"Le mot knack viendrait du bruit que fait la saucisse quand on croque dans sa peau.","c":"Cuisine","d":3},{"id":"k7sq68d8","t":"En quelle année les Français obtiennent-ils leurs premiers congés payés, de deux semaines ?","r":["1919","1936","1945","1968"],"b":1,"a":"Un billet de train à tarif réduit, dit « billet Lagrange », permet alors à de nombreuses familles ouvrières de partir en vacances.","c":"Culture générale","d":3},{"id":"1a4aj0y5","t":"Quel chef, vainqueur de Top Chef en 2012, a repris en 2021 le restaurant de l'hôtel Plaza Athénée, à Paris ?","r":["Jean Imbert","Norbert Tarayre","Juan Arbelaez","Mory Sacko"],"b":0,"a":"Au Plaza Athénée, il succède à Alain Ducasse et y remet la viande et la cuisine classique à l'honneur.","c":"Cuisine","d":3},{"id":"381ys3e3","t":"Quelle ville abrite le siège de l'Académie royale espagnole ?","r":["Tolède","Salamanque","Madrid","Séville"],"b":2,"a":"Son siège madrilène se trouve près du parc du Retiro.","c":"Culture générale","d":2},{"id":"a1ak9i5x","t":"Qui est élu président de la République en 1995, pour succéder à François Mitterrand ?","r":["Édouard Balladur","Lionel Jospin","Raymond Barre","Jacques Chirac"],"b":3,"a":"Il avait été maire de Paris pendant dix-huit ans avant d'entrer à l'Élysée.","c":"Histoire","d":3},{"id":"jkm9pobc","t":"Kim, Khloé et Kourtney sont les sœurs de quelle famille vedette de la télé-réalité ?","r":["Hilton","Osbourne","Kardashian","Spears"],"b":2,"a":"Leur père, l'avocat Robert Kardashian, avait défendu O. J. Simpson lors de son célèbre procès.","c":"Jeux & pop culture","d":1},{"id":"d8lz9l03","t":"Comment appelle-t-on la capacité à se mettre à la place d'autrui pour ressentir ce qu'il ressent ?","r":["Apathie","Empathie","Indifférence","Égoïsme"],"b":1,"a":"Le mot « empathie » s'est répandu en français au XXe siècle. Il traduit l'allemand Einfühlung, un terme employé d'abord pour parler de l'art.","c":"Arts & lettres","d":2},{"id":"lc9qeld3","t":"Dans quelle ville du Brésil la statue du Christ Rédempteur domine-t-elle le mont Corcovado ?","r":["São Paulo","Salvador","Rio de Janeiro","Recife"],"b":2,"a":"La statue a été inaugurée en 1931, les bras grands ouverts au-dessus de la baie.","c":"Géographie","d":1},{"id":"xk4zxxxl","t":"Que veut dire « feedback » dans le monde du travail ?","r":["Un budget prévisionnel","Une pause déjeuner","Un retour d'information","Une promotion interne"],"b":2,"a":"À l'origine, le mot vient de l'électronique : un signal de sortie renvoyé à l'entrée d'un système.","c":"Culture générale","d":2},{"id":"56udp7vy","t":"Quel poète latin accompagne Dante à travers l'Enfer dans La Divine Comédie ?","r":["Ovide","Horace","Virgile","Lucain"],"b":2,"a":"Béatrice prend ensuite le relais pour la dernière partie du voyage, le Paradis.","c":"Arts & lettres","d":3},{"id":"4elt5bjv","t":"Quel instrument à vent de la famille des cuivres a une coulisse qu'on avance et qu'on recule ?","r":["La trompette","Le cor","Le trombone","Le tuba"],"b":2,"a":"La coulisse allonge le tube pour changer la note : les pistons des autres cuivres font le même travail.","c":"Musique","d":2},{"id":"46s55t61","t":"Quel stade possède la plus grande capacité d'accueil de France ?","r":["Stade de France","Stade Vélodrome","Parc des Princes","Groupama Stadium"],"b":0,"a":"Le Stade de France a été construit à Saint-Denis pour accueillir la Coupe du monde de football de 1998.","c":"Culture générale","d":2},{"id":"zw8e0ej9","t":"Quelle langue co-officielle avec le castillan parle-t-on à Barcelone ?","r":["Le catalan","Le galicien","Le basque","L'occitan"],"b":0,"a":"Elle est aussi la seule langue officielle d'Andorre.","c":"Culture générale","d":1},{"id":"te44s36t","t":"Combien d'épreuves composent l'heptathlon ?","r":["5","6","7","8"],"b":2,"a":"Il a remplacé le pentathlon féminin aux Jeux olympiques en 1984.","c":"Sport","d":2},{"id":"fdqd9995","t":"Comment dit-on « Joyeux Noël » en allemand ?","r":["Frohe Weihnachten","Feliz Navidad","Merry Christmas","Buon Natale"],"b":0,"a":"Weihnachten signifie littéralement « nuits sacrées » : le mot est ancien et pluriel.","c":"Autour de la fête","d":2},{"id":"0ozjugz5","t":"Que veut dire « bimestriel » ?","r":["Deux fois par an","Quatre fois par an","Six fois par an","Douze fois par an"],"b":2,"a":"Le piège vient de « bimensuel », qui désigne ce qui paraît deux fois par mois : les deux mots ne se confondent pas.","c":"Culture générale","d":3},{"id":"ac4ky3gb","t":"Quel ustensile sert à étaler une pâte ?","r":["Un rouleau à pâtisserie","Un presse-purée","Un fouet","Un entonnoir"],"b":0,"a":"On farine le plan de travail et le rouleau pour éviter que la pâte ne colle pendant qu'on l'abaisse.","c":"Cuisine","d":1},{"id":"tpcbebgd","t":"Quel numéro d'urgence, créé à Londres en 1937, passe pour le premier numéro d'urgence au monde ?","r":["911","999","000","112"],"b":1,"a":"Il est né après un incendie mortel survenu à Londres en 1935, où les secours avaient été appelés trop tard.","c":"Culture générale","d":3},{"id":"is0vwv4c","t":"De quelle couleur sont les survêtements des joueurs dans « Squid Game » (2021) ?","r":["Rouges","Bleus","Gris","Verts"],"b":3,"a":"Les gardes masqués, eux, portent des combinaisons roses, et leur masque s'orne d'un rond, d'un triangle ou d'un carré.","c":"Cinéma & séries","d":2},{"id":"k7fzq74u","t":"Avant la décimalisation de 1971, combien de pence comptait une livre sterling ?","r":["100 pence","144 pence","200 pence","240 pence"],"b":3,"a":"Une livre valait 20 shillings, et un shilling 12 pence : un système hérité de la livre carolingienne, comme l'ancienne livre française.","c":"Culture générale","d":3},{"id":"sb9bdqp7","t":"Quel instrument était la spécialité de Benny Goodman, surnommé « le roi du swing » ?","r":["Le saxophone","La trompette","La clarinette","Le trombone"],"b":2,"a":"En 1938, son orchestre a donné un concert resté célèbre au Carnegie Hall de New York.","c":"Musique","d":3},{"id":"0qdsscx4","t":"En 2016, quelle ville accueille les premiers Jeux olympiques organisés en Amérique du Sud ?","r":["Buenos Aires","Rio de Janeiro","São Paulo","Santiago"],"b":1,"a":"Le Christ Rédempteur domine la ville.","c":"Sport","d":2},{"id":"k240lmau","t":"Comment nomme-t-on la surface sculptée située au-dessus de la porte d'une église, sous l'arc du portail ?","r":["Le trumeau","Le tympan","Le narthex","Le fronton"],"b":1,"a":"À Sainte-Foy de Conques, le tympan figure le Jugement dernier, avec le Christ au centre.","c":"Arts & lettres","d":3},{"id":"p4zmzm5u","t":"Quel fleuve traverse La Nouvelle-Orléans avant de se jeter dans le golfe du Mexique ?","r":["Missouri","Mississippi","Colorado","Rio Grande"],"b":1,"a":"Son nom vient d'un mot algonquin signifiant « grand fleuve ».","c":"Géographie","d":2},{"id":"y43g7ygh","t":"Quel cervidé d'Europe se reconnaît à ses bois aplatis en palette et à son pelage souvent tacheté de blanc ?","r":["Le chevreuil","Le cerf élaphe","Le renne","Le daim"],"b":3,"a":"Le daim est souvent élevé dans les parcs et les domaines, où sa robe tachetée le rend très reconnaissable.","c":"Nature","d":3},{"id":"628a9j73","t":"Dans quelle ville suisse se dresse le palais des Nations, ancien siège de la Société des Nations ?","r":["Berne","Zurich","Genève","Lausanne"],"b":2,"a":"Construit dans les années 1930, il abrite aujourd'hui l'office des Nations unies en Europe.","c":"Géographie","d":3},{"id":"kc3jvd6m","t":"Dans quelle ville américaine se déroule chaque Thanksgiving le défilé de Macy's et ses ballons géants ?","r":["Chicago","Boston","New York","Washington"],"b":2,"a":"Le défilé a eu lieu pour la première fois en 1924, organisé par des employés du grand magasin.","c":"Autour de la fête","d":3},{"id":"i6rqp4wx","t":"Quel organisme est chargé de la collecte du sang des donneurs en France ?","r":["L'Établissement français du sang","L'Agence de la biomédecine","Santé publique France","La Croix-Rouge française"],"b":0,"a":"L'EFS collecte, prépare et distribue les produits sanguins aux hôpitaux et aux cliniques.","c":"Culture générale","d":2},{"id":"77zwwgyk","t":"Dans le roman de Gaston Leroux paru en 1910, quel édifice parisien est hanté par le Fantôme de l'Opéra ?","r":["Palais Garnier","Opéra Bastille","Opéra-Comique","Théâtre du Châtelet"],"b":0,"a":"Le lac souterrain du roman a une base réelle : sous le Palais Garnier, une vaste citerne d'eau existe vraiment.","c":"Autour de la fête","d":3},{"id":"36gxcqgj","t":"Quel petit oiseau jaune est souvent élevé en cage pour son joli chant ?","r":["Le moineau","Le canari","Le pigeon","Le merle"],"b":1,"a":"Le canari domestique descend du serin des Canaries, un oiseau sauvage des îles atlantiques dont il porte le nom.","c":"Nature","d":1},{"id":"jfdchj68","t":"Combien de jours compte le mois d'août ?","r":["30","29","28","31"],"b":3,"a":"Juillet et août se suivent avec 31 jours chacun, comme décembre et janvier.","c":"Culture générale","d":2},{"id":"sjrhcens","t":"Quel est le prénom du philosophe Rousseau, auteur du Contrat social ?","r":["Jean-Jacques","Jean-Baptiste","Jean-Paul","Jean-Pierre"],"b":0,"a":"Né à Genève, Rousseau signait volontiers ses ouvrages « citoyen de Genève ».","c":"Arts & lettres","d":2},{"id":"hya99fzd","t":"Quelle reine de Castille finance avec son époux le premier voyage de Christophe Colomb, en 1492 ?","r":["Jeanne la Folle","Blanche de Castille","Catherine d'Aragon","Isabelle la Catholique"],"b":3,"a":"Cette même année 1492, les souverains espagnols prennent Grenade, dernier royaume musulman de la péninsule.","c":"Histoire","d":3},{"id":"a20pnm25","t":"Quel oiseau de proie figure sur le grand sceau des États-Unis ?","r":["L'aigle royal","Le pygargue à tête blanche","Le condor des Andes","Le faucon pèlerin"],"b":1,"a":"Sur le sceau, il tient dans ses serres un rameau d'olivier et des flèches.","c":"Culture générale","d":2},{"id":"v9une21j","t":"Quel est le prénom du shérif Hopper, chef de la police d'Hawkins dans « Stranger Things » (2016) ?","r":["Jim","Bob","Steve","Billy"],"b":0,"a":"Le shérif est joué par l'acteur américain David Harbour.","c":"Cinéma & séries","d":3},{"id":"c8cw0d6v","t":"De quel pays la marque automobile Jaguar est-elle originaire ?","r":["Italie","Royaume-Uni","États-Unis","Allemagne"],"b":1,"a":"Jaguar est née sous le nom de Swallow Sidecar Company, une entreprise qui fabriquait des side-cars pour motos.","c":"Culture générale","d":3},{"id":"qdvjvx5e","t":"Quelle crème fouettée et sucrée porte le nom d'un château de l'Oise ?","r":["La crème pâtissière","La crème anglaise","La crème Chantilly","La crème au beurre"],"b":2,"a":"La légende en attribue l'invention à Vatel, maître d'hôtel au château de Chantilly, mais rien ne le prouve.","c":"Cuisine","d":2},{"id":"orywvb3k","t":"Quel jouet fait de deux disques reliés par un axe monte et descend le long d'une ficelle ?","r":["Le diabolo","Le bilboquet","Le yo-yo","La toupie"],"b":2,"a":"Il fut à la mode en France à la fin du XVIIIe siècle sous le nom d'« émigrette ».","c":"Jeux & pop culture","d":1},{"id":"wx34m0s2","t":"Qui a réalisé le film « Babel », sorti en 2006 ?","r":["Alfonso Cuarón","Alejandro Amenábar","Pedro Almodóvar","Alejandro González Iñárritu"],"b":3,"a":"Le film entremêle plusieurs histoires qui se déroulent au Maroc, aux États-Unis, au Mexique et au Japon, avec notamment Brad Pitt et Cate Blanchett.","c":"Cinéma & séries","d":3},{"id":"ffghy692","t":"Quel chef a installé à l'Hôtel de Paris, à Monaco, le restaurant Le Louis XV, triplement étoilé ?","r":["Joël Robuchon","Alain Ducasse","Guy Savoy","Pierre Gagnaire"],"b":1,"a":"Il a obtenu ses trois étoiles quelques années après l'ouverture du restaurant, en 1987.","c":"Cuisine","d":3},{"id":"7wu68y8k","t":"Dans quelle discipline Sébastien Loeb a-t-il été neuf fois champion du monde ?","r":["Formule 1","Moto GP","Rallye","Motocross"],"b":2,"a":"Avant le sport automobile, Sébastien Loeb a pratiqué la gymnastique à haut niveau en Alsace.","c":"Sport","d":1},{"id":"gj2291mp","t":"Qui a réalisé le film « Retour vers le futur », sorti en 1985 ?","r":["Robert Zemeckis","Kevin Costner","Mel Gibson","Gus Van Sant"],"b":0,"a":"Michael J. Fox y joue Marty McFly, qui voyage dans le temps à bord d'une DeLorean.","c":"Cinéma & séries","d":3},{"id":"zixk322w","t":"Quel jouet, fait de boules qui coulissent sur des tiges, aide les enfants à apprendre à compter ?","r":["Le boulier","Le tangram","Le mobile","Le jeu de quilles"],"b":0,"a":"Le boulier n'est pas qu'un jouet : en Asie, des commerçants calculaient très vite avec lui, bien avant les calculatrices.","c":"Jeux & pop culture","d":2},{"id":"ydg7eruf","t":"Près de son embouchure, quel fleuve d'Afrique de l'Ouest baigne la ville de Saint-Louis ?","r":["Le Niger","La Gambie","Le Sénégal","La Volta"],"b":2,"a":"Saint-Louis a été la capitale de la colonie du Sénégal, puis de l'Afrique-Occidentale française, avant Dakar.","c":"Géographie","d":3},{"id":"lk6um2sx","t":"La levure qui fait lever le pain et fermenter la bière est un être vivant de quel groupe ?","r":["Les bactéries","Les algues","Les champignons","Les mousses"],"b":2,"a":"Un seul gramme de levure fraîche contient des milliards de cellules.","c":"Nature","d":3},{"id":"r81x2txl","t":"Quel signe du zodiaque correspond à une naissance le 9 janvier ?","r":["Sagittaire","Verseau","Capricorne","Poissons"],"b":2,"a":"Le Capricorne est représenté par une chèvre à queue de poisson, héritée de l'ancienne Babylonie.","c":"Autour de la fête","d":3},{"id":"kezaen4x","t":"Quelle est la plus grande île d'Afrique ?","r":["Madagascar","Bioko","Tenerife","Zanzibar"],"b":0,"a":"C'est la quatrième île du monde par sa superficie.","c":"Culture générale","d":3},{"id":"83jq37ry","t":"À quel âge Louis de Funès est-il mort, en 1983 ?","r":["61 ans","68 ans","74 ans","79 ans"],"b":1,"a":"Avant de percer au cinéma, Louis de Funès a longtemps gagné sa vie comme pianiste de bar.","c":"Cinéma & séries","d":3},{"id":"9f7lz8h9","t":"Quel légume, coupé en bâtonnets puis plongé dans l'huile bouillante, donne les frites ?","r":["Le panais","La pomme de terre","La courgette","Le céleri"],"b":1,"a":"La Belgique et la France se disputent depuis longtemps la paternité des frites.","c":"Cuisine","d":1},{"id":"9pduade7","t":"Quel appareil à pièces, installé dans les bars, permet de choisir le disque qui fera danser tout le monde ?","r":["Le juke-box","Le magnétophone","Le radio-réveil","Le baladeur"],"b":0,"a":"Le premier appareil de ce genre a été installé en 1889 dans un saloon de San Francisco.","c":"Autour de la fête","d":1},{"id":"cl6wz24m","t":"En quelle année Michael Schumacher devient-il champion du monde de Formule 1 pour la première fois ?","r":["1982","1994","2004","2012"],"b":1,"a":"Il décroche ce titre sur Benetton, d'un seul point devant Damon Hill, après un accrochage à Adélaïde.","c":"Sport","d":2},{"id":"hzzd5gfi","t":"Quel grand compositeur est devenu sourd, mais a continué de composer jusqu'à sa mort ?","r":["Mozart","Bach","Vivaldi","Beethoven"],"b":3,"a":"Ses carnets de conversation, où ses visiteurs écrivaient leurs questions, ont été conservés et renseignent sur ses dernières années.","c":"Musique","d":1},{"id":"j2cja44k","t":"Pendant le siège de Paris, en 1870-1871, quel animal rapportait des messages aux Parisiens encerclés ?","r":["Le pigeon voyageur","Le chien","Le faucon","Le cheval"],"b":0,"a":"Les dépêches étaient photographiées en tout petit sur des pellicules légères, puis agrandies et lues à l'arrivée.","c":"Histoire","d":3},{"id":"zl10wdnb","t":"Quel océan entoure le continent antarctique ?","r":["L'océan Arctique","L'océan Indien","L'océan Austral","L'océan Pacifique"],"b":2,"a":"Un puissant courant y fait le tour complet de la Terre d'ouest en est : le courant circumpolaire antarctique.","c":"Géographie","d":3},{"id":"63hmip0y","t":"Dans quelle ville se dresse la tour Eiffel ?","r":["Lyon","Bordeaux","Paris","Nice"],"b":2,"a":"Prévue pour durer vingt ans, elle fut conservée car elle servait d'antenne de radio.","c":"Géographie","d":1},{"id":"841r9a6b","t":"Combien de livres anglo-saxonnes compte un stone, unité qui sert encore à dire son poids au Royaume-Uni ?","r":["16 livres","12 livres","20 livres","14 livres"],"b":3,"a":"Au Royaume-Uni et en Irlande, on dit volontiers son poids en stones et en livres plutôt qu'en kilogrammes.","c":"Culture générale","d":3},{"id":"m0zij2hq","t":"Combien de jours le roquefort doit-il être affiné au minimum avant d'être vendu ?","r":["30 jours","60 jours","90 jours","150 jours"],"b":2,"a":"Il s'affine dans des caves naturelles aérées par des fissures de la roche, appelées fleurines.","c":"Cuisine","d":3},{"id":"0ug7tm6f","t":"De quel pays la marque automobile Toyota est-elle originaire ?","r":["Corée du Sud","Japon","Chine","États-Unis"],"b":1,"a":"Avant les voitures, l'entreprise de la famille Toyoda fabriquait des métiers à tisser automatiques.","c":"Culture générale","d":2},{"id":"117sjt5k","t":"Une prothèse de main dite myoélectrique se commande grâce à l'activité électrique de quoi ?","r":["Les muscles du moignon","Les os du bras","La peau de la paume","Le sang du patient"],"b":0,"a":"De petites électrodes posées sur la peau captent les contractions musculaires et les traduisent en mouvements de doigts.","c":"Culture générale","d":3},{"id":"t227x1gt","t":"De quels deux mots le mot-valise « courriel » est-il formé ?","r":["Courrier et électrique","Courrier et électronique","Coursier et électronique","Courrier et éclair"],"b":1,"a":"Le mot est venu du Québec, où l'Office de la langue française l'a diffusé pour remplacer l'anglais « e-mail ».","c":"Culture générale","d":2},{"id":"yj6ec1vy","t":"Que fait-on en fouettant vivement une vinaigrette pour disperser l'huile en fines gouttelettes ?","r":["On la clarifie","On la réduit","On l'émulsionne","On la décante"],"b":2,"a":"Une vinaigrette se sépare vite au repos : une pointe de moutarde aide l'émulsion à tenir plus longtemps.","c":"Cuisine","d":3},{"id":"ptuzzewx","t":"Quel dieu nordique espiègle est le père du loup Fenrir ?","r":["Loki","Odin","Tyr","Baldr"],"b":0,"a":"Il figure dans les Eddas, recueils islandais du XIIIe siècle.","c":"Culture générale","d":3},{"id":"o9y79o1c","t":"Sous quelle plante s'embrasse-t-on traditionnellement à minuit le soir du Nouvel An en France ?","r":["Le houx","Le gui","Le lierre","Le laurier"],"b":1,"a":"Les druides gaulois lui prêtaient des vertus sacrées ; le cri « Au gui l'an neuf » accompagnait son passage dans l'année nouvelle.","c":"Autour de la fête","d":2},{"id":"6vhulf3a","t":"Quel grand instrument à clavier, aux tuyaux parfois immenses, trouve-t-on dans beaucoup d'églises ?","r":["Le clavecin","L'orgue","Le piano","L'accordéon"],"b":1,"a":"L'orgue produit le son en envoyant de l'air dans ses tuyaux ; les plus grands en comptent plusieurs milliers.","c":"Musique","d":1},{"id":"0mdjov33","t":"Quel petit outil le médecin utilise-t-il pour frapper doucement sous le genou, et voir la jambe se lever toute seule ?","r":["Un diapason","Un marteau à réflexes","Un abaisse-langue","Un otoscope"],"b":1,"a":"Quand le tendon est frappé, la jambe se lève toute seule : ce réflexe passe par la moelle épinière, sans que le cerveau décide quoi que ce soit.","c":"Culture générale","d":2},{"id":"m28xofev","t":"Dans quelle pièce Molière jouait-il le soir où il est pris d'un malaise avant de mourir, en 1673 ?","r":["Le Misanthrope","Le Bourgeois gentilhomme","Le Malade imaginaire","Les Femmes savantes"],"b":2,"a":"Il meurt quelques heures après la représentation, le 17 février 1673.","c":"Arts & lettres","d":3},{"id":"sx4a7laq","t":"Quel dieu grec du vin et de la fête les Romains appelaient-ils Bacchus ?","r":["Dionysos","Apollon","Arès","Hermès"],"b":0,"a":"Les fêtes données en son honneur, les Dionysies, sont à l'origine du théâtre grec.","c":"Culture générale","d":3},{"id":"6uzcsas6","t":"Quelle est l'année de la découverte de la grotte de Lascaux, en Dordogne, par des adolescents ?","r":["1930","1940","1950","1925"],"b":1,"a":"Fermée au public en 1963 pour préserver ses peintures, elle se visite aujourd'hui grâce à des répliques.","c":"Histoire","d":3},{"id":"3cnfrq2y","t":"Quel écrivain américain a signé les romans dont est tirée la série « Game of Thrones » ?","r":["Patrick Rothfuss","George R. R. Martin","Terry Pratchett","Robert Jordan"],"b":1,"a":"La saga s'intitule « A Song of Ice and Fire » en anglais, et « Le Trône de fer » dans sa traduction française.","c":"Cinéma & séries","d":3},{"id":"2s49ur7t","t":"En quelle année Steve Jobs, Steve Wozniak et Ronald Wayne fondent-ils Apple ?","r":["1966","1976","1986","1996"],"b":1,"a":"Ronald Wayne a revendu sa part au bout de quelques jours, pour quelques centaines de dollars.","c":"Sciences","d":2},{"id":"i7jcri0i","t":"Quel aéronaute français a traversé la Manche en ballon en 1785, avec l'Américain John Jeffries ?","r":["Pilâtre de Rozier","Jean-Pierre Blanchard","Jacques Charles","Joseph Montgolfier"],"b":1,"a":"Leur ballon, à hydrogène, a failli tomber à la mer : ils ont dû jeter presque tout leur matériel pour atteindre la forêt de Guînes.","c":"Sciences","d":3},{"id":"r8saidai","t":"Quel pilote de Formule 1 était surnommé « le Professeur » pour son pilotage calculé ?","r":["Jacques Laffite","René Arnoux","Didier Pironi","Alain Prost"],"b":3,"a":"Sa rivalité avec Ayrton Senna, coéquipier chez McLaren en 1988 et 1989, reste l'une des plus célèbres de l'histoire du sport automobile.","c":"Sport","d":3},{"id":"fgyjg01k","t":"Quel petit animal marin a une tête qui rappelle celle d'un cheval et nage en position verticale ?","r":["La murène","L'hippocampe","La raie","Le poisson-lune"],"b":1,"a":"Malgré sa silhouette étrange, l'hippocampe est bien un poisson : il respire par des branchies.","c":"Nature","d":1},{"id":"3a1gjfwy","t":"Dans « La Reine des neiges » (2013), comment s'appelle la reine qui a le pouvoir de créer la glace ?","r":["Anna","Elsa","Aurore","Ariel"],"b":1,"a":"La chanson « Libérée, délivrée », que chante cette reine, a été traduite dans des dizaines de langues.","c":"Cinéma & séries","d":1},{"id":"tsgoo56b","t":"Sur le drapeau français, quelle couleur se trouve du côté du mât ?","r":["Le rouge","Le blanc","Le vert","Le bleu"],"b":3,"a":"Sur le pavillon de la marine, les trois bandes ont longtemps eu des largeurs inégales (le rouge plus large) pour paraître égales quand le drapeau flotte au vent.","c":"Géographie","d":1},{"id":"bd01bhgm","t":"Qui a réalisé le film « Eyes Wide Shut », sorti en 1999 ?","r":["Richard Donner","Stanley Kubrick","Sidney Lumet","Richard Attenborough"],"b":1,"a":"Le film met en scène Tom Cruise et Nicole Kidman, alors mariés à la ville.","c":"Cinéma & séries","d":3},{"id":"u4my2emh","t":"Comment appelle-t-on les petites billes de glace qui tombent parfois pendant un orage ?","r":["La neige","Le givre","La grêle","La rosée"],"b":2,"a":"Les grêlons grossissent en montant et en redescendant plusieurs fois dans le nuage d'orage, qui les couvre à chaque passage d'une nouvelle couche de glace.","c":"Sciences","d":1},{"id":"ourynll3","t":"Quel grand rapace est surnommé le « roi des oiseaux » ?","r":["Le vautour","Le faucon","L'aigle","Le hibou"],"b":2,"a":"L'aigle orne les blasons et étendards depuis l'Antiquité : les légions romaines marchaient déjà derrière une aigle.","c":"Nature","d":2},{"id":"g11s2a7p","t":"Quel coureur français des années 1990 était surnommé « Jaja » ?","r":["Richard Virenque","Luc Leblanc","Laurent Jalabert","Laurent Brochard"],"b":2,"a":"Sur le Tour de France, Jalabert a remporté le maillot vert puis, plus tard, le maillot à pois du meilleur grimpeur.","c":"Sport","d":3},{"id":"lrscgz2o","t":"Quelle monnaie utilise-t-on en Inde ?","r":["Le dinar","Le dirham","La roupie","Le baht"],"b":2,"a":"Le mot « roupie » vient du sanskrit « rupya », qui désigne l'argent frappé en pièces.","c":"Culture générale","d":2},{"id":"awnevn2n","t":"Comment s'appelle la plante carnivore qui jaillit des tuyaux dans Mario ?","r":["Plante Piranha","Plante Bulbe","Plante Cactus","Plante Tigre"],"b":0,"a":"Son nom vient du poisson carnivore d'Amérique du Sud.","c":"Jeux & pop culture","d":2},{"id":"s4fy5vcg","t":"Quel bijou se glisse autour d'un doigt de la main ?","r":["Un collier","Une bague","Une broche","Un bracelet"],"b":1,"a":"Dans de nombreux pays, l'alliance se porte à l'annulaire gauche : on disait autrefois qu'une veine reliait ce doigt au cœur.","c":"Jeux & pop culture","d":1},{"id":"1veme8rc","t":"Que mesure un baromètre ?","r":["La température de l'air","La pression atmosphérique","La vitesse du vent","L'humidité de l'air"],"b":1,"a":"Le premier baromètre, à mercure, a été mis au point par l'Italien Evangelista Torricelli en 1643.","c":"Sciences","d":2},{"id":"w9o0d1qs","t":"Quel jour l'Inde célèbre-t-elle sa fête de l'Indépendance ?","r":["26 janvier","15 août","2 octobre","14 août"],"b":1,"a":"Chaque année, le Premier ministre hisse le drapeau au Fort Rouge de Delhi et prononce un discours à la nation.","c":"Autour de la fête","d":3},{"id":"kbdt3tvl","t":"Quel jeu Mario de 2007 sur Wii envoie le plombier de planète en planète dans l'espace ?","r":["Super Mario Sunshine","Super Mario Odyssey","Super Mario 3D World","Super Mario Galaxy"],"b":3,"a":"Le jeu joue avec la gravité sur de petites planètes sphériques, et se pilote en partie en agitant la télécommande de la Wii.","c":"Jeux & pop culture","d":3},{"id":"uo436kgy","t":"En 2023, quelle équipe devient la première à remporter quatre fois la Coupe du monde de rugby ?","r":["Nouvelle-Zélande","Afrique du Sud","Australie","Angleterre"],"b":1,"a":"La finale se joue au Stade de France et se décide à un seul point d'écart.","c":"Sport","d":1},{"id":"gbl6wxwi","t":"Quelle discipline olympique se pratique avec un fleuret, une épée ou un sabre ?","r":["Judo","Escrime","Tir à l'arc","Taekwondo"],"b":1,"a":"L'escrime fait partie des rares sports présents à toutes les éditions des Jeux modernes depuis 1896.","c":"Sport","d":1},{"id":"34avph4b","t":"Comment dit-on « anniversaire » en anglais ?","r":["Holiday","Weekend","Present","Birthday"],"b":3,"a":"Le mot associe « birth », la naissance, et « day », le jour.","c":"Autour de la fête","d":1},{"id":"kbthaghp","t":"Que veut dire, en latin, le mot « veto » ?","r":["Je vote","J'interdis","Je décide","J'accepte"],"b":1,"a":"Dans la Rome antique, les tribuns de la plèbe pouvaient bloquer une décision en prononçant ce simple mot.","c":"Culture générale","d":3},{"id":"zdr9rcum","t":"Quel outil le maçon utilise-t-il pour étaler le mortier entre les briques ?","r":["Le fil à plomb","Le rabot","La truelle","La scie"],"b":2,"a":"Le mot truelle vient du latin trulla, qui désignait une petite louche.","c":"Arts & lettres","d":2},{"id":"nuf0tys3","t":"Quel peuple d'Italie centrale, à la langue encore mal comprise, dominait la Toscane avant l'essor de Rome ?","r":["Les Sabins","Les Samnites","Les Étrusques","Les Latins"],"b":2,"a":"Les Romains leur ont emprunté des insignes du pouvoir, comme les faisceaux des licteurs.","c":"Histoire","d":3},{"id":"3l8qmxom","t":"Quel acteur joue le surveillant Clément Mathieu dans « Les Choristes » (2004) ?","r":["Gérard Depardieu","Christian Clavier","Gérard Jugnot","Daniel Auteuil"],"b":2,"a":"Les chœurs du film sont chantés par les Petits Chanteurs de Saint-Marc ; le jeune soliste, Jean-Baptiste Maunier, y a été révélé.","c":"Cinéma & séries","d":2},{"id":"wc1adi5s","t":"Quelle ville est la préfecture de la Gironde ?","r":["Arcachon","Bordeaux","Libourne","Mérignac"],"b":1,"a":"Bordeaux est surnommée le « port de la Lune » : la Garonne y dessine un croissant devant les quais.","c":"Géographie","d":1},{"id":"mu5i6t7w","t":"Comment nomme-t-on le fait de n'avoir qu'un seul conjoint ?","r":["La polyandrie","La monogamie","La polygynie","L'endogamie"],"b":1,"a":"Le mot vient du grec monos, « seul », et gamos, « mariage ».","c":"Autour de la fête","d":2},{"id":"dzvozg5x","t":"Comment appelle-t-on la femelle du cerf ?","r":["La daine","La chevrette","La laie","La biche"],"b":3,"a":"Le cerf perd ses bois chaque année et les refait ; la biche, elle, n'en porte jamais.","c":"Nature","d":2},{"id":"wodbb23t","t":"Dans « Vaiana, la légende du bout du monde » (2016), quel animal est Heihei, le compagnon un peu bête de l'héroïne ?","r":["Un cochon","Un perroquet","Un coq","Un crabe"],"b":2,"a":"Dans la version originale, Heihei est doublé par Alan Tudyk, voix récurrente des films Disney.","c":"Cinéma & séries","d":3},{"id":"pf62il1k","t":"Sur quelle planète glacée les rebelles ont-ils leur base au début de « L'Empire contre-attaque » ?","r":["Dagobah","Hoth","Bespin","Endor"],"b":1,"a":"Les scènes de neige de Hoth ont été tournées en Norvège, sur un glacier, durant l'hiver 1979.","c":"Cinéma & séries","d":3},{"id":"6jcaa261","t":"De quelle couleur est la « boîte noire » d'un avion ?","r":["Noire","Rouge","Jaune","Orange"],"b":3,"a":"Sa couleur vive aide à la retrouver dans les débris après un accident.","c":"Culture générale","d":2},{"id":"zsdaicak","t":"Quel compositeur a écrit l'opéra « Così fan tutte », créé à Vienne en 1790 ?","r":["Wolfgang Amadeus Mozart","Antonio Salieri","Joseph Haydn","Christoph Willibald Gluck"],"b":0,"a":"Son livret est de Lorenzo Da Ponte, qui avait déjà écrit pour Mozart ceux des « Noces de Figaro » et de « Don Giovanni ».","c":"Musique","d":3},{"id":"3ss5ijj2","t":"En 1958, la Chine adopte un système officiel de transcription de ses caractères en lettres latines. Comment s'appelle-t-il ?","r":["Le wade-giles","Le romaji","Le hangeul","Le pinyin"],"b":3,"a":"C'est le pinyin qui écrit « Beijing » là où le français dit Pékin.","c":"Culture générale","d":3},{"id":"owox8aqr","t":"En quelle année la Coupe des clubs champions européens prend-elle le nom de Ligue des champions ?","r":["1988","1995","1990","1992"],"b":3,"a":"Son hymne, joué avant chaque match, est une adaptation d'une œuvre de Haendel signée Tony Britten.","c":"Sport","d":2},{"id":"7aylgrox","t":"Quelle alliance militaire est fondée en 1949 par les États-Unis et leurs alliés d'Europe de l'Ouest ?","r":["Le pacte de Varsovie","L'OTAN","L'OTASE","L'ONU"],"b":1,"a":"Le traité de l'Atlantique Nord est signé à Washington ; le bloc soviétique répond en 1955 par le pacte de Varsovie.","c":"Histoire","d":3},{"id":"duouahn4","t":"Comment dit-on « ombre » en espagnol ?","r":["sol","luz","sombra","nube"],"b":2,"a":"Le sombrero, chapeau à larges bords, protège du soleil en faisant de l'ombre sur le visage.","c":"Culture générale","d":3},{"id":"efxfamaf","t":"Quel footballeur portugais est surnommé « CR7 » ?","r":["Lionel Messi","Cristiano Ronaldo","Neymar","Kylian Mbappé"],"b":1,"a":"Le surnom associe les initiales du joueur et le numéro 7 qu'il porte depuis ses années à Manchester United.","c":"Jeux & pop culture","d":1},{"id":"sx3qljnq","t":"Combien de points rapporte un lancer franc réussi au basket ?","r":["2 points","3 points","1 point","5 points"],"b":2,"a":"Un lancer franc se tire sans opposition, depuis une ligne située à 4,60 m du plan du panneau.","c":"Sport","d":2},{"id":"mstbyde4","t":"Dans quel pays se trouve la ville de Barcelone ?","r":["Espagne","Portugal","Italie","France"],"b":0,"a":"Barcelone a accueilli les Jeux olympiques d'été de 1992.","c":"Géographie","d":1},{"id":"vlzhbl2z","t":"Quelle expression française correspond à « to kill two birds with one stone » ?","r":["Faire d'une pierre deux coups","Avoir deux fers au feu","Tuer le temps","Courir deux lièvres à la fois"],"b":0,"a":"La version anglaise est attestée depuis le XVIIe siècle ; le français remplace les oiseaux par des coups.","c":"Culture générale","d":2},{"id":"2al8ff0m","t":"Quel ballet de Tchaïkovski, créé en 1890, met en scène la princesse Aurore ?","r":["Giselle","Coppélia","La Belle au bois dormant","Le Lac des cygnes"],"b":2,"a":"Le ballet suit le conte de Charles Perrault, et sa chorégraphie originale est de Marius Petipa.","c":"Arts & lettres","d":3},{"id":"xy6luvch","t":"Quel compositeur a écrit la célèbre « Marche funèbre », troisième mouvement d'une de ses sonates pour piano ?","r":["Franz Schubert","Robert Schumann","Franz Liszt","Frédéric Chopin"],"b":3,"a":"Cette marche a été jouée aux obsèques de son auteur, à l'église de la Madeleine à Paris, en 1849.","c":"Musique","d":3},{"id":"sc83vaj6","t":"Quel jeune acteur joue Kevin dans le film « Maman, j'ai raté l'avion ! » ?","r":["Elijah Wood","Haley Joel Osment","Macaulay Culkin","Jonathan Lipnicki"],"b":2,"a":"Michael Jackson, dont Macaulay Culkin était un proche, l'a fait apparaître dans le clip de « Black or White ».","c":"Autour de la fête","d":2},{"id":"ahduypr0","t":"Combien d'États ont fait sécession pour former les États confédérés d'Amérique pendant la guerre de Sécession ?","r":["7","11","20","25"],"b":1,"a":"La capitale de la Confédération fut d'abord Montgomery, en Alabama, avant d'être transférée à Richmond, en Virginie.","c":"Histoire","d":3},{"id":"szvkh27u","t":"Quel président de la République quitte l'Élysée en 1969, après avoir perdu un référendum qu'il avait lié à son maintien ?","r":["Georges Pompidou","Charles de Gaulle","René Coty","Valéry Giscard d'Estaing"],"b":1,"a":"Il se retire aussitôt à Colombey-les-Deux-Églises, où il meurt en 1970.","c":"Histoire","d":2},{"id":"0fab7ber","t":"Vous placez 100 € à 10 % d'intérêt simple par an. Combien avez-vous au bout de deux ans ?","r":["110 €","120 €","121 €","200 €"],"b":1,"a":"Avec des intérêts composés, on obtiendrait 121 €, car les intérêts de la première année rapportent eux-mêmes des intérêts.","c":"Culture générale","d":2},{"id":"4cvo76jd","t":"Quel palais est la principale résidence londonienne du monarque britannique ?","r":["Le château de Windsor","Le palais de Kensington","Le palais de Holyrood","Le palais de Buckingham"],"b":3,"a":"La reine Victoria fut la première souveraine à faire de Buckingham sa résidence, dès son accession au trône en 1837.","c":"Culture générale","d":2},{"id":"s606gtyd","t":"Combien d'épisodes compte au total la série Breaking Bad ?","r":["75 épisodes","50 épisodes","62 épisodes","100 épisodes"],"b":2,"a":"La série a été créée par Vince Gilligan et suit un professeur de chimie devenu fabricant de drogue.","c":"Cinéma & séries","d":3},{"id":"k3ldcrg4","t":"Quel petit mammifère creuse des galeries sous les jardins et laisse des monticules de terre derrière lui ?","r":["Le lapin","La taupe","Le hérisson","L'écureuil"],"b":1,"a":"La taupe vit presque toujours sous terre et se nourrit surtout de vers de terre, qu'elle peut stocker vivants dans ses galeries.","c":"Nature","d":1},{"id":"m2eu8sg2","t":"Quelle ville est la préfecture de la Dordogne ?","r":["Bergerac","Sarlat-la-Canéda","Périgueux","Nontron"],"b":2,"a":"Sa cathédrale Saint-Front est surmontée de cinq coupoles.","c":"Géographie","d":3},{"id":"2pz6cmxu","t":"Dans une discussion en ligne, que signifie à l'origine l'abréviation anglaise « LOL » ?","r":["Lots of love","Laughing out loud","Look over left","Lost on line"],"b":1,"a":"En français, on l'a parfois traduite par « MDR », pour « mort de rire ».","c":"Jeux & pop culture","d":2},{"id":"krbarwfj","t":"Quelle ville est le chef-lieu de la région Nouvelle-Aquitaine ?","r":["Poitiers","Limoges","Bordeaux","La Rochelle"],"b":2,"a":"La Nouvelle-Aquitaine est née en 2016 de la fusion de l'Aquitaine, du Limousin et de Poitou-Charentes.","c":"Géographie","d":3},{"id":"w0nkvm2p","t":"Comment appelle-t-on une phrase comme « Cette phrase est fausse », qui semble à la fois vraie et fausse ?","r":["Pléonasme","Tautologie","Oxymore","Paradoxe"],"b":3,"a":"Ce casse-tête, dit paradoxe du menteur, est attribué au philosophe grec Eubulide de Milet, au IVe siècle avant J.-C.","c":"Arts & lettres","d":2},{"id":"y9n6s1ca","t":"De quel pays vient la marque Schleich, fabricante de figurines d'animaux et de Schtroumpfs ?","r":["Suisse","Autriche","Pays-Bas","Allemagne"],"b":3,"a":"Schleich fabrique des figurines de Schtroumpfs depuis les années 1960.","c":"Jeux & pop culture","d":3},{"id":"3vjkdm42","t":"Quelle veste d'hiver, rembourrée de duvet ou de fibres, gonfle en boudins matelassés ?","r":["La doudoune","Le blazer","Le gilet","Le trench"],"b":0,"a":"Le duvet des oiseaux emprisonne de l'air entre ses fibres : c'est cet air immobile qui garde la chaleur du corps.","c":"Jeux & pop culture","d":1},{"id":"347xk33k","t":"Une personne née un 1er janvier a quel signe dans l'astrologie occidentale ?","r":["Verseau","Sagittaire","Capricorne","Poissons"],"b":2,"a":"Le Capricorne court environ du 22 décembre au 20 janvier : il est le signe des fêtes de fin d'année.","c":"Autour de la fête","d":3},{"id":"xz4jolzn","t":"Jusqu'à quel âge, en années, la baleine boréale peut-elle vivre ?","r":["40 ans","80 ans","200 ans","1 000 ans"],"b":2,"a":"Des chasseurs inuits ont trouvé dans certaines baleines boréales des pointes de harpon fabriquées au XIXe siècle.","c":"Nature","d":2},{"id":"55qfcct5","t":"Quel est le nom civil de Batman ?","r":["Clark Kent","Peter Parker","Tony Stark","Bruce Wayne"],"b":3,"a":"Batman est apparu pour la première fois en 1939, dans le numéro 27 de la revue de bandes dessinées « Detective Comics ».","c":"Cinéma & séries","d":1},{"id":"2q3o985s","t":"Combien d'années dure le chantier de l'opéra de Sydney, d'abord prévu pour quatre ans ?","r":["10 ans","20 ans","14 ans","8 ans"],"b":2,"a":"L'architecte danois Jørn Utzon a quitté le chantier en 1966 et n'a jamais vu l'édifice terminé.","c":"Arts & lettres","d":3},{"id":"w96qzrzh","t":"Comment dit-on « fais ! » à une personne que l'on tutoie, avec le verbe « hacer » ?","r":["haz","hace","hagas","hazte"],"b":0,"a":"Plusieurs impératifs familiers sont très courts : « ven, haz, di, pon, ten, sal, ve ».","c":"Culture générale","d":3},{"id":"kzmsuqm7","t":"Quel instrument de la famille des cuivres change de note grâce à une coulisse que le musicien fait glisser ?","r":["La trompette","Le cor","Le tuba","Le trombone"],"b":3,"a":"Le mot « trombone » vient de l'italien et signifie « grande trompette ». L'attache de bureau qui porte le même nom n'a rien à voir avec l'instrument.","c":"Musique","d":2},{"id":"wf89eemx","t":"Quelle remontée mécanique tire le skieur, resté debout sur ses skis, grâce à une perche ?","r":["Le télésiège","La télécabine","Le téléski","Le téléphérique"],"b":2,"a":"Les skieurs surnomment familièrement le téléski le « tire-fesses ».","c":"Sport","d":2},{"id":"dta1as6v","t":"Quel pays occupe l'extrémité occidentale de l'Europe continentale ?","r":["L'Espagne","La France","Le Portugal","Le Danemark"],"b":2,"a":"Le cap da Roca, près de Lisbonne, est le point le plus occidental de l'Europe continentale.","c":"Géographie","d":3},{"id":"polgl7dy","t":"Dans quelle comédie de Molière le héros s'appelle-t-il Alceste ?","r":["L'Avare","Tartuffe","Dom Juan","Le Misanthrope"],"b":3,"a":"Alceste y est épris de la coquette Célimène.","c":"Arts & lettres","d":3},{"id":"mmy6k9hy","t":"En quelle année Twitter a-t-il été rebaptisé X par Elon Musk ?","r":["2021","2022","2023","2024"],"b":2,"a":"Le petit oiseau bleu, emblème du réseau depuis ses débuts, a alors laissé la place à une simple lettre X blanche sur fond noir.","c":"Jeux & pop culture","d":2},{"id":"o7mej4gb","t":"Quelle forme géométrique sert de logo à la marque automobile Renault ?","r":["Un ovale","Un losange","Un triangle","Un hexagone"],"b":1,"a":"On surnomme souvent Renault « la marque au losange ». Le logo a été redessiné à plusieurs reprises au fil du XXe siècle.","c":"Culture générale","d":3},{"id":"z5r8wway","t":"Combien de pays indépendants sont nés de la dissolution de l'URSS en 1991 ?","r":["12","18","21","15"],"b":3,"a":"Les trois pays baltes avaient proclamé leur indépendance avant la dissolution finale de décembre 1991.","c":"Géographie","d":3},{"id":"ed8dj7dk","t":"Combien de lettres compte l'alphabet hawaïen ?","r":["20","13","17","24"],"b":1,"a":"L'une de ses lettres, l'ʻokina, note un coup de glotte, comme dans le nom même de « Hawaiʻi ».","c":"Culture générale","d":3},{"id":"2y3zuvi1","t":"En avril 1912, quel paquebot était, lors de son voyage inaugural, le plus grand navire du monde ?","r":["Lusitania","Mauretania","Titanic","Normandie"],"b":2,"a":"Il partait de Southampton pour New York et transportait plus de deux mille personnes à son bord.","c":"Culture générale","d":3},{"id":"3katr729","t":"Combien de côtés compte un hexagone ?","r":["5","6","7","8"],"b":1,"a":"La France métropolitaine est surnommée l'Hexagone, car son contour rappelle vaguement cette figure.","c":"Sciences","d":2},{"id":"w0lm4t26","t":"Quel nombre suit dans la suite 1, 1, 2, 3, 5, 8, 13 ?","r":["20","22","21","24"],"b":2,"a":"Cette suite doit son nom à Leonardo Fibonacci, qui l'a présentée en 1202 avec un problème de lapins.","c":"Sciences","d":2},{"id":"es8cw0tr","t":"Combien de planètes du système solaire sont plus petites que la Terre ?","r":["1","2","3","4"],"b":2,"a":"Vénus est presque une jumelle de la Terre, avec un diamètre d'environ 95 % du sien.","c":"Sciences","d":3},{"id":"k3ciarq1","t":"Quelle danseuse néerlandaise est fusillée à Vincennes en octobre 1917, accusée d'espionnage pour l'Allemagne ?","r":["Isadora Duncan","Mata Hari","Louise de Bettignies","Marthe Richard"],"b":1,"a":"Née Margaretha Zelle, elle avait choisi un nom de scène malais qui signifie « œil du jour », c'est-à-dire le soleil.","c":"Histoire","d":2},{"id":"mcbynnk9","t":"En quelle année le tout premier prix Nobel de littérature est-il décerné ?","r":["1851","1880","1901","1951"],"b":2,"a":"Le premier lauréat est le poète français Sully Prudhomme, préféré à Léon Tolstoï, ce qui fit scandale.","c":"Arts & lettres","d":2},{"id":"z9kctmiq","t":"Quel grand instrument à cordes pincées, souvent placé entre les mains des anges, trouve-t-on dans l'orchestre ?","r":["La harpe","La guitare","Le luth","La mandoline"],"b":0,"a":"La harpe est l'emblème de l'Irlande : elle figure sur les pièces en euros frappées par le pays.","c":"Musique","d":2},{"id":"oeogx9w7","t":"Quel acteur britannique incarne James Bond dans « Le monde ne suffit pas » (1999) ?","r":["Roger Moore","Pierce Brosnan","Timothy Dalton","Daniel Craig"],"b":1,"a":"Il y joue Bond pour la troisième fois, après « GoldenEye » et « Demain ne meurt jamais ».","c":"Cinéma & séries","d":2},{"id":"h0f21ju1","t":"Quel petit animal virtuel de poche, lancé en 1996 au Japon, fallait-il nourrir et câliner pour qu'il grandisse ?","r":["Le Tamagotchi","Le Furby","Le Digimon","Le Nintendogs"],"b":0,"a":"Son nom mêle « tamago », l'œuf en japonais, et « watch », la montre.","c":"Jeux & pop culture","d":2},{"id":"ljh1azd1","t":"Qui a écrit le roman « L'Insoutenable Légèreté de l'être », publié en 1984 ?","r":["Milan Kundera","Ismaïl Kadaré","Gabriel García Márquez","Umberto Eco"],"b":0,"a":"L'action se déroule en grande partie à Prague, au moment du Printemps de 1968. Le roman a été adapté au cinéma en 1988 avec Daniel Day-Lewis.","c":"Arts & lettres","d":3},{"id":"3ip6zzls","t":"Dans quel pays le Mékong forme-t-il son delta avant de se jeter dans la mer ?","r":["Cambodge","Viêt Nam","Thaïlande","Laos"],"b":1,"a":"Né sur le plateau tibétain, il traverse ou longe six pays : la Chine, la Birmanie, le Laos, la Thaïlande, le Cambodge et le Viêt Nam.","c":"Géographie","d":3},{"id":"9jow4dow","t":"Quel journaliste a présenté pendant des années l'émission « Des racines et des ailes » ?","r":["Jean-Pierre Pernaut","Patrick de Carolis","Stéphane Bern","Frédéric Taddeï"],"b":1,"a":"L'émission mêle patrimoine et reportages en France et à l'étranger.","c":"Jeux & pop culture","d":3},{"id":"mgiy6ioc","t":"Quelle planète porte le nom du dieu romain de la mer ?","r":["Uranus","Saturne","Mercure","Neptune"],"b":3,"a":"Son symbole astronomique est le trident, l'attribut du dieu des mers.","c":"Sciences","d":3},{"id":"lnpzwnlk","t":"Dans les légendes bretonnes, que sont les korrigans ?","r":["Des géants","Des lutins","Des sirènes","Des loups-garous"],"b":1,"a":"On les dit amateurs de rondes nocturnes autour des dolmens, et prompts à jouer des tours aux passants.","c":"Culture générale","d":3},{"id":"m78ku0wc","t":"Comment appelle-t-on les petits corps rocheux qui tournent autour du Soleil sans être des planètes ?","r":["Des astéroïdes","Des quasars","Des pulsars","Des nébuleuses"],"b":0,"a":"Certains astéroïdes ont leurs propres petites lunes, comme Ida, accompagnée de Dactyle.","c":"Sciences","d":3},{"id":"3pf4684e","t":"En 2024 à Paris, sur quel fleuve les délégations défilent-elles en bateau lors de la cérémonie d'ouverture des Jeux ?","r":["La Loire","La Seine","Le Rhône","La Garonne"],"b":1,"a":"C'était la première cérémonie d'ouverture des Jeux d'été organisée hors d'un stade.","c":"Sport","d":1},{"id":"b5d4nyc6","t":"Sur quelle syllabe tombe l'accent tonique de « mariposa » ?","r":["La première","L'avant-dernière","La dernière","L'antépénultième"],"b":1,"a":"Sans accent écrit, un mot terminé par une voyelle, un « n » ou un « s » est accentué sur l'avant-dernière syllabe.","c":"Culture générale","d":3},{"id":"st0f8loq","t":"Quelle ville est la préfecture du Cantal ?","r":["Saint-Flour","Mauriac","Murat","Aurillac"],"b":3,"a":"Gerbert d'Aurillac, devenu pape en l'an 999 sous le nom de Sylvestre II, en était originaire.","c":"Géographie","d":3},{"id":"cv5zae1c","t":"Comment traduit-on en français « deep learning », une technique d'intelligence artificielle ?","r":["Apprentissage profond","Calcul quantique","Réalité augmentée","Fouille de données"],"b":0,"a":"Le Français Yann LeCun a partagé le prix Turing 2018 avec Geoffrey Hinton et Yoshua Bengio pour leurs travaux sur ces réseaux de neurones.","c":"Sciences","d":3},{"id":"a8td1zlu","t":"Qui a peint « Golconde » en 1953, où des hommes en chapeau melon flottent devant des immeubles ?","r":["René Magritte","Amedeo Modigliani","Salvador Dalí","Norman Rockwell"],"b":0,"a":"Le titre fait référence à une ancienne ville d'Inde. Le tableau est l'un des plus célèbres du surréalisme belge.","c":"Arts & lettres","d":3},{"id":"pzuhkgr2","t":"Quel poète associe des couleurs aux voyelles : « A noir, E blanc, I rouge, U vert, O bleu » ?","r":["Charles Baudelaire","Stéphane Mallarmé","Arthur Rimbaud","Gérard de Nerval"],"b":2,"a":"Ce sonnet, intitulé Voyelles, est un exemple de la recherche de correspondances entre les sens.","c":"Arts & lettres","d":3},{"id":"juvl492w","t":"Quelle ville est la préfecture du Tarn ?","r":["Castres","Gaillac","Mazamet","Albi"],"b":3,"a":"Sa cathédrale Sainte-Cécile, en brique rouge, est inscrite à l'Unesco avec la cité épiscopale depuis 2010.","c":"Géographie","d":3},{"id":"5zxlwbmc","t":"En décembre 1941, quelle base navale américaine du Pacifique est attaquée par l'aviation japonaise ?","r":["Midway","Pearl Harbor","Guam","Manille"],"b":1,"a":"Le lendemain, 8 décembre, les États-Unis déclarent la guerre au Japon.","c":"Histoire","d":1},{"id":"2x6ep0e3","t":"Quel nom, suivi du numéro d'un département, portent les hélicoptères de la Sécurité civile ?","r":["Phénix","Griffon","Dragon","Faucon"],"b":2,"a":"Ces appareils sont basés dans plusieurs villes et servent aux secours en montagne, en mer et à l'évacuation de blessés graves.","c":"Culture générale","d":3},{"id":"rmw5wjcq","t":"Quelle victoire du 2 décembre 1805, surnommée la « bataille des Trois Empereurs », est le chef-d'œuvre de Napoléon ?","r":["Iéna","Wagram","Austerlitz","Eylau"],"b":2,"a":"Elle oppose les Français aux armées russe et autrichienne.","c":"Histoire","d":3},{"id":"bq1r7g3s","t":"Comment appelle-t-on une vidéo où l'on filme le déballage d'un produit neuf ?","r":["Un tutoriel","Un haul","Un unboxing","Un vlog"],"b":2,"a":"Les vidéos de déballage de jouets ont fait la fortune de plusieurs chaînes pour enfants sur YouTube.","c":"Jeux & pop culture","d":3},{"id":"o7cbc0qk","t":"Quel nom portent les deux sondes américaines lancées en 1977 qui emportent un disque doré de sons terrestres ?","r":["Pioneer","Voyager","Viking","Mariner"],"b":1,"a":"En 2012, Voyager 1 est devenue le premier engin humain à quitter l'héliosphère, la bulle du vent solaire.","c":"Histoire","d":3},{"id":"opo3qmi7","t":"Quel est le vrai nom du chanteur belge Stromae ?","r":["Paul Van Damme","Pierre Van Haver","Paul Vandaele","Paul Van Haver"],"b":3,"a":"Stromae est un verlan de « maestro », mot qui le désigne comme chef d'orchestre de ses morceaux.","c":"Jeux & pop culture","d":3},{"id":"6uosgul9","t":"Dans la pièce d'Edmond Rostand, quel cadet Cyrano aide-t-il à séduire Roxane en lui prêtant sa plume ?","r":["Le comte de Guiche","Christian de Neuvillette","Ragueneau","Le Bret"],"b":1,"a":"La pièce a été créée en décembre 1897 au théâtre de la Porte-Saint-Martin et a triomphé dès la première soirée.","c":"Autour de la fête","d":3},{"id":"vhxxiiwx","t":"De quel continent la pintade est-elle originaire ?","r":["D'Asie","D'Amérique","D'Afrique","D'Europe"],"b":2,"a":"Les Romains l'appelaient « poule de Numidie », du nom d'un royaume d'Afrique du Nord.","c":"Nature","d":3},{"id":"bg3ow3u3","t":"Quel arbre produit les dattes ?","r":["Le cocotier","Le figuier","Le palmier dattier","L'olivier"],"b":2,"a":"Un palmier dattier est mâle ou femelle : seuls les pieds femelles donnent des dattes. Les cultivateurs les pollinisent souvent à la main.","c":"Nature","d":2},{"id":"9w6vblrm","t":"Dans quel pays se tiennent les Jeux olympiques d'hiver de Sotchi, en 2014 ?","r":["La Géorgie","La Russie","L'Ukraine","La Turquie"],"b":1,"a":"Sotchi est une station balnéaire au bord de la mer Noire : les épreuves de ski se sont courues dans les montagnes voisines du Caucase.","c":"Sport","d":2},{"id":"z75xkvwu","t":"Que signifie l'expression « appeler un chat un chat » ?","r":["Aimer les animaux","Dire les choses franchement","Donner des noms aux bêtes","Parler à voix basse"],"b":1,"a":"Boileau l'a rendue célèbre par son vers : « J'appelle un chat un chat et Rolet un fripon », dans sa première satire.","c":"Culture générale","d":3},{"id":"20ax8yoz","t":"Pour quelle danseuse Michel Fokine a-t-il chorégraphié « La Mort du cygne » en 1905 ?","r":["Tamara Karsavina","Maïa Plissetskaïa","Anna Pavlova","Galina Oulanova"],"b":2,"a":"Ce solo de quelques minutes, sur une musique de Saint-Saëns, est devenu l'emblème de la danseuse qui l'a créé.","c":"Arts & lettres","d":2},{"id":"eifeakuq","t":"Dans l'espagnol d'Amérique, que veut dire « plata » au sens courant ?","r":["Assiette","Plage","Argent (monnaie)","Plaine"],"b":2,"a":"Le mot vient du métal argent : même glissement que dans le français « argent ».","c":"Culture générale","d":3},{"id":"4hde7mhf","t":"Quel patineur japonais devient champion olympique de patinage artistique en 2014, puis de nouveau en 2018 ?","r":["Shoma Uno","Daisuke Takahashi","Yuzuru Hanyu","Nobunari Oda"],"b":2,"a":"Au Japon, ses admirateurs lancent sur la glace une pluie de peluches Winnie l'ourson, son porte-bonheur, à la fin de ses programmes.","c":"Sport","d":3},{"id":"l8rz6x73","t":"Dans une séance de tirs au but, combien de tirs chaque équipe tente-t-elle avant une éventuelle mort subite ?","r":["3","5","6","4"],"b":1,"a":"La série s'arrête dès qu'une équipe ne peut plus être rattrapée, même si tous les tirs n'ont pas été tentés.","c":"Sport","d":2},{"id":"64kvb79s","t":"Quel spécialiste opère le cerveau et la moelle épinière ?","r":["Chirurgien cardiaque","Chirurgien viscéral","Chirurgien orthopédiste","Neurochirurgien"],"b":3,"a":"L'Américain Harvey Cushing est considéré comme le père de la neurochirurgie moderne.","c":"Culture générale","d":2},{"id":"4sw7ila6","t":"Les anglophones écrivent « RSVP » sur leurs invitations. De quelle langue viennent ces initiales ?","r":["Latin","Anglais","Français","Italien"],"b":2,"a":"L'anglais a gardé bien d'autres expressions françaises telles quelles, comme « déjà vu », « rendez-vous » ou « bon appétit ».","c":"Culture générale","d":3},{"id":"ifutb98j","t":"Comment s'appelle l'enceinte à piste inclinée où se disputent les courses de cyclisme sur piste ?","r":["Un vélodrome","Un hippodrome","Un autodrome","Un cynodrome"],"b":0,"a":"Les virages d'une piste olympique sont relevés de plus de quarante degrés pour que les coureurs y gardent leur vitesse.","c":"Sport","d":2},{"id":"u4mqdgp2","t":"Quel conifère méditerranéen donne les pignons du pesto ?","r":["Pin maritime","Cyprès","Cèdre","Pin parasol"],"b":3,"a":"Les pignons sont cachés dans de gros cônes qu'il faut casser pour en extraire de petites graines.","c":"Nature","d":3},{"id":"86qfc9hc","t":"Quel dieu romain du feu et de la forge correspond à l'Héphaïstos des Grecs ?","r":["Mars","Mercure","Saturne","Vulcain"],"b":3,"a":"Le mot « volcan » vient de son nom : les Romains imaginaient sa forge sous les montagnes en feu.","c":"Culture générale","d":3},{"id":"myjd3t48","t":"Quelle viennoiserie appelle-t-on « chocolatine » dans une grande partie du Sud-Ouest de la France ?","r":["Le pain au chocolat","Le pain aux raisins","Le croissant","La brioche"],"b":0,"a":"La querelle entre « pain au chocolat » et « chocolatine » est un débat de clocher bien connu en France, nourri par les régions de Toulouse et de Bordeaux.","c":"Cuisine","d":2},{"id":"i1r3sc6x","t":"Dans Les Misérables, quel gamin de Paris tombe sur une barricade en chantant ?","r":["Marius","Enjolras","Gavroche","Courfeyrac"],"b":2,"a":"Son nom est devenu un nom commun : un gavroche désigne un gamin de Paris effronté et débrouillard.","c":"Arts & lettres","d":2},{"id":"myuy3ghl","t":"En quart de finale de la Coupe du monde 2023, quel pays bat la France 29-28 au Stade de France ?","r":["Irlande","Nouvelle-Zélande","Argentine","Afrique du Sud"],"b":3,"a":"Les Bleus s'inclinent d'un point devant leur public, pourtant favoris.","c":"Sport","d":3},{"id":"czkzygwk","t":"Quelle console portable de Nintendo possède deux écrans, dont un tactile ?","r":["Game Boy Advance","Nintendo DS","PSP","Nintendo Switch"],"b":1,"a":"Le sigle DS signifie Dual Screen, c'est-à-dire double écran.","c":"Jeux & pop culture","d":2},{"id":"ojd6ltmd","t":"En 2006, quelle équipe bat la France aux tirs au but en finale de la Coupe du monde ?","r":["Italie","Portugal","Allemagne","Brésil"],"b":0,"a":"Ce fut le dernier match de Zinédine Zidane, exclu en prolongation pour un coup de tête sur Marco Materazzi.","c":"Sport","d":2},{"id":"87wqvu0d","t":"Quel rappeur new-yorkais a sorti « Hypnotize » en 1997, extrait de l'album « Life After Death » ?","r":["Nas","Jay-Z","The Notorious B.I.G.","DMX"],"b":2,"a":"« Life After Death » est paru quelques semaines après la mort du rappeur, tué à Los Angeles en mars 1997.","c":"Musique","d":3},{"id":"zxknhsm1","t":"Combien de faces un cube possède-t-il ?","r":["4","6","8","12"],"b":1,"a":"Sur un dé classique, les faces opposées totalisent toujours 7.","c":"Sciences","d":1},{"id":"ayjjgvvj","t":"De quel journal Times Square, haut lieu new-yorkais du réveillon, tient-il son nom ?","r":["The Washington Post","The New York Times","The Times de Londres","Time Magazine"],"b":1,"a":"La place s'appelait Longacre Square avant que le quotidien n'y installe son siège en 1904 et ne lui donne son nom.","c":"Autour de la fête","d":3},{"id":"m733004t","t":"Quelle chaîne de montagnes sépare la France de l'Espagne ?","r":["Alpes","Pyrénées","Jura","Vosges"],"b":1,"a":"Elle s'étend sur environ 430 kilomètres, de la Méditerranée à l'Atlantique.","c":"Géographie","d":1},{"id":"kll2uz9p","t":"Comment appelle-t-on une personne qui ne croit en l'existence d'aucun dieu ?","r":["Agnostique","Athée","Déiste","Mystique"],"b":1,"a":"Le mot vient du grec atheos, qui signifie « sans dieu ».","c":"Arts & lettres","d":1},{"id":"i6yh64ro","t":"En quelle année Forrest Mars fabrique-t-il la première barre Mars à Slough, en Angleterre ?","r":["1950","1932","1911","1946"],"b":1,"a":"Forrest Mars était le fils du fondateur américain de l'entreprise, avec qui il s'était brouillé.","c":"Cuisine","d":2},{"id":"g38f1ahp","t":"Dans « La Belle et la Bête » (1991), quel objet enchanté permet à la Bête de voir ce qui se passe au loin ?","r":["Une boule de cristal","Un miroir","Un livre","Une longue-vue"],"b":1,"a":"Pour ce film, la scénariste Linda Woolverton a fait de Belle une grande lectrice, plus indépendante que les héroïnes précédentes.","c":"Cinéma & séries","d":3},{"id":"vanvc5z3","t":"Quelle figure de style remplace le nom de Paris par « la Ville Lumière » ?","r":["Antiphrase","Hyperbole","Périphrase","Allitération"],"b":2,"a":"Le roi des animaux pour le lion, l'astre du jour pour le Soleil : la périphrase est une expression qui décrit au lieu de nommer.","c":"Culture générale","d":2},{"id":"4oaa8517","t":"Quel duo britannique a chanté « Wake Me Up Before You Go-Go » en 1984 ?","r":["Pet Shop Boys","Tears for Fears","Wham!","Eurythmics"],"b":2,"a":"Le duo formé par George Michael et Andrew Ridgeley a aussi signé « Last Christmas », sortie la même année.","c":"Musique","d":3},{"id":"auhy1384","t":"En quelle année Kendrick Lamar a-t-il reçu le prix Pulitzer de musique pour l'album « DAMN. » ?","r":["2015","2016","2018","2021"],"b":2,"a":"C'était la première fois que ce prix, jusque-là réservé à la musique classique et au jazz, récompensait un artiste de rap.","c":"Musique","d":2},{"id":"bf7e1zmi","t":"Dans une salle de cinéma, sur quoi le film est-il projeté ?","r":["L'écran","Le rideau","Le paravent","Le plafond"],"b":0,"a":"Dans de nombreuses salles, un rideau masque l'écran et s'ouvre juste avant la séance.","c":"Cinéma & séries","d":1},{"id":"sgoq2w9g","t":"Dans « C'est bon, très bon, délicieux, divin », quelle figure range les mots par intensité croissante ?","r":["Anaphore","Antithèse","Gradation","Chiasme"],"b":2,"a":"Une gradation peut aussi aller du plus fort au plus faible : on la dit alors descendante.","c":"Culture générale","d":3},{"id":"8sl88wv0","t":"Quel poisson cuirassé géant, au museau garni de lames osseuses tranchantes, dominait les mers du Dévonien ?","r":["Hélicoprion","Cladoselache","Dunkleosteus","Xiphactinus"],"b":2,"a":"Il n'avait pas de vraies dents : ses plaques osseuses s'aiguisaient en se frottant l'une contre l'autre.","c":"Nature","d":3},{"id":"cduki6ov","t":"Quelle maison de luxe française a pour emblème deux C entrelacés ?","r":["Dior","Hermès","Chanel","Louis Vuitton"],"b":2,"a":"Les deux C seraient les initiales de Gabrielle « Coco » Chanel, fondatrice de la maison.","c":"Jeux & pop culture","d":1},{"id":"49bxl5i6","t":"Quel pays d'Asie, sans accès à la mer, a pour capitale Oulan-Bator ?","r":["Kazakhstan","Mongolie","Ouzbékistan","Kirghizistan"],"b":1,"a":"La Mongolie est l'un des pays les moins densément peuplés du monde.","c":"Géographie","d":3},{"id":"94wnrop9","t":"Quelle envergure, en centimètres, atteint environ un aigle royal adulte ?","r":["80 cm","200 cm","400 cm","50 cm"],"b":1,"a":"La femelle de l'aigle royal est plus grande que le mâle, comme chez beaucoup de rapaces.","c":"Nature","d":2},{"id":"nbbtzntt","t":"Quel coquillage en forme de chapeau chinois s'agrippe si fort aux rochers qu'on peine à le décoller ?","r":["Le bigorneau","Le bulot","La patelle","La coque"],"b":2,"a":"À marée haute, la patelle broute les algues, puis revient se loger exactement au même creux du rocher.","c":"Nature","d":3},{"id":"4b2wxmlf","t":"Quel pain rond, garni de thon, d'œufs, de tomates et d'olives, est une spécialité niçoise ?","r":["Le pan bagnat","Le croque-monsieur","Le panini","Le jambon-beurre"],"b":0,"a":"Son nom niçois signifie « pain mouillé » : on l'arrose d'huile d'olive.","c":"Cuisine","d":3},{"id":"354ok50r","t":"Sur un tournage, comment appelle-t-on le chef qui règle l'image et la lumière avec le réalisateur ?","r":["Le chef monteur","Le chef décorateur","Le directeur de la photographie","L'ingénieur du son"],"b":2,"a":"Il dirige les équipes de la caméra, de l'éclairage et de la machinerie.","c":"Cinéma & séries","d":3},{"id":"bj7fz4u6","t":"Dans quelle série de jeux vidéo gère-t-on la vie quotidienne de personnages virtuels dans leur maison ?","r":["SimCity","Animal Crossing","Second Life","Les Sims"],"b":3,"a":"Le premier épisode, sorti en 2000 sur PC, est devenu l'un des jeux pour ordinateur les plus vendus de son époque.","c":"Jeux & pop culture","d":1},{"id":"cq1zvrt7","t":"Dans « La Belle et la Bête » (1991), comment s'appelle la théière du château ?","r":["Madame Samovar","Madame Garde-Robe","Madame Théière","Madame Porcelaine"],"b":0,"a":"Son fils Zip est une petite tasse ébréchée.","c":"Cinéma & séries","d":3},{"id":"nmfthed8","t":"Dans la mythologie grecque, comment s'appelle la nourriture des dieux qui leur assure l'immortalité ?","r":["L'hydromel","La manne","Le soma","L'ambroisie"],"b":3,"a":"Les dieux boivent aussi le nectar, que la jeune déesse Hébé leur servait à table sur l'Olympe.","c":"Culture générale","d":3}],"dur":[{"id":"3p7l6tdy","t":"Comment s'appelle la contrée paisible où vivent les hobbits, dans « Le Seigneur des anneaux » ?","r":["La Comté","Le Rohan","La Lothlórien","Le Gondor"],"b":0,"a":"Tolkien s'est inspiré de la campagne anglaise de son enfance, près de Birmingham, pour imaginer ce pays.","c":"Cinéma & séries","d":4},{"id":"if25gxlr","t":"Quel est le nom de famille de naissance de Judy Garland ?","r":["Gilmore","Gumm","Garrett","Graham"],"b":1,"a":"Elle a incarné Dorothy dans « Le Magicien d'Oz » en 1939.","c":"Jeux & pop culture","d":5},{"id":"2mqvwob6","t":"Au Danemark, que fait-on traditionnellement le soir du Nouvel An devant la porte de ses amis ?","r":["Planter un sapin","Allumer un feu","Briser de la vaisselle","Déposer du sel"],"b":2,"a":"Plus le tas d'assiettes brisées devant votre porte est grand, plus vous avez d'amis, dit-on.","c":"Autour de la fête","d":5},{"id":"o0vkig62","t":"Quel Lorrain, ancien président de la République, redevient président du Conseil en 1926 et stabilise le franc ?","r":["Gaston Doumergue","Raymond Poincaré","Alexandre Millerand","Aristide Briand"],"b":1,"a":"La monnaie stabilisée en 1928 est restée connue sous le nom de « franc Poincaré ».","c":"Histoire","d":4},{"id":"aad34ii2","t":"Comment appelle-t-on la partie de la lame d'un couteau qui s'enfonce dans le manche ?","r":["La mitre","Le talon","La soie","Le tenon"],"b":2,"a":"Sur certains couteaux, elle traverse toute la longueur du manche pour en assurer l'équilibre et la solidité.","c":"Culture générale","d":5},{"id":"8ao2rzb1","t":"Quel fruit géant descendait d'une tour à minuit, le soir du Nouvel An, à Atlanta ?","r":["Pomme","Orange","Pêche","Citron"],"b":2,"a":"La Géorgie est surnommée « l'État de la pêche » ; à New York, c'est une boule lumineuse qui descend.","c":"Autour de la fête","d":5},{"id":"ydnnuk4k","t":"Quel volcan éteint, point culminant de la Turquie, domine la frontière avec l'Arménie et l'Iran ?","r":["Erciyes","Uludağ","Ararat","Süphan"],"b":2,"a":"Cette montagne à deux sommets dépasse 5 000 mètres d'altitude et reste enneigée une grande partie de l'année.","c":"Géographie","d":4},{"id":"30c6o040","t":"Quelle prophétesse troyenne voit l'avenir sans que personne ne la croie ?","r":["Cassandre","Andromaque","Hécube","Briséis"],"b":0,"a":"Selon le mythe, Apollon lui donna le don de prophétie puis, éconduit, la condamna à n'être jamais crue.","c":"Culture générale","d":4},{"id":"xgp9xm0u","t":"Quelle est la seule unité de base du Système international dont le nom contient un préfixe ?","r":["La candela","Le kilogramme","La mole","Le kelvin"],"b":1,"a":"C'est pourquoi les multiples de la masse se forment à partir du gramme : on dit milligramme, pas microkilogramme.","c":"Culture générale","d":5},{"id":"j8lz66rh","t":"Quel Japonais, surnommé « Ō-Sensei », est le fondateur de l'aïkido ?","r":["Morihei Ueshiba","Jigoro Kano","Gichin Funakoshi","Mas Oyama"],"b":0,"a":"Ō-Sensei veut dire « grand maître » : il a créé une discipline sans compétition.","c":"Sport","d":4},{"id":"9e0een2y","t":"Qui a peint « Femmes de Tahiti », tableau polynésien conservé au musée d'Orsay ?","r":["Henri Rousseau","Paul Gauguin","Gustave Caillebotte","Ilia Répine"],"b":1,"a":"Le peintre s'installa à Tahiti en 1891, puis aux îles Marquises, où il mourut en 1903.","c":"Arts & lettres","d":5},{"id":"vjuezwhb","t":"Quel solo de Jérôme Bel, créé en 2004, donne la parole à une danseuse du corps de ballet de l'Opéra de Paris ?","r":["The Show Must Go On","Véronique Doisneau","Cédric Andrieux","Pichet Klunchun and Myself"],"b":1,"a":"Sur scène, la danseuse parle de son métier, du quotidien du corps de ballet et de la carrière d'étoile qu'elle n'a pas eue.","c":"Arts & lettres","d":5},{"id":"6j61qn11","t":"Quel acteur incarne James Bond dans la parodie « Casino Royale » de 1967, hors de la série officielle ?","r":["David Niven","Sean Connery","Peter Sellers","Roger Moore"],"b":0,"a":"Peter Sellers et Woody Allen jouent aussi dans ce film délirant, où plusieurs agents prennent le nom de James Bond.","c":"Cinéma & séries","d":5},{"id":"567xsoao","t":"Quel chanteur malien est surnommé « la voix d'or de l'Afrique » ?","r":["Youssou N'Dour","Ali Farka Touré","Baaba Maal","Salif Keïta"],"b":3,"a":"Son album « Soro », de 1987, l'a fait connaître en Europe.","c":"Musique","d":5},{"id":"ckeyljhc","t":"À quelle fréquence oscille le courant alternatif du réseau électrique français ?","r":["25 hertz","50 hertz","60 hertz","100 hertz"],"b":1,"a":"Aux États-Unis, la fréquence du réseau est de 60 hertz.","c":"Sciences","d":4},{"id":"nkbe1d9l","t":"Dans quel pays se trouve Volubilis, cité romaine célèbre pour ses mosaïques ?","r":["Maroc","Tunisie","Algérie","Libye"],"b":0,"a":"Le site, proche de Meknès, est inscrit au patrimoine mondial de l'Unesco.","c":"Géographie","d":5},{"id":"hukkw5sk","t":"Quelle mangaka a créé Fullmetal Alchemist, l'histoire de deux frères alchimistes ?","r":["Naoko Takeuchi","Rumiko Takahashi","Hiromu Arakawa","Moyoco Anno"],"b":2,"a":"Hiromu Arakawa a grandi dans une ferme de Hokkaido, ce qui a inspiré son manga Silver Spoon.","c":"Arts & lettres","d":5},{"id":"ipvdue6d","t":"Quelle épice rouge-orangé enveloppe la graine de la noix de muscade ?","r":["Le safran","La cardamome","Le macis","Le curcuma"],"b":2,"a":"Une même muscade livre deux épices : la graine elle-même, râpée, et cette membrane, séchée, au goût plus délicat.","c":"Nature","d":5},{"id":"b88mbqkg","t":"Quel est le nom de l'hymne national de la Belgique ?","r":["La Wallonne","La Liégeoise","La Flamande","La Brabançonne"],"b":3,"a":"Il est né en 1830, pendant la révolution qui a mené le pays à l'indépendance face aux Pays-Bas.","c":"Culture générale","d":4},{"id":"gut8vu3e","t":"Quel acteur britannique incarne le comte Dracula dans les films de la Hammer, dès « Le Cauchemar de Dracula » (1958) ?","r":["Peter Cushing","Vincent Price","Christopher Lee","Boris Karloff"],"b":2,"a":"Il y retrouve Peter Cushing, qui joue le docteur Van Helsing, dans plusieurs films de la série.","c":"Autour de la fête","d":4},{"id":"x35eq164","t":"Quel chant de Noël français est connu en anglais sous le titre « O Holy Night » ?","r":["Douce nuit","Les anges dans nos campagnes","Minuit, chrétiens","Il est né, le divin Enfant"],"b":2,"a":"Les paroles françaises ont été écrites par Placide Cappeau, un négociant en vins de Roquemaure, dans le Gard.","c":"Autour de la fête","d":4},{"id":"blomht0x","t":"Quel sommet, haut de plus de 5 000 mètres, est le point culminant de la Turquie ?","r":["Mont Erciyes","Mont Ararat","Mont Nemrut","Mont Uludağ"],"b":1,"a":"Bien qu'il se trouve en Turquie, le mont Ararat figure sur les armoiries de l'Arménie, d'où on le voit.","c":"Culture générale","d":4},{"id":"c6d758ky","t":"Qui a écrit le poème « Le Fardeau de l'homme blanc », publié en 1899 ?","r":["H. G. Wells","Rudyard Kipling","Arthur Conan Doyle","Natsume Sōseki"],"b":1,"a":"Le poème a été écrit à propos de la conquête des Philippines par les États-Unis. Son auteur a reçu le prix Nobel de littérature en 1907.","c":"Arts & lettres","d":5},{"id":"vyzgcjdr","t":"Dans quel film Disney de 1963 un magicien barbu lance-t-il « Higitus figitus » ?","r":["Robin des Bois","Merlin l'Enchanteur","Le Livre de la jungle","Les Aristochats"],"b":1,"a":"Le film est tiré d'un roman de T. H. White, publié en 1938.","c":"Cinéma & séries","d":5},{"id":"o3sdz3k5","t":"Dans quelle région se déroulent les jeux Pokémon Rubis et Saphir, sortis en 2002 au Japon ?","r":["Kanto","Hoenn","Johto","Sinnoh"],"b":1,"a":"Cette troisième génération a introduit les combats en double et les talents des Pokémon.","c":"Jeux & pop culture","d":4},{"id":"zew1vizr","t":"Qui a réalisé le film « Deadpool et Wolverine », sorti en 2024 ?","r":["Shawn Levy","Adam McKay","Christopher McQuarrie","David Ayer"],"b":0,"a":"Ryan Reynolds et Hugh Jackman y partagent l'affiche.","c":"Cinéma & séries","d":4},{"id":"nipaa41f","t":"Quel duo d'auteurs a imaginé la série Les Cités obscures ?","r":["Bilal et Christin","Mézières et Christin","Schuiten et Peeters","Moebius et Jodorowsky"],"b":2,"a":"La série, entre architecture et uchronie, a pour premier album Les Murailles de Samaris.","c":"Arts & lettres","d":4},{"id":"jnq9r3hz","t":"Quel producteur italien installé à Munich a produit « I Feel Love », succès de Donna Summer en 1977 ?","r":["Nile Rodgers","Giorgio Moroder","Quincy Jones","Trevor Horn"],"b":1,"a":"Le morceau repose sur une ligne de basse entièrement synthétique et passe pour un jalon de la musique électronique de danse.","c":"Musique","d":5},{"id":"4l0xpo5e","t":"Sous quel nom Ludovic Navarre a-t-il sorti en 2000 l'album « Tourist », mêlant jazz et house ?","r":["Cassius","Motorbass","Mr. Oizo","St Germain"],"b":3,"a":"L'album est paru chez Blue Note, label historique du jazz américain, une rareté pour un disque électro français.","c":"Musique","d":5},{"id":"cc3y5lif","t":"Quelle compagnie de hip-hop sur scène Mourad Merzouki a-t-il fondée en 1996 ?","r":["Pockemon Crew","Käfig","Accrorap","Wanted Posse"],"b":1,"a":"Il y mêle hip-hop, cirque et danse contemporaine.","c":"Arts & lettres","d":4},{"id":"20wt0gu8","t":"Quel nuage en forme de soucoupe se forme souvent au-dessus des montagnes ?","r":["Le nuage mammatus","Le nuage lenticulaire","Le cumulus","Le nimbostratus"],"b":1,"a":"Sa forme lisse et immobile l'a fait plus d'une fois prendre pour un OVNI.","c":"Sciences","d":4},{"id":"xf733xvo","t":"Quel amiral chinois dirige, entre 1405 et 1433, sept grandes expéditions maritimes jusqu'en Afrique de l'Est ?","r":["Xuanzang","Zhang Qian","Zheng He","Faxian"],"b":2,"a":"Eunuque musulman originaire du Yunnan, il s'appelait d'abord Ma He ; l'empereur Yongle lui donna un nouveau nom.","c":"Histoire","d":5},{"id":"tnljyplg","t":"Kandy, ancienne capitale royale au cœur des collines à thé, se trouve dans quel pays ?","r":["Inde","Népal","Sri Lanka","Bangladesh"],"b":2,"a":"Kandy fut la capitale du dernier royaume indépendant de l'île avant la conquête britannique.","c":"Géographie","d":5},{"id":"c31f7c5d","t":"Quel chef d'orchestre new-yorkais a popularisé le boogaloo avec « Bang Bang » en 1966 ?","r":["Joe Cuba","Joe Bataan","Pete Rodríguez","Ricardo Ray"],"b":0,"a":"Le boogaloo mêle rythmes latins et rhythm and blues ; ce titre en est un emblème.","c":"Musique","d":5},{"id":"hl3ouyht","t":"Au hockey sur glace, de quelle couleur sont les deux lignes qui délimitent la zone neutre au centre de la patinoire ?","r":["Rouge","Jaune","Bleu","Vert"],"b":2,"a":"Un attaquant ne peut pas franchir la ligne bleue adverse avant le palet : c'est la règle du hors-jeu.","c":"Sport","d":4},{"id":"m6ho4nbx","t":"Quelle graine est broyée en pâte pour faire le tahini, que l'on mêle au houmous ?","r":["Le tournesol","Le sésame","Le lin","Le pavot"],"b":1,"a":"Dans les contes des Mille et Une Nuits, la formule « Sésame, ouvre-toi » ferait allusion à la gousse qui s'ouvre d'un coup.","c":"Cuisine","d":4},{"id":"171jjmzk","t":"Quel groupe new-yorkais a sorti en 1986 l'album « Licensed to Ill » ?","r":["Run-DMC","De La Soul","Beastie Boys","A Tribe Called Quest"],"b":2,"a":"« Licensed to Ill » a été le premier album de rap à se classer numéro un du Billboard 200.","c":"Musique","d":4},{"id":"vyeqqd4h","t":"Comment moule-t-on, selon le cahier des charges de l'AOP, le camembert de Normandie ?","r":["À la main","Au tamis","À la presse","À la louche"],"b":3,"a":"Le caillé est versé dans le moule en plusieurs passages successifs, traditionnellement cinq, espacés d'environ 40 minutes.","c":"Cuisine","d":4},{"id":"9idkhjbs","t":"Quel sommet du Karakoram est surnommé la « Montagne sauvage » ?","r":["Makalu","Lhotse","K2","Cho Oyu"],"b":2,"a":"Réputé plus technique que l'Everest, il garde ce surnom depuis une expédition américaine des années 1950.","c":"Géographie","d":4},{"id":"um2jyavp","t":"De quel concours britannique « Nouvelle Star » est-elle l'adaptation française ?","r":["Pop Idol","The X Factor","Popstars","Britain's Got Talent"],"b":0,"a":"Pop Idol a donné naissance à toute une famille de concours, dont American Idol aux États-Unis.","c":"Jeux & pop culture","d":4},{"id":"0b9pp2qt","t":"Qui a réalisé la comédie « Les Sous-doués », sortie en 1980 avec Daniel Auteuil ?","r":["Serge Korber","Claude Zidi","Claude Berri","Christian de Chalonge"],"b":1,"a":"Le film a connu une suite, « Les Sous-doués en vacances », sortie en 1982.","c":"Cinéma & séries","d":4},{"id":"2tboakz5","t":"Quelle commune des Hautes-Alpes passe pour la plus haute de France, son village dépassant 2 000 mètres ?","r":["Briançon","Montgenèvre","Molines-en-Queyras","Saint-Véran"],"b":3,"a":"Sa devise dit qu'on y est si haut que « les coqs picorent les étoiles ».","c":"Culture générale","d":5},{"id":"fvwcr2go","t":"Qui proclame l'indépendance d'Haïti, le 1er janvier 1804 ?","r":["Jean-Jacques Dessalines","Toussaint Louverture","Henri Christophe","Alexandre Pétion"],"b":0,"a":"Il se fait couronner empereur la même année, sous le nom de Jacques Ier.","c":"Histoire","d":5},{"id":"6d8y61aa","t":"Quelle femme devient en 1969 la première Première ministre d'Israël ?","r":["Indira Gandhi","Golda Meir","Margaret Thatcher","Benazir Bhutto"],"b":1,"a":"Née à Kiev, elle a grandi aux États-Unis avant de s'installer en Palestine.","c":"Histoire","d":4},{"id":"uvhcldyv","t":"Dans quel film de 1984 chante-t-on « Who you gonna call? » face à des apparitions ?","r":["Gremlins","Poltergeist","Les Goonies","SOS Fantômes"],"b":3,"a":"La chanson de Ray Parker Jr. a été numéro un aux États-Unis en 1984.","c":"Cinéma & séries","d":4},{"id":"0hf0eji5","t":"Quel footballeur argentin était surnommé « El Pibe de Oro », le gamin en or ?","r":["Lionel Messi","Diego Maradona","Gabriel Batistuta","Mario Kempes"],"b":1,"a":"Il a mené l'Argentine au titre mondial en 1986, au Mexique.","c":"Jeux & pop culture","d":4},{"id":"5vj8frt7","t":"Le Graoully est le dragon légendaire de quelle ville française ?","r":["Nancy","Strasbourg","Reims","Metz"],"b":3,"a":"Saint Clément, premier évêque de la ville, l'aurait chassé en le menant jusqu'à la rivière.","c":"Culture générale","d":5},{"id":"lo9cm7yv","t":"Sur quelle île se dresse le volcan Hekla ?","r":["Le Groenland","L'Islande","Les îles Féroé","Jan Mayen"],"b":1,"a":"Au Moyen Âge, ses éruptions lui valurent d'être surnommé la « porte de l'enfer » en Europe.","c":"Géographie","d":4},{"id":"f5qsvqkf","t":"Quel oiseau surmonte les armoiries du drapeau de l'Équateur ?","r":["Un aigle royal","Un quetzal","Un condor","Un toucan"],"b":2,"a":"Sans ses armoiries, le drapeau équatorien serait presque identique à celui de la Colombie.","c":"Géographie","d":5},{"id":"39voxj7h","t":"De quel pays vient la majorité des graines de moutarde utilisées pour la moutarde de Dijon ?","r":["France","Inde","Chine","Canada"],"b":3,"a":"« Moutarde de Dijon » désigne une recette et non une origine : elle peut être fabriquée n'importe où.","c":"Cuisine","d":5},{"id":"0n6vy6w6","t":"Dans quelle ville britannique le label électro Warp a-t-il été fondé en 1989 ?","r":["Manchester","Bristol","Sheffield","Leeds"],"b":2,"a":"Le label a compté Aphex Twin et Autechre parmi ses artistes.","c":"Musique","d":5},{"id":"ep361ft3","t":"Quels insectes un myrmécologue étudie-t-il ?","r":["Les fourmis","Les abeilles","Les papillons","Les termites"],"b":0,"a":"Les fourmis vivent sur tous les continents sauf l'Antarctique, et l'on en a décrit plus de dix mille espèces.","c":"Nature","d":4},{"id":"wuiykj3l","t":"Comment qualifie-t-on une réaction chimique qui dégage de la chaleur, comme une combustion ?","r":["Endothermique","Isotherme","Exothermique","Adiabatique"],"b":2,"a":"Les chaufferettes de poche jetables fonctionnent ainsi : de la poudre de fer s'oxyde au contact de l'air en libérant de la chaleur.","c":"Sciences","d":4},{"id":"fbtdir8a","t":"Quel journaliste a publié en 1913 la première grille de mots croisés dans un journal new-yorkais ?","r":["Will Shortz","Arthur Wynne","Georges Perec","Alfred Butts"],"b":1,"a":"Il l'avait baptisée « word-cross » ; une inversion typographique l'aurait rebaptisée « cross-word ».","c":"Culture générale","d":4},{"id":"t4xn3mwu","t":"Quel écrivain a rédigé en 1857 une dictée devenue célèbre, lue à Compiègne devant Napoléon III ?","r":["Prosper Mérimée","Alphonse Daudet","Théophile Gautier","Alexandre Dumas"],"b":0,"a":"Mérimée est aussi l'auteur des nouvelles « Carmen » et « Colomba ».","c":"Culture générale","d":4},{"id":"eu014pu0","t":"Dans quel quartier de Tokyo se trouve Sukiyabashi Jiro, le restaurant de sushis du maître Jiro Ono ?","r":["Shibuya","Shinjuku","Ginza","Asakusa"],"b":2,"a":"Ce minuscule comptoir, installé au sous-sol d'un immeuble de bureaux, a été rendu célèbre par le documentaire Jiro Dreams of Sushi.","c":"Cuisine","d":5},{"id":"eonbqld6","t":"Depuis quelle année le marché de Noël de Strasbourg, le Christkindelsmärik, est-il attesté ?","r":["1670","1570","1770","1470"],"b":1,"a":"Il a succédé à un ancien marché de la Saint-Nicolas, déplacé pour mettre en avant l'Enfant Jésus apportant les cadeaux.","c":"Autour de la fête","d":4},{"id":"rho615eu","t":"Quelle est la forme correcte de « contredire » à la deuxième personne du pluriel du présent ?","r":["Vous contredites","Vous contredissez","Vous contredisiez","Vous contredisez"],"b":3,"a":"Contredire, interdire, médire et prédire font « vous …disez », alors que dire et redire font « vous dites », « vous redites ».","c":"Culture générale","d":4},{"id":"n3duawoo","t":"Quel surnom porte la Symphonie n° 41, la dernière de Mozart ?","r":["Prague","Linz","Jupiter","Haffner"],"b":2,"a":"Ce surnom ne vient pas de Mozart : il serait dû à l'imprésario londonien Johann Peter Salomon, après la mort du compositeur.","c":"Musique","d":4},{"id":"ekmb9b96","t":"Quel prénom porte le volleyeur français Ngapeth, choisi par son père en hommage à Magic Johnson ?","r":["Kevin","Earvin","Jenia","Antoine"],"b":1,"a":"Son père, Éric Ngapeth, ancien international français de volley, a aussi été son entraîneur.","c":"Sport","d":5},{"id":"ohk4qx0m","t":"En 1979, dans quel État américain la centrale de Three Mile Island a-t-elle connu une fusion partielle du cœur d'un réacteur ?","r":["Le New Jersey","La Pennsylvanie","L'Ohio","Le Maryland"],"b":1,"a":"L'accident est survenu quelques jours après la sortie du film « Le Syndrome chinois », qui imaginait justement un accident nucléaire.","c":"Nature","d":4},{"id":"nnj34s4h","t":"Combien d'intersections compte le plateau standard du jeu de go ?","r":["81","169","289","361"],"b":3,"a":"Des plateaux plus petits, de 9 ou 13 lignes, servent à l'initiation.","c":"Jeux & pop culture","d":4},{"id":"01jt6ktd","t":"Sur quel lac italien se trouvent les îles Borromées ?","r":["Le lac de Côme","Le lac Majeur","Le lac de Garde","Le lac d'Iseo"],"b":1,"a":"L'Isola Bella, la plus célèbre, porte un palais baroque et des jardins en terrasses construits pour la famille Borromée.","c":"Géographie","d":4},{"id":"lsznk8et","t":"Quel écrivain libanais a publié en 1923 Le Prophète, livre de textes poétiques ?","r":["Amin Maalouf","Mahmoud Darwich","Khalil Gibran","Adonis"],"b":2,"a":"Écrit directement en anglais, le livre compte parmi les ouvrages poétiques les plus lus au monde.","c":"Arts & lettres","d":4},{"id":"q1ae5h46","t":"Qui a remporté le classement général du Tour de France 1980 ?","r":["Giuseppe Saronni","Faustino Rupérez","Joop Zoetemelk","Giovanni Battaglin"],"b":2,"a":"Il a été champion du monde sur route en 1985, à 38 ans.","c":"Sport","d":5},{"id":"q0qkroi4","t":"Quel Viking, banni d'Islande, fonde vers 985 la première colonie du Groenland ?","r":["Ingólfr Arnarson","Bjarni Herjólfsson","Naddodd","Erik le Rouge"],"b":3,"a":"Selon les sagas, il aurait choisi le nom de « terre verte » pour attirer des colons vers une île surtout couverte de glace.","c":"Histoire","d":5},{"id":"5rspb4xa","t":"Qui a réalisé le film « Imitation Game », sorti en 2014 ?","r":["Harald Zwart","Denis Villeneuve","Morten Tyldum","J. J. Abrams"],"b":2,"a":"Benedict Cumberbatch y incarne le mathématicien Alan Turing, qui a aidé à déchiffrer la machine Enigma.","c":"Cinéma & séries","d":5},{"id":"evv8q5qu","t":"Quel rappeur new-yorkais a sorti « Juicy » en 1994 ?","r":["Nas","The Notorious B.I.G.","LL Cool J","Method Man"],"b":1,"a":"Le morceau reprend la mélodie de « Juicy Fruit », un titre du groupe Mtume sorti en 1983.","c":"Musique","d":4},{"id":"z3sskhpq","t":"Quel oiseau couronné est l'emblème de la Pologne ?","r":["Un aigle noir","Un faucon","Une cigogne","Un aigle blanc"],"b":3,"a":"Selon la légende, Lech, fondateur du pays, aurait vu un aigle blanc nicher et fait de ce lieu sa capitale.","c":"Culture générale","d":5},{"id":"0pzmz5g6","t":"Comment dit-on « quarante » en anglais ?","r":["forty","fourty","fourteen","fortie"],"b":0,"a":"Curieusement, « four » garde son « u » mais « forty » le perd, alors que « fourteen » le conserve.","c":"Culture générale","d":4},{"id":"40xisdj6","t":"Combien d'éléments le calendrier chinois associe-t-il aux douze animaux pour former un cycle de soixante ans ?","r":["Quatre","Cinq","Six","Trois"],"b":1,"a":"Les cinq éléments sont le bois, le feu, la terre, le métal et l'eau. Une même combinaison d'élément et d'animal ne revient que tous les soixante ans.","c":"Autour de la fête","d":4},{"id":"48joz8hs","t":"Comment appelle-t-on les noces célébrées après neuf ans de mariage ?","r":["Noces de faïence","Noces de cuivre","Noces de verre","Noces de bois"],"b":0,"a":"Fragile, la faïence rappelle qu'un couple s'entretient comme un service de table.","c":"Autour de la fête","d":4},{"id":"kesgpvkt","t":"Quel fruit à l'odeur très forte est interdit dans le métro de Singapour ?","r":["Le jacquier","Le ramboutan","Le durian","Le mangoustan"],"b":2,"a":"Les amateurs comparent sa chair à une crème onctueuse, ses détracteurs son odeur à celle d'oignons pourris.","c":"Cuisine","d":4},{"id":"9oj3sff8","t":"Quel coureur finlandais, surnommé le « Finlandais volant », remporte neuf médailles d'or olympiques entre 1920 et 1928 ?","r":["Lasse Virén","Ville Ritola","Paavo Nurmi","Hannes Kolehmainen"],"b":2,"a":"Il courait en tenant un chronomètre à la main.","c":"Sport","d":4},{"id":"kqwe252q","t":"Dans quelle ville la chanteuse Juliette Gréco est-elle née, en 1927 ?","r":["Marseille","Paris","Toulouse","Montpellier"],"b":3,"a":"Égérie de Saint-Germain-des-Prés après la guerre, elle a chanté des textes de Jacques Prévert et de Raymond Queneau.","c":"Musique","d":5},{"id":"zbg9jt92","t":"Qui a écrit « Respect », chanson qu'Aretha Franklin a rendue célèbre en 1967 ?","r":["Sam Cooke","Otis Redding","James Brown","Marvin Gaye"],"b":1,"a":"Otis Redding l'avait enregistrée en 1965 ; la version d'Aretha est devenue un hymne féministe et un étendard des droits civiques.","c":"Musique","d":4},{"id":"wxal517d","t":"Dans quel pays est né Angus Young, guitariste d'AC/DC ?","r":["Australie","Irlande","Écosse","Nouvelle-Zélande"],"b":2,"a":"Il joue sur scène en uniforme d'écolier, une tenue devenue sa marque depuis les débuts du groupe.","c":"Musique","d":5},{"id":"tqi1y9sd","t":"Quel légume émincé forme l'essentiel de la garniture de l'okonomiyaki, galette japonaise cuite sur une plaque ?","r":["Le poireau","La carotte","Le chou","L'aubergine"],"b":2,"a":"Son nom veut dire à peu près « grillé comme on l'aime » : chacun y ajoute ce qu'il préfère, porc, calamar ou fromage.","c":"Cuisine","d":4},{"id":"mlobahw1","t":"Quelle île, la deuxième plus grande du monde après le Groenland, est partagée entre deux pays ?","r":["Bornéo","Madagascar","Nouvelle-Guinée","Sumatra"],"b":2,"a":"Sa moitié occidentale appartient à l'Indonésie, et sa moitié orientale à un État indépendant depuis 1975.","c":"Géographie","d":4},{"id":"kl3s22sw","t":"Selon l'épopée qui porte son nom, sur quelle cité de Mésopotamie régnait le roi Gilgamesh ?","r":["Babylone","Ninive","Ur","Uruk"],"b":3,"a":"L'épopée de Gilgamesh, gravée sur des tablettes d'argile, raconte déjà un grand déluge auquel un homme survit dans une barque.","c":"Histoire","d":5},{"id":"veqkobc6","t":"Quel chanteur belge était surnommé « le Grand Jacques » ?","r":["Jacques Dutronc","Jacques Brel","Jacques Higelin","Jacques Lanzmann"],"b":1,"a":"Il a passé ses dernières années aux îles Marquises, où il repose à Atuona, non loin du peintre Paul Gauguin.","c":"Jeux & pop culture","d":4},{"id":"dzuryc01","t":"Qui a créé la série médicale américaine « Urgences », lancée en 1994 ?","r":["Michael Crichton","George Lucas","Steven Spielberg","Stephen King"],"b":0,"a":"Ce créateur est aussi l'auteur du roman « Jurassic Park ». Il avait fait des études de médecine à Harvard.","c":"Cinéma & séries","d":5},{"id":"yiqrffla","t":"La cueca, danse où l'on agite un mouchoir, a été déclarée danse nationale de quel pays en 1979 ?","r":["Mexique","Colombie","Chili","Uruguay"],"b":2,"a":"La cueca met en scène la cour d'un homme à une femme ; les deux danseurs tiennent chacun un mouchoir.","c":"Musique","d":4},{"id":"p89bkoa4","t":"Que signifie la lettre A dans le sigle ADSL, la connexion à Internet par la ligne téléphonique ?","r":["Advanced","Asymmetric","Automatic","Analog"],"b":1,"a":"Avec l'ADSL, on peut téléphoner et surfer en même temps, ce que ne permettait pas l'ancien modem par ligne commutée.","c":"Jeux & pop culture","d":5},{"id":"faudywnv","t":"Quel réalisateur a signé « La Planète sauvage » (1973), Prix spécial du jury à Cannes ?","r":["René Laloux","Paul Grimault","Jean Image","Albert Barillé"],"b":0,"a":"Les dessins du film sont de Roland Topor.","c":"Cinéma & séries","d":5},{"id":"n47lbodr","t":"Comment appelle-t-on le chant à deux voix qui se répondent, sans instrument, pour faire danser un fest-noz ?","r":["La gwerz","Le sône","Le kanaouenn","Le kan ha diskan"],"b":3,"a":"Le nom breton veut dire « chant et contre-chant » : un chanteur lance la phrase, le second la reprend aussitôt.","c":"Autour de la fête","d":5},{"id":"zwynp7pr","t":"La mangue et la pistache appartiennent à la même famille botanique que quel autre fruit ?","r":["L'amande","La noisette","La noix de macadamia","La noix de cajou"],"b":3,"a":"Cette famille, celle des Anacardiacées, compte aussi le sumac vénéneux d'Amérique du Nord, une plante très irritante pour la peau.","c":"Nature","d":5},{"id":"f4trc8ze","t":"Quelle pyramide a le plus grand volume du monde ?","r":["La pyramide de Khéops","La pyramide du Soleil","La pyramide de Djéser","La pyramide de Cholula"],"b":3,"a":"Une église espagnole couronne son sommet, et la pyramide ressemble à une colline.","c":"Culture générale","d":5},{"id":"f7gnh4wm","t":"Quelle Française a reçu en 1935 le prix Nobel de chimie pour la radioactivité artificielle, comme sa mère en 1911 ?","r":["Ève Curie","Marguerite Perey","Irène Joliot-Curie","Émilie du Châtelet"],"b":2,"a":"Avec son mari Frédéric, elle a créé en laboratoire de nouveaux éléments radioactifs.","c":"Sciences","d":4},{"id":"gj65fonu","t":"Qui a remporté le classement général du Tour d'Italie 2019 ?","r":["Primož Roglič","Tom Dumoulin","Richard Carapaz","Vincenzo Nibali"],"b":2,"a":"Il est devenu le premier coureur de son pays à gagner le Giro, après avoir pris le maillot rose dans les Alpes.","c":"Sport","d":5},{"id":"cbkpohcs","t":"Comment appelle-t-on en français un groupe de quatre bits, soit un demi-octet ?","r":["Un quartet","Un mot","Un doublet","Un registre"],"b":0,"a":"En anglais, il se nomme « nibble », jeu de mots sur « byte », qui se prononce comme « bite », une bouchée.","c":"Sciences","d":5},{"id":"a3v3136y","t":"Que signifie le sigle SCI, souvent utilisé pour détenir un bien à plusieurs ?","r":["Société commerciale immobilière","Société civile immobilière","Syndicat civil d'investissement","Société coopérative immobilière"],"b":1,"a":"Beaucoup de familles s'en servent pour détenir ensemble un logement et préparer sa transmission.","c":"Culture générale","d":4},{"id":"fz8wkoj4","t":"Quelle crème mêle de la crème pâtissière et de la meringue italienne, et garnit le saint-honoré ?","r":["La crème diplomate","La crème mousseline","La crème Chiboust","La frangipane"],"b":2,"a":"Elle doit son nom au pâtissier parisien Chiboust, installé rue Saint-Honoré, où il aurait aussi créé le gâteau baptisé du nom de cette rue.","c":"Cuisine","d":5},{"id":"u5nqvvky","t":"Dans « Jurassic Park » (1993), quel milliardaire accueille ses invités d'un « Bienvenue à Jurassic Park » ?","r":["Ian Malcolm","John Hammond","Alan Grant","Dennis Nedry"],"b":1,"a":"John Hammond est joué par Richard Attenborough, lui-même réalisateur de « Gandhi », récompensé par l'Oscar du meilleur film.","c":"Cinéma & séries","d":4},{"id":"eve0eac1","t":"En septembre 1900, quelle ville du Texas est ravagée par un ouragan, la pire catastrophe naturelle de l'histoire des États-Unis ?","r":["Houston","Corpus Christi","Mobile","Galveston"],"b":3,"a":"Après le drame, la ville a construit une digue géante et rehaussé ses rues pour se protéger des tempêtes.","c":"Histoire","d":5},{"id":"npbl4dvv","t":"De quel pays la race de moutons mérinos est-elle originaire ?","r":["L'Australie","La Nouvelle-Zélande","L'Espagne","L'Écosse"],"b":2,"a":"L'Espagne en a longtemps interdit l'exportation, pour garder le monopole de sa laine, très fine.","c":"Nature","d":5},{"id":"vnmwkw7q","t":"Qu'avait de particulier le pouce de l'Iguanodon ?","r":["Une pointe osseuse conique","Il était palmé","Il était absent","Une ventouse"],"b":0,"a":"Gideon Mantell avait d'abord placé cette pointe sur le nez de l'animal, comme une corne de rhinocéros.","c":"Nature","d":4},{"id":"bphdi4uk","t":"Sur combien de bits le code ASCII d'origine représente-t-il un caractère ?","r":["5","7","8","16"],"b":1,"a":"Sept bits donnent 128 caractères ; le huitième bit a ensuite servi à étendre le code avec les accents et d'autres symboles.","c":"Sciences","d":5},{"id":"y6n7zw45","t":"Dans quel pays a été fondée en 1951 l'entreprise du Tetra Pak, emballage de carton pour le lait et les jus ?","r":["Danemark","Suisse","Suède","Finlande"],"b":2,"a":"Le premier emballage de la firme avait la forme d'un tétraèdre, d'où son nom.","c":"Culture générale","d":5},{"id":"tox7a4ae","t":"Selon la tradition antique, quel était le vrai nom de Platon, « Platon » n'étant qu'un surnom ?","r":["Alcibiade","Philoclès","Archélaos","Aristoclès"],"b":3,"a":"Le surnom viendrait du grec « platus », large : il aurait évoqué la carrure de ses épaules, ou l'ampleur de son front.","c":"Arts & lettres","d":5},{"id":"asf8y71d","t":"Quel film a reçu la Palme d'or du Festival de Cannes en 2006 ?","r":["L'Enfant","Le vent se lève","Entre les murs","Le Ruban blanc"],"b":1,"a":"Le film se déroule pendant la guerre d'indépendance irlandaise.","c":"Cinéma & séries","d":5},{"id":"awskbb3v","t":"Pourquoi remue-t-on la pâte à choux sur le feu, juste après y avoir versé la farine ?","r":["Pour la caraméliser","Pour la dessécher","Pour la faire lever","Pour la refroidir"],"b":1,"a":"Une pâte bien desséchée absorbe ensuite plus d'œufs, et c'est l'eau des œufs, changée en vapeur au four, qui fait gonfler les choux.","c":"Cuisine","d":5},{"id":"tw12nhyb","t":"En quelle année les voitures électriques du circuit Scalextric, guidées par une fente, sont-elles apparues ?","r":["1953","1955","1957","1960"],"b":2,"a":"Son inventeur, Fred Francis, avait d'abord produit des petites voitures de tôle à ressort.","c":"Jeux & pop culture","d":4},{"id":"278r9nak","t":"Par quoi les mousses et les fougères se reproduisent-elles, faute de graines ?","r":["Des pépins","Des spores","Des noyaux","Des samares"],"b":1,"a":"Sous les feuilles d'une fougère, les petits points bruns que l'on voit sont des amas de sporanges pleins de spores.","c":"Nature","d":4},{"id":"kscqz39u","t":"Quel est le nom de famille de naissance de l'acteur Ben Kingsley ?","r":["Patel","Bhanji","Kapoor","Sharma"],"b":1,"a":"Il a reçu l'Oscar du meilleur acteur en 1983 pour « Gandhi ».","c":"Jeux & pop culture","d":5},{"id":"93yekebs","t":"Qui a écrit les paroles de « Sous le ciel de Paris », chanson de 1951 ?","r":["Jacques Prévert","Boris Vian","Jean Dréjac","Francis Lemarque"],"b":2,"a":"Hubert Giraud en a composé la musique, et la chanson est devenue un véritable hymne à la capitale.","c":"Musique","d":4},{"id":"mcscl7l8","t":"Qui a réalisé « Oscar » (1967), comédie avec Louis de Funès adaptée d'une pièce de Claude Magnier ?","r":["Gérard Oury","Jean Girault","Édouard Molinaro","Claude Zidi"],"b":2,"a":"Louis de Funès avait joué la pièce au théâtre des centaines de fois avant le film.","c":"Cinéma & séries","d":4},{"id":"342a17zy","t":"Sur quel réseau américain « Les Simpson » ont-ils débuté en 1989 ?","r":["NBC","CBS","Fox","ABC"],"b":2,"a":"Les personnages sont nés en courts métrages dans « The Tracey Ullman Show », avant d'obtenir leur propre série.","c":"Jeux & pop culture","d":4},{"id":"v2mi6hfp","t":"De quoi se nourrit surtout le phoque crabier, qui vit autour de l'Antarctique ?","r":["De crabes","De krill","De manchots","De poissons"],"b":1,"a":"Ses dents à multiples pointes s'emboîtent comme un tamis, ce qui lui permet de filtrer le krill.","c":"Nature","d":5},{"id":"fa4j0aak","t":"Qui a peint en 1787 « Marie-Antoinette et ses enfants », exposé à Versailles ?","r":["Jacques-Louis David","Francisco de Goya","Jean-Honoré Fragonard","Élisabeth Vigée Le Brun"],"b":3,"a":"Le berceau vide, que désigne le petit dauphin, rappelle la mort de la petite Sophie, survenue peu avant l'achèvement du tableau, ce qui rend la composition plus grave qu'une scène de famille officielle.","c":"Arts & lettres","d":5},{"id":"9vxqp466","t":"Dans une cuisine, comment appelle-t-on le revêtement mural qui protège le mur au-dessus du plan de travail ?","r":["La plinthe","La crédence","La corniche","Le chambranle"],"b":1,"a":"À l'origine, la crédence était un meuble où l'on posait les plats ; on y goûtait les mets pour s'assurer qu'ils n'étaient pas empoisonnés.","c":"Culture générale","d":4},{"id":"p8ja5bog","t":"Dans quelle langue est rédigée la devise « Dieu et mon droit », celle du monarque britannique ?","r":["Latin","Anglais","Français","Gaélique"],"b":2,"a":"Héritée du français parlé par la cour médiévale d'Angleterre, cette devise orne toujours les armoiries royales britanniques.","c":"Culture générale","d":5},{"id":"nbz4x6m2","t":"Quel langage de programmation pour le Web a été créé par Rasmus Lerdorf ?","r":["Ruby","Perl","PHP","Python"],"b":2,"a":"PHP voulait d'abord dire « Personal Home Page ». Il est devenu un acronyme récursif : « PHP: Hypertext Preprocessor ».","c":"Sciences","d":5},{"id":"27uvonmp","t":"En janvier 1961, trois mois avant Gagarine, quel animal la NASA envoie-t-elle dans l'espace lors d'un vol suborbital ?","r":["Un chien","Un chat","Un chimpanzé","Un cochon d'Inde"],"b":2,"a":"Le chimpanzé Ham avait été entraîné à actionner des leviers pendant le vol ; il fut récupéré vivant dans l'Atlantique.","c":"Histoire","d":5},{"id":"9n5odg7a","t":"Quelle personne détient le record du nombre d'Oscars remportés ?","r":["Steven Spielberg","Walt Disney","Katharine Hepburn","John Williams"],"b":1,"a":"Walt Disney a reçu la plupart de ses statuettes pour des courts métrages d'animation et des documentaires produits par son studio.","c":"Cinéma & séries","d":5},{"id":"208y96zn","t":"Quel art martial le chef Thierry Marx pratique-t-il, au point d'en être ceinture noire ?","r":["Le karaté","L'aïkido","Le judo","Le kendo"],"b":2,"a":"Thierry Marx a longtemps dirigé les cuisines du Mandarin Oriental à Paris, et il a séjourné au Japon.","c":"Cuisine","d":4},{"id":"qrpq7i13","t":"En quelle année l'International Rugby Board autorise-t-il le professionnalisme dans le rugby à XV ?","r":["1987","1991","1999","1995"],"b":3,"a":"Jusque-là amateur, le rugby à XV s'ouvre au professionnalisme quelques semaines après la Coupe du monde en Afrique du Sud.","c":"Sport","d":4},{"id":"565atc8u","t":"Quelle chanteuse a enregistré en 1939 « Strange Fruit », chanson contre le racisme aux États-Unis ?","r":["Bessie Smith","Ella Fitzgerald","Billie Holiday","Sarah Vaughan"],"b":2,"a":"La chanson vient d'un poème écrit par Abel Meeropol, un enseignant new-yorkais.","c":"Musique","d":4},{"id":"2hzd830p","t":"Quel pays désigne le code « CH » sur les autocollants et plaques d'immatriculation internationaux ?","r":["Chine","Suisse","Chili","Tchéquie"],"b":1,"a":"« CH » abrège le nom latin du pays, Confoederatio Helvetica, ce qui évite de choisir entre ses langues nationales.","c":"Culture générale","d":4},{"id":"1e4ur7ko","t":"Quel pays abrite l'essentiel du delta du Danube ?","r":["Roumanie","Bulgarie","Serbie","Hongrie"],"b":0,"a":"Ce delta est inscrit au patrimoine mondial de l'Unesco.","c":"Géographie","d":5},{"id":"1k9ymfzn","t":"Quelle pierre rouge sombre est associée au mois de naissance de janvier ?","r":["Rubis","Grenat","Corail","Améthyste"],"b":1,"a":"Son nom vient du latin granatum, « grenade », car ses petits cristaux ressemblent aux grains du fruit.","c":"Autour de la fête","d":4},{"id":"mfiue4o4","t":"Quel poète artésien a composé vers 1280 Le Jeu de Robin et Marion, pastourelle mêlée de chansons ?","r":["Rutebeuf","Jean Bodel","Chrétien de Troyes","Adam de la Halle"],"b":3,"a":"Cette pièce est souvent présentée comme l'un des ancêtres de l'opéra-comique, car ses dialogues alternent avec des chansons.","c":"Arts & lettres","d":5},{"id":"an8pfybo","t":"Quel film a reçu la Palme d'or du Festival de Cannes en 1994 ?","r":["Pulp Fiction","Barton Fink","Sailor et Lula","Sexe, Mensonges et Vidéo"],"b":0,"a":"Quentin Tarantino a reçu la Palme d'or pour ce film en 1994, sous la présidence de Clint Eastwood.","c":"Cinéma & séries","d":5},{"id":"04wn02pz","t":"Quel conifère californien est surnommé « l'arbre mammouth » ?","r":["Le douglas","Le séquoia géant","Le cèdre du Liban","Le pin de Monterey"],"b":1,"a":"Certains individus ont plus de 3 000 ans, et leur écorce épaisse résiste au feu.","c":"Nature","d":4},{"id":"ni5k7sbp","t":"Quel chanteur brésilien a lancé le mouvement tropicaliste avec Gilberto Gil, à la fin des années 1960 ?","r":["João Gilberto","Caetano Veloso","Jorge Ben","Chico Buarque"],"b":1,"a":"Jugés subversifs par la dictature militaire, les deux chanteurs ont été emprisonnés puis exilés à Londres en 1969.","c":"Musique","d":4},{"id":"1r5efxqa","t":"Quelle grande ville d'Auvergne est réputée depuis des siècles pour ses pâtes de fruits ?","r":["Aurillac","Le Puy-en-Velay","Clermont-Ferrand","Montluçon"],"b":2,"a":"Les vergers de la Limagne, riches en abricots, ont fourni les fruits de cette tradition confiseuse.","c":"Cuisine","d":5},{"id":"xyz27zog","t":"Quel peintre italien, précurseur du surréalisme, est célèbre pour ses places désertes aux ombres longues et ses mannequins ?","r":["Giorgio de Chirico","Amedeo Modigliani","Giorgio Morandi","Gino Severini"],"b":0,"a":"Il a baptisé son style « peinture métaphysique » vers 1910, et les surréalistes l'ont admiré.","c":"Arts & lettres","d":5},{"id":"882cigt5","t":"Quel architecte américain a bâti en Pennsylvanie la maison de la Cascade, au-dessus d'une chute d'eau, dans les années 1930 ?","r":["Richard Neutra","Frank Lloyd Wright","Louis Sullivan","Philip Johnson"],"b":1,"a":"La maison fut commandée par Edgar Kaufmann, propriétaire d'un grand magasin de Pittsburgh, comme résidence de week-end.","c":"Arts & lettres","d":5},{"id":"lqbdafdf","t":"Qui a réalisé le film « Des hommes et des dieux », sorti en 2010 sur des moines en Algérie ?","r":["Stéphane Brizé","Xavier Beauvois","Jean-François Richet","Michel Hazanavicius"],"b":1,"a":"Le film a reçu le Grand Prix du Festival de Cannes 2010. Il s'inspire de l'histoire des moines de Tibhirine, enlevés en 1996.","c":"Cinéma & séries","d":4},{"id":"m7gq1v47","t":"Dans « La Guerre des étoiles » (1977), quel personnage étrangle un officier à distance en lui reprochant son « manque de foi » ?","r":["L'Empereur","Grand Moff Tarkin","Dark Vador","Le comte Dooku"],"b":2,"a":"Dark Vador est joué physiquement par David Prowse, mais sa voix originale est celle de James Earl Jones.","c":"Cinéma & séries","d":4},{"id":"xrzlkgad","t":"Quel studio texan a créé le jeu de tir Doom, en 1993 ?","r":["Epic Games","id Software","Valve","Blizzard"],"b":1,"a":"Doom a été diffusé en partie en shareware, ce qui a fait sa fortune.","c":"Jeux & pop culture","d":4},{"id":"uytyook1","t":"Quel gaz injecte-t-on dans le ventre lors d'une cœlioscopie pour y ménager de la place au chirurgien ?","r":["Le dioxyde de carbone","L'oxygène","L'azote","L'hélium"],"b":0,"a":"Le ventre gonfle comme un ballon ; l'opération se fait par de minuscules incisions, d'où des cicatrices très discrètes.","c":"Sciences","d":4},{"id":"d8zplutl","t":"Quelle capitale est desservie par l'aéroport d'Arlanda ?","r":["Oslo","Helsinki","Stockholm","Copenhague"],"b":2,"a":"Arlanda se trouve au nord de Stockholm ; un train express, l'Arlanda Express, le relie au centre-ville.","c":"Culture générale","d":4},{"id":"nkqaing1","t":"Quel outil se dit « sierra » en espagnol, ce qui a donné leur nom aux chaînes de montagnes ?","r":["Une scie","Un marteau","Un rabot","Une pince"],"b":0,"a":"Une chaîne de montagnes se dit aussi « sierra » car ses sommets alignés rappellent les dents d'une scie.","c":"Culture générale","d":4},{"id":"jd3xih5i","t":"Comment s'appellent les pores sensibles aux champs électriques sur le museau du requin ?","r":["L'appareil de Weber","La ligne de Müller","Les nageoires de Corti","Les ampoules de Lorenzini"],"b":3,"a":"Ils lui permettent de détecter la proie cachée sous le sable, par les faibles champs que produit son corps.","c":"Nature","d":5},{"id":"nzgybvi0","t":"Dans Les Trois Mousquetaires, quelle espionne au service du cardinal de Richelieu porte une fleur de lys marquée à l'épaule ?","r":["Milady de Winter","Constance Bonacieux","Anne d'Autriche","La Reine Margot"],"b":0,"a":"Les Trois Mousquetaires est paru en feuilleton dans le journal Le Siècle, en 1844, avant d'être publié en volumes.","c":"Arts & lettres","d":4},{"id":"y0ac4zg8","t":"Sur un voilier, comment s'appelle le cordage qui sert à régler l'angle d'une voile ?","r":["La drisse","L'écoute","Le hauban","L'amarre"],"b":1,"a":"Border l'écoute, c'est la tirer pour rapprocher la voile de l'axe du bateau ; la choquer, c'est la relâcher.","c":"Sport","d":5},{"id":"ne570f3e","t":"Quel film de Federico Fellini a reçu en 1957 le premier Oscar du meilleur film en langue étrangère décerné en compétition ?","r":["La Dolce Vita","La Strada","Huit et demi","Amarcord"],"b":1,"a":"Giulietta Masina, épouse du réalisateur, y joue la jeune Gelsomina.","c":"Cinéma & séries","d":5},{"id":"izmukz76","t":"Sur combien de bits est codée une adresse IPv6 ?","r":["64","128","256","32"],"b":1,"a":"Une adresse IPv6 s'écrit en huit groupes de quatre chiffres hexadécimaux séparés par deux-points.","c":"Sciences","d":4},{"id":"vksuz9h8","t":"Quelle ville du centre de l'Anatolie était la capitale de l'Empire hittite ?","r":["Ninive","Babylone","Hattusa","Troie"],"b":2,"a":"Ses tablettes d'argile ont livré l'un des plus anciens traités de paix connus, conclu avec l'Égypte.","c":"Histoire","d":4},{"id":"gw8kd72c","t":"Qui a réalisé le film « Spider-Man: No Way Home », sorti en 2021 ?","r":["Greta Gerwig","Jon Watts","Wes Ball","Jon Chu"],"b":1,"a":"Tom Holland y retrouve Tobey Maguire et Andrew Garfield, interprètes précédents de l'homme-araignée.","c":"Cinéma & séries","d":4},{"id":"pyn3mzsu","t":"Qui a écrit l'essai « Le Droit à la paresse », publié en 1880 ?","r":["Alphonse Daudet","Anatole France","Émile Zola","Paul Lafargue"],"b":3,"a":"Son auteur était le gendre de Karl Marx, dont il avait épousé la fille Laura.","c":"Arts & lettres","d":5},{"id":"xdtya8eh","t":"Dans quel pays se trouvent les ruines de Hampi, ancienne capitale de l'empire de Vijayanagara ?","r":["Sri Lanka","Inde","Népal","Cambodge"],"b":1,"a":"Les ruines parsèment un paysage de blocs de granit, au bord de la rivière Tungabhadra.","c":"Géographie","d":5},{"id":"ber1sef4","t":"Dans quel pays se dresse le Ruapehu, volcan actif et plus haut sommet de son île du Nord ?","r":["Chili","Nouvelle-Zélande","Japon","Islande"],"b":1,"a":"Les paysages volcaniques du parc national de Tongariro, où se dresse le Ruapehu, ont servi de décor au Mordor dans « Le Seigneur des anneaux ».","c":"Géographie","d":4},{"id":"xw240zxw","t":"Quelle ville est la capitale de l'Éthiopie ?","r":["Asmara","Djibouti","Khartoum","Addis-Abeba"],"b":3,"a":"La ville accueille le siège de l'Union africaine ; son nom signifie « nouvelle fleur » en amharique.","c":"Géographie","d":4},{"id":"mu0q7hd5","t":"Dans quelle langue souhaite-t-on un joyeux anniversaire en disant « Doğum günün kutlu olsun » ?","r":["En turc","En grec","En persan","En azéri"],"b":0,"a":"Les Turcs disent aussi volontiers « İyi ki doğdun », littéralement « heureusement que tu es né ».","c":"Autour de la fête","d":4},{"id":"y7wf3zpr","t":"Quelle aire du cerveau, dont la lésion empêche de parler, porte le nom d'un médecin français ?","r":["L'aire de Wernicke","L'aire de Brodmann","L'aire de Penfield","L'aire de Broca"],"b":3,"a":"Paul Broca l'a localisée en 1861 en étudiant le cerveau d'un patient surnommé « Tan », seule syllabe qu'il prononçait.","c":"Sciences","d":5},{"id":"e8f6r742","t":"Quelle famille de médicaments antibactériens de synthèse a été lancée dans les années 1930 avec le Prontosil de Gerhard Domagk ?","r":["Pénicillines","Tétracyclines","Macrolides","Sulfamides"],"b":3,"a":"Domagk a reçu le Nobel de médecine en 1939 mais, sous le régime nazi, n'a pu le recevoir qu'après la guerre.","c":"Sciences","d":4},{"id":"cs91b7y5","t":"Quel instrument à cordes pincées, au dos bombé et au chevillier coudé vers l'arrière, régnait sur la musique de la Renaissance ?","r":["Cistre","Luth","Viole de gambe","Vielle à roue"],"b":1,"a":"Le mot « luthier » vient du luth : on désignait d'abord ainsi l'artisan qui fabriquait cet instrument.","c":"Musique","d":4},{"id":"jlbqh7wh","t":"Dans un clan de hyènes tachetées, qui domine les autres ?","r":["Le mâle le plus âgé","Le mâle le plus fort","Une femelle","Le plus jeune adulte"],"b":2,"a":"Les femelles sont un peu plus grandes que les mâles ; les petits héritent du rang de leur mère.","c":"Nature","d":5}],"mots":[{"id":"1wgifuwt","t":"Quelle ville est la capitale de la Lituanie ?","m":"VILNIUS","aff":"Vilnius","a":"Son centre historique est inscrit au patrimoine mondial de l'UNESCO depuis 1994.","c":"Géographie"},{"id":"cja5es3o","t":"Dans quel pays la fondue au fromage, où l'on trempe des morceaux de pain dans un caquelon, est-elle un plat national ?","m":"SUISSE","aff":"Suisse","a":"La fondue moitié-moitié associe à parts égales du gruyère et du vacherin fribourgeois.","c":"Cuisine"},{"id":"utgb6203","t":"Quel produit laitier est la base du tzatziki grec, relevé d'ail et de concombre ?","m":"YAOURT","aff":"yaourt","a":"On le sert en entrée avec du pain pita, ou en accompagnement de viandes grillées.","c":"Cuisine"},{"id":"vjxhb5pu","t":"Dans une fable de La Fontaine, quelle plante, face à la tempête, « plie, et ne rompt pas », au contraire du chêne ?","m":"ROSEAU","aff":"Roseau","a":"La fable figure dans le premier livre des Fables, paru en 1668 ; elle s'achève sur le chêne déraciné par le vent.","c":"Arts & lettres"},{"id":"fw2nrdcr","t":"En boxe, quel instrument sonne le début et la fin de chaque reprise ?","m":"CLOCHE","aff":"cloche","a":"L'expression « sauvé par le gong » vient de la boxe : un boxeur au tapis échappe au compte quand la reprise se termine.","c":"Sport"},{"id":"k5gibwoi","t":"Quel cousin de Frodon rejoint la Communauté de l'anneau en même temps que Pippin ?","m":"MERRY","aff":"Merry","a":"Dans les livres, Merry s'appelle en réalité Meriadoc Brandebouc, et Pippin, Peregrin Touque.","c":"Cinéma & séries"},{"id":"6q7gz789","t":"Comment appelle-t-on une substance sans principe actif, donnée dans un essai pour être comparée à un vrai médicament ?","m":"PLACEBO","aff":"Placebo","a":"Placebo est un mot latin qui signifie « je plairai » : l'effet vient de la confiance du patient, non de la substance.","c":"Sciences"},{"id":"bsdld5s6","t":"Combien de côtés un triangle a-t-il ?","m":"TROIS","aff":"Trois","a":"Le mot vient du latin tri, « trois », et angulus, « angle ».","c":"Sciences"},{"id":"v80xbzws","t":"Dans quelle ville se trouve Buckingham Palace, résidence officielle des souverains britanniques ?","m":"LONDRES","aff":"Londres","a":"Devant le palais a lieu la relève de la garde, assurée par des soldats coiffés de hauts bonnets en fourrure noire.","c":"Géographie"},{"id":"31213p7r","t":"Parmi ces sources d'énergie, laquelle est une énergie fossile ?","m":"CHARBON","aff":"charbon","a":"Le charbon s'est formé pendant des millions d'années à partir de végétaux enfouis, ce qui le rend impossible à renouveler à l'échelle humaine.","c":"Nature"},{"id":"2nszub3c","t":"Sur quel appareil le DJ fait-il tourner ses disques vinyles ?","m":"PLATINE","aff":"platine","a":"Les DJ font glisser le disque sous la main pour caler le morceau suivant et enchaîner sans temps mort.","c":"Autour de la fête"},{"id":"az0ma3f4","t":"Quel instrument de percussion à peau, frappé avec deux baguettes, bat la marche dans les défilés militaires ?","m":"TAMBOUR","aff":"tambour","a":"Sur les champs de bataille d'autrefois, le tambour transmettait les ordres aux soldats malgré le vacarme.","c":"Musique"},{"id":"k5soin9g","t":"Comment appelle-t-on la cuisson d'une viande au four ou à la broche, à chaleur vive et sans liquide ?","m":"ROTIR","aff":"Rôtir","a":"Pendant la cuisson, on arrose souvent un rôti de son propre jus pour l'empêcher de se dessécher.","c":"Cuisine"},{"id":"0o6t8vqo","t":"Quelle marque italienne de moto, basée à Bologne, est célèbre pour ses machines rouges de course ?","m":"DUCATI","aff":"Ducati","a":"Son usine est à Borgo Panigale, un quartier de Bologne.","c":"Sport"},{"id":"6rbf0zhk","t":"Quel personnage de « Friends » est joué par Lisa Kudrow ?","m":"PHOEBE","aff":"Phoebe","a":"Phoebe chante au café ses propres chansons, dont la célèbre « Smelly Cat ».","c":"Cinéma & séries"},{"id":"ryfyndfa","t":"Comment appelle-t-on le professeur dans les arts martiaux japonais ?","m":"SENSEI","aff":"Sensei","a":"Au Japon, le mot s'emploie aussi pour les instituteurs, les médecins ou les avocats.","c":"Sport"},{"id":"n4qx7h7e","t":"De quelle pierre grise, qui se fend en plaques fines, sont couverts les toits traditionnels de Bretagne et d'Anjou ?","m":"ARDOISE","aff":"ardoise","a":"Les ardoisières de Trélazé, près d'Angers, ont fourni pendant des siècles une grande partie des ardoises de France.","c":"Arts & lettres"},{"id":"d2h03zxd","t":"Comment appelle-t-on le tapis sur lequel se déroule un combat de judo ?","m":"TATAMI","aff":"tatami","a":"À l'origine, ce mot désigne la natte de paille de riz qui couvre le sol des maisons japonaises traditionnelles.","c":"Sport"},{"id":"pmnlwre2","t":"Comment nomme-t-on un triangle qui a deux côtés de même longueur ?","m":"ISOCELE","aff":"Isocèle","a":"Le mot « isocèle » vient du grec et signifie « aux jambes égales ».","c":"Sciences"},{"id":"yb8ha06z","t":"Quelle fleur est l'emblème des Pays-Bas, cultivée en immenses champs colorés ?","m":"TULIPE","aff":"Tulipe","a":"Originaire d'Asie centrale, elle a provoqué en Hollande une spéculation folle, la tulipomanie, en 1636-1637.","c":"Nature"},{"id":"d2okxiij","t":"Quel oiseau blanc, symbole de la paix, est souvent représenté avec un rameau d'olivier ?","m":"COLOMBE","aff":"colombe","a":"Picasso a dessiné une colombe pour l'affiche du Congrès mondial de la paix, à Paris, en 1949.","c":"Nature"},{"id":"1x6zy84a","t":"Au basket, comment appelle-t-on le geste défensif qui consiste à repousser de la main le tir d'un adversaire ?","m":"CONTRE","aff":"contre","a":"Un contre n'est valable que si le ballon n'a pas commencé à redescendre vers le panier : sinon, c'est une interférence et le panier est accordé.","c":"Sport"},{"id":"wn8s81f4","t":"Comment s'appelle la haute coiffe blanche que portent les cuisiniers ?","m":"TOQUE","aff":"toque","a":"Selon une tradition, les cent plis de la toque évoquent les cent façons d'accommoder un œuf.","c":"Cuisine"},{"id":"6jgbj9oa","t":"Dans le conte norvégien des trois boucs, quelle créature vit sous le pont que les boucs veulent traverser ?","m":"TROLL","aff":"troll","a":"Ce conte a été recueilli au XIXe siècle en Norvège par Peter Christen Asbjørnsen et Jørgen Moe, souvent comparés aux frères Grimm.","c":"Culture générale"},{"id":"2dmgygx8","t":"Quel arbre extraterrestre des « Gardiens de la Galaxie » ne dit jamais qu'une phrase, toujours la même ?","m":"GROOT","aff":"Groot","a":"Dans la version originale, Groot est doublé par Vin Diesel, qui prononce toujours la même phrase avec des intonations variées.","c":"Cinéma & séries"},{"id":"fdbzrjdu","t":"Dans la version française de « Scooby-Doo », comment s'appelle le grand ami gourmand et peureux du chien ?","m":"SAMMY","aff":"Sammy","a":"En version originale, le personnage s'appelle Shaggy, un surnom qui évoque ses cheveux en bataille.","c":"Autour de la fête"},{"id":"odfzrxw8","t":"Quelle ville est la capitale de la république d'Irlande ?","m":"DUBLIN","aff":"Dublin","a":"Son nom irlandais, Baile Átha Cliath, signifie « la ville du gué aux claies ».","c":"Géographie"},{"id":"ogfua985","t":"Quel minéral, abondant dans le lait, rend les os et les dents solides ?","m":"CALCIUM","aff":"calcium","a":"Presque tout le calcium du corps est stocké dans le squelette et les dents.","c":"Sciences"},{"id":"3widbsgg","t":"Comment appelle-t-on le cri du cerf à la saison des amours ?","m":"BRAME","aff":"brame","a":"Le brame s'entend surtout en septembre et en octobre, à la tombée de la nuit : les mâles y défient leurs rivaux.","c":"Nature"},{"id":"6k93qwlq","t":"Quel monstre des légendes se nourrit du sang de ses victimes ?","m":"VAMPIRE","aff":"vampire","a":"Dans de nombreuses légendes, le vampire ne se reflète pas dans les miroirs et craint la lumière du jour.","c":"Autour de la fête"},{"id":"b7o33rfn","t":"Quel animal est Titi, le petit personnage jaune que Grosminet cherche à croquer ?","m":"CANARI","aff":"canari","a":"Dans ses toutes premières apparitions, Titi était rose et n'avait pas de plumes : sa couleur jaune est venue plus tard.","c":"Cinéma & séries"},{"id":"6b7h77jc","t":"Quel gaz de l'air entretient la combustion et la respiration ?","m":"OXYGENE","aff":"oxygène","a":"Lavoisier a montré que ce gaz est l'agent de la combustion et l'a baptisé oxygène.","c":"Sciences"},{"id":"ss9bzv8j","t":"De quel lait le roquefort est-il fait exclusivement ?","m":"BREBIS","aff":"Brebis","a":"Le fromage mûrit dans les caves naturelles de Roquefort-sur-Soulzon ; sa pâte est ensemencée avec une moisissure appelée Penicillium roqueforti.","c":"Cuisine"},{"id":"zh1xm7pv","t":"Que doit soutenir un étudiant en médecine pour obtenir le titre de docteur en médecine en France ?","m":"THESE","aff":"thèse","a":"On dit « docteur » pour un médecin, même si le titre vient de la thèse soutenue en fin d'études.","c":"Culture générale"},{"id":"beh82hdu","t":"Quel instrument joue le célèbre riff du thème de James Bond ?","m":"GUITARE","aff":"guitare","a":"Le riff a été joué par le guitariste Vic Flick pour le film de 1962, puis arrangé par John Barry.","c":"Musique"},{"id":"ipuy2szb","t":"De quelle couleur sont les boîtes aux lettres de La Poste en France ?","m":"JAUNE","aff":"Jaune","a":"Au Royaume-Uni, les boîtes aux lettres sont rouges.","c":"Culture générale"},{"id":"bypcg6a3","t":"Quelle baie séchée, noire et piquante, est l'épice la plus utilisée au monde ?","m":"POIVRE","aff":"poivre","a":"Au Moyen Âge, on pouvait payer un loyer, une dot ou une rançon en grains de poivre.","c":"Cuisine"},{"id":"xvvdijtv","t":"Quel pays est associé au kilt, jupe à carreaux masculine, et à la cornemuse ?","m":"ECOSSE","aff":"Écosse","a":"Chaque motif de tartan est traditionnellement associé à un clan ou à une famille.","c":"Géographie"},{"id":"yrptypko","t":"Comment s'appelle le gentil petit fantôme blanc des dessins animés et du cinéma, au nom proche de Gaspard ?","m":"CASPER","aff":"Casper","a":"Créé à la fin des années 1930, il a connu plusieurs séries animées et un film en 1995.","c":"Autour de la fête"},{"id":"ulz4d2a8","t":"Quelle plante est l'emblème de l'Irlande ?","m":"TREFLE","aff":"trèfle","a":"On l'arbore chaque 17 mars, jour de la Saint-Patrick, fêtée bien au-delà de l'Irlande.","c":"Culture générale"},{"id":"xgntshpp","t":"Dans quelle ville se trouve le stade du Dragon, antre de l'un des trois grands clubs portugais ?","m":"PORTO","aff":"Porto","a":"Son nom rappelle le dragon qui surmonte l'écusson du club.","c":"Sport"},{"id":"2c6xha76","t":"Quel pays d'Europe a la forme d'une botte ?","m":"ITALIE","aff":"Italie","a":"La Sicile, plus grande île de la Méditerranée, est le « ballon » que la botte semble frapper.","c":"Géographie"},{"id":"qwc2v8x9","t":"Quel champignon souterrain, surnommé « diamant noir », est cherché avec l'aide d'un chien ou d'un cochon ?","m":"TRUFFE","aff":"truffe","a":"On utilise aujourd'hui plus volontiers des chiens, car les cochons ont tendance à manger la truffe qu'ils trouvent.","c":"Cuisine"},{"id":"q9dxurwr","t":"Quel titre portait le souverain de l'Empire ottoman ?","m":"SULTAN","aff":"Sultan","a":"Le dernier sultan quitta le pays en 1922 ; la République turque fut proclamée l'année suivante.","c":"Histoire"},{"id":"k9hg0094","t":"Quel animal marin, très intelligent, aime nager à l'étrave des bateaux en sautant hors de l'eau ?","m":"DAUPHIN","aff":"dauphin","a":"Les dauphins accompagnent souvent les navires pour profiter de la vague que l'étrave pousse devant elle, ce qui leur évite de dépenser trop d'énergie.","c":"Nature"},{"id":"n7klmkk9","t":"Quelle est la couleur de la bande centrale du drapeau italien ?","m":"BLANCHE","aff":"Blanche","a":"Le Tricolore s'inspire du drapeau français, que les armées révolutionnaires ont fait connaître en Italie à la fin du XVIIIe siècle.","c":"Géographie"},{"id":"kcw4e6my","t":"De quel pays vient la marque de vêtements Uniqlo ?","m":"JAPON","aff":"Japon","a":"Le nom Uniqlo est la contraction de « Unique Clothing Warehouse », le nom de sa première boutique.","c":"Jeux & pop culture"},{"id":"upstjszb","t":"Quel dieu égyptien à tête de chacal préside à l'embaumement des morts ?","m":"ANUBIS","aff":"Anubis","a":"On pense que les chacals qui rôdaient près des tombes ont inspiré son image de gardien des nécropoles.","c":"Culture générale"},{"id":"hnl0yofe","t":"Quel grand pays d'Amérique du Sud a été une colonie portugaise et en parle encore la langue ?","m":"BRESIL","aff":"Brésil","a":"Le Brésil est le seul pays d'Amérique du Sud dont le portugais soit la langue officielle.","c":"Histoire"},{"id":"0z8tbv6c","t":"Complétez le proverbe : « Pierre qui roule n'amasse pas… »","m":"MOUSSE","aff":"mousse","a":"Le proverbe anglais équivalent est « A rolling stone gathers no moss ».","c":"Culture générale"},{"id":"jqivqdw1","t":"Comment appelle-t-on les quatre dents pointues placées entre les incisives et les prémolaires ?","m":"CANINES","aff":"canines","a":"Leur racine est la plus longue de toutes les dents humaines.","c":"Sciences"},{"id":"q7gddkfc","t":"Quel peuple venu de Scandinavie mène des raids sur les côtes d'Europe à partir de la fin du VIIIe siècle ?","m":"VIKINGS","aff":"Vikings","a":"Les Vikings remontaient aussi les fleuves : ils ont assiégé Paris en 885-886 en remontant la Seine.","c":"Histoire"},{"id":"vw0fib2e","t":"Comment dit-on « merci » en espagnol ?","m":"GRACIAS","aff":"Gracias","a":"« Gracias » vient du latin gratia, comme « grâce » en français ; « muchas gracias » dit « merci beaucoup ».","c":"Culture générale"},{"id":"36gxcqgj","t":"Quel petit oiseau jaune est souvent élevé en cage pour son joli chant ?","m":"CANARI","aff":"canari","a":"Le canari domestique descend du serin des Canaries, un oiseau sauvage des îles atlantiques dont il porte le nom.","c":"Nature"},{"id":"whfbsf2i","t":"Quel est le comparatif de supériorité de l'adjectif « good » ?","m":"BETTER","aff":"better","a":"Comme « bon » et « meilleur » en français, good et better viennent de racines différentes.","c":"Culture générale"},{"id":"uja8yf0s","t":"Au karaté, quelle couleur de ceinture distingue les pratiquants confirmés, à partir du premier dan ?","m":"NOIRE","aff":"Noire","a":"Le système des ceintures colorées vient du judo : le karaté l'a adopté au XXe siècle, en même temps que les grades en dan.","c":"Sport"},{"id":"m753afll","t":"Quel fruit jaune, célébré par une fête chaque hiver, fait la renommée de la ville de Menton ?","m":"CITRON","aff":"citron","a":"La fête du Citron, à la fin de l'hiver, couvre chars et sculptures de milliers d'agrumes.","c":"Cuisine"},{"id":"n79y6qp2","t":"Quel instrument à cordes pincées a pour caisse de résonance un cercle tendu d'une membrane, comme un tambourin ?","m":"BANJO","aff":"banjo","a":"Ses ancêtres viennent d'Afrique de l'Ouest, d'où des esclaves les ont emportés vers l'Amérique.","c":"Musique"},{"id":"ssnal1mq","t":"Quel chien de bande dessinée, créé par Charles M. Schulz, se rêve en as de l'aviation ?","m":"SNOOPY","aff":"Snoopy","a":"Juché sur sa niche, qu'il prend pour un avion, il rejoue sans fin ses duels contre le Baron rouge.","c":"Arts & lettres"},{"id":"x7nyup7v","t":"Quel insecte fabrique le miel ?","m":"ABEILLE","aff":"abeille","a":"Pour faire le miel, les abeilles butinent le nectar des fleurs puis le stockent dans les alvéoles de la ruche, où il s'épaissit.","c":"Nature"},{"id":"90x4y3h4","t":"Quel dessert aux fruits est recouvert d'une pâte sableuse émiettée, faite de beurre, de sucre et de farine ?","m":"CRUMBLE","aff":"crumble","a":"Le crumble serait né en Angleterre pendant la Seconde Guerre mondiale, quand le rationnement rendait la pâte à tarte trop coûteuse.","c":"Cuisine"},{"id":"bb13i8vz","t":"Quel gaz, plus léger que l'air et ininflammable, gonfle les ballons de fête ?","m":"HELIUM","aff":"hélium","a":"Inhalé, il rend la voix plus aiguë, car le son s'y propage plus vite que dans l'air.","c":"Sciences"},{"id":"mj989x0a","t":"Quelle forme ont la plupart des panneaux routiers d'interdiction ?","m":"RONDE","aff":"Ronde","a":"Les panneaux d'interdiction sont ronds à bordure rouge, ceux de danger triangulaires.","c":"Culture générale"},{"id":"bmzi4kg5","t":"Dans le conte de Perrault, qu'apporte le Petit Chaperon rouge à sa mère-grand, avec un petit pot de beurre ?","m":"GALETTE","aff":"galette","a":"Chez Perrault, l'histoire finit mal et se clôt sur une morale ; le chasseur qui sauve tout le monde vient de la version des frères Grimm.","c":"Arts & lettres"},{"id":"x3ucy543","t":"Dans le conte d'Ali Baba, quel mot magique fait s'ouvrir la caverne des quarante voleurs ?","m":"SESAME","aff":"Sésame","a":"Le mot est passé dans le langage courant : un « sésame » désigne un moyen infaillible d'ouvrir une porte ou d'obtenir un accès.","c":"Culture générale"},{"id":"bl0iu6dk","t":"Quels instruments, des calebasses garnies de graines que l'on secoue par paires, rythment la musique cubaine ?","m":"MARACAS","aff":"maracas","a":"À l'origine, les maracas étaient fabriquées avec des fruits séchés de calebassier remplis de graines ou de petits cailloux.","c":"Musique"},{"id":"azxm2kfq","t":"Sur quelle plateforme en ligne regarde-t-on des vidéos de millions de créateurs, des clips aux tutoriels ?","m":"YOUTUBE","aff":"YouTube","a":"La première vidéo, « Me at the zoo », a été mise en ligne en avril 2005 et dure moins de vingt secondes.","c":"Sciences"},{"id":"ni7ljh32","t":"Quelle marque italienne de voitures de sport a pour emblème un cheval noir cabré sur fond jaune ?","m":"FERRARI","aff":"Ferrari","a":"Le cheval vient de l'avion de l'as de la Première Guerre mondiale Francesco Baracca ; sa mère l'aurait proposé à Enzo Ferrari.","c":"Culture générale"},{"id":"dkxx0l1m","t":"Comment s'appelle l'os de la cuisse ?","m":"FEMUR","aff":"fémur","a":"Le fémur est l'os le plus long et le plus solide du squelette humain.","c":"Sciences"},{"id":"ivlm2kvd","t":"Quel ustensile sert à retourner une crêpe dans la poêle ?","m":"SPATULE","aff":"spatule","a":"La spatule en bois ne raye pas les poêles antiadhésives, contrairement aux modèles en métal.","c":"Cuisine"},{"id":"mdx0kwsu","t":"Comment appelle-t-on une montagne d'où peuvent jaillir de la lave, des cendres et des gaz brûlants ?","m":"VOLCAN","aff":"volcan","a":"Le mot volcan vient de Vulcain, le dieu romain du feu et de la forge, qui avait son atelier sous la terre selon la légende.","c":"Géographie"},{"id":"ldjx5pnz","t":"Quel oiseau de la ferme « glougloute » ?","m":"DINDON","aff":"dindon","a":"Le dindon mâle fait la roue comme le paon pour séduire les femelles, en gonflant son plumage.","c":"Nature"},{"id":"udyk9lpc","t":"Que signifie le mot espagnol « vaso » ?","m":"VERRE","aff":"Verre","a":"Le vase se dit « jarrón » ou « florero » en espagnol.","c":"Culture générale"},{"id":"kqmbcfat","t":"Comment appelle-t-on le spectacle où des chanteurs racontent une histoire en chantant, accompagnés par un orchestre ?","m":"OPERA","aff":"opéra","a":"L'opéra est né en Italie vers 1600, et l'un des premiers chefs-d'œuvre du genre est l'« Orfeo » de Monteverdi.","c":"Musique"},{"id":"k5iui5ni","t":"Quel peuple antique a construit le Colisée ?","m":"ROMAINS","aff":"Romains","a":"Il pouvait accueillir des dizaines de milliers de spectateurs, répartis selon leur rang social.","c":"Histoire"},{"id":"0xh396gl","t":"Comment nomme-t-on la tour d'une église où sont suspendues les cloches ?","m":"CLOCHER","aff":"clocher","a":"Une cloche fixée au clocher sonnait autrefois les heures, les fêtes et les alertes, comme le tocsin en cas d'incendie.","c":"Arts & lettres"},{"id":"z1uqs95l","t":"Quel animal est la mascotte du système libre Linux, nommée Tux ?","m":"MANCHOT","aff":"manchot","a":"Tux a été dessiné par Larry Ewing en 1996, avec le logiciel de dessin GIMP.","c":"Jeux & pop culture"},{"id":"xubtojbp","t":"Comment appelle-t-on la femelle du loup ?","m":"LOUVE","aff":"louve","a":"Selon la légende, une louve aurait allaité Romulus et Rémus, les jumeaux fondateurs de Rome.","c":"Nature"},{"id":"hfal81as","t":"Quel instrument à clavier a des touches blanches et noires et des marteaux qui frappent des cordes ?","m":"PIANO","aff":"Piano","a":"Les marteaux du piano sont garnis de feutre, ce qui adoucit l'attaque de la corde.","c":"Musique"},{"id":"iqc4qnur","t":"Quel condiment vert et très piquant accompagne les sushis ?","m":"WASABI","aff":"wasabi","a":"Le vrai wasabi se râpe sur une peau de requin séchée ; beaucoup de pâtes vendues sont du raifort teinté.","c":"Cuisine"}],"filet":[{"id":"djvhrlzq","t":"En quelle année a été fondée à Paris la Chambre syndicale de la couture, ancêtre de la Fédération de la haute couture ?","v":1868,"u":"","annee":true,"a":"Le couturier Charles Frederick Worth a joué un rôle clé dans l'organisation de la profession à Paris.","c":"Jeux & pop culture"},{"id":"5ykdpeji","t":"En quelle année commence la première saison de « Downton Abbey » ?","v":2010,"u":"","annee":true,"a":"L'intrigue démarre avec le naufrage du Titanic, où meurt l'héritier du domaine ; le château de Highclere a servi de décor.","c":"Cinéma & séries"},{"id":"5eih9b6x","t":"En quelle année la Nintendo 64 est-elle sortie au Japon ?","v":1996,"u":"","annee":true,"a":"Elle est arrivée en Amérique du Nord en septembre 1996, avec Super Mario 64 en vedette.","c":"Jeux & pop culture"},{"id":"4juwwfag","t":"En quelle année le Sydney Harbour Bridge a-t-il été inauguré ?","v":1932,"u":"","annee":true,"a":"Les habitants de Sydney le surnomment « le Cintre », à cause de sa grande arche d'acier.","c":"Géographie"},{"id":"zc9c1v43","t":"En quelle année est sorti le tout premier The Legend of Zelda, au Japon ?","v":1986,"u":"","annee":true,"a":"La version américaine de la cartouche était dorée.","c":"Jeux & pop culture"},{"id":"qh8o6ki7","t":"En quelle année a eu lieu le concert Live Aid, en faveur de l'Éthiopie ?","v":1985,"u":"","annee":true,"a":"Organisé par Bob Geldof, il a été diffusé en direct dans le monde entier depuis Londres et Philadelphie.","c":"Musique"},{"id":"nemud7u9","t":"En quelle année éclate l'affaire Festina, scandale de dopage qui secoue le Tour de France ?","v":1998,"u":"","annee":true,"a":"Tout part de l'interpellation d'un soigneur de l'équipe à la frontière belge, quelques jours avant le départ, donné à Dublin.","c":"Sport"},{"id":"cjh2ri3c","t":"En quelle année se déroule la première saison de « Stranger Things » ?","v":2016,"u":"","annee":true,"a":"La série multiplie les clins d'œil aux années 1980, des films de Spielberg aux romans de Stephen King.","c":"Cinéma & séries"},{"id":"kn9tar4l","t":"En quelle année a été diffusé le premier grand gala télévisé de la fête du Printemps, rendez-vous du Nouvel An chinois ?","v":1983,"u":"","annee":true,"a":"Ce spectacle de la télévision d'État chinoise est regardé chaque année par des centaines de millions de téléspectateurs.","c":"Autour de la fête"},{"id":"kvosrmjd","t":"En quelle année « Casse-Noisette », de Tchaïkovski, a-t-il été créé à Saint-Pétersbourg ?","v":1892,"u":"","annee":true,"a":"Le ballet a été chorégraphié par Lev Ivanov, d'après un plan de Marius Petipa.","c":"Musique"},{"id":"oaxic3jf","t":"En quelle année Michael Jackson a-t-il dévoilé son moonwalk à la télévision, lors de l'émission « Motown 25 » ?","v":1983,"u":"","annee":true,"a":"Il a exécuté ce pas glissé à reculons en chantant « Billie Jean », lors d'un spectacle célébrant les 25 ans du label Motown.","c":"Musique"},{"id":"e1dd630x","t":"En quelle année Louis Braille publie-t-il son procédé d'écriture pour les aveugles ?","v":1829,"u":"","annee":true,"a":"Louis Braille avait perdu la vue enfant, après s'être blessé avec un outil dans l'atelier de son père, bourrelier à Coupvray.","c":"Culture générale"},{"id":"uw7oo9ri","t":"En quelle année le classement britannique des 50 meilleurs restaurants du monde est-il publié pour la première fois ?","v":2002,"u":"","annee":true,"a":"Ce classement est établi par les votes de plusieurs centaines de chefs, critiques et gastronomes voyageurs.","c":"Cuisine"},{"id":"8s8xnzu6","t":"En quelle année commence la guerre de Sept Ans, qui oppose notamment la France et la Grande-Bretagne ?","v":1756,"u":"","annee":true,"a":"Souvent décrite comme la première guerre vraiment mondiale, elle s'est jouée en Europe, en Amérique et en Inde.","c":"Histoire"},{"id":"2lsf2kyg","t":"En quelle année l'Office national des forêts a-t-il été créé ?","v":1964,"u":"","annee":true,"a":"Il gère les forêts publiques de l'État et des communes, soit environ un quart de la forêt française.","c":"Nature"},{"id":"dxcnxb38","t":"En quelle année est mort le luthier Antonio Stradivari ?","v":1737,"u":"","annee":true,"a":"Stradivari a travaillé jusqu'à un âge très avancé : certains de ses instruments les plus réputés datent de ses dernières décennies.","c":"Musique"},{"id":"71vrlii3","t":"En quelle année Valentino Rossi remporte-t-il son premier titre mondial dans la catégorie reine, alors le 500 cm3 ?","v":2001,"u":"","annee":true,"a":"Il est le dernier champion de l'ère des 500 cm3 deux-temps, remplacés dès l'année suivante par les MotoGP à quatre temps.","c":"Sport"},{"id":"fuiyeex5","t":"En quelle année sort le premier « Godzilla », film japonais d'Ishirō Honda ?","v":1954,"u":"","annee":true,"a":"Le monstre était joué par un acteur glissé dans un lourd costume, qui piétinait des maquettes de Tokyo.","c":"Cinéma & séries"},{"id":"8e70lhz5","t":"En quelle année Ferrero a-t-il lancé l'œuf en chocolat Kinder Surprise ?","v":1974,"u":"","annee":true,"a":"Le petit jouet est rangé dans une capsule jaune en plastique, au cœur de l'œuf.","c":"Jeux & pop culture"},{"id":"hnu8759d","t":"En quelle année une grande expédition sur le Yangzi n'a-t-elle trouvé aucun baiji, ce dauphin d'eau douce alors déclaré fonctionnellement éteint ?","v":2006,"u":"","annee":true,"a":"Le baiji est souvent présenté comme le premier cétacé que l'activité humaine a fait disparaître : pêche, barrages et trafic fluvial.","c":"Nature"},{"id":"jq86gdho","t":"En quelle année les Pèlerins du Mayflower ont-ils partagé avec les Wampanoags le repas des moissons considéré comme le premier Thanksgiving ?","v":1621,"u":"","annee":true,"a":"Ce festin de l'automne a duré trois jours, à Plymouth, dans l'actuel Massachusetts, et réunissait colons anglais et Amérindiens wampanoags.","c":"Autour de la fête"},{"id":"lo9rdk8y","t":"En quelle année le Système international d'unités reçoit-il son nom officiel, lors d'une conférence générale des poids et mesures ?","v":1960,"u":"","annee":true,"a":"Son abréviation, SI, est la même dans toutes les langues. Le système prolongeait le système métrique né sous la Révolution.","c":"Culture générale"},{"id":"dnkh9i6y","t":"En quelle année François Vatel, maître d'hôtel du prince de Condé, meurt-il à Chantilly ?","v":1671,"u":"","annee":true,"a":"On lui attribue souvent l'invention de la crème Chantilly, mais rien ne le prouve : la légende s'est bâtie après lui.","c":"Cuisine"},{"id":"o8zambhc","t":"En quelle année naît le Caprice des Dieux, fromage ovale à croûte fleurie ?","v":1956,"u":"","annee":true,"a":"Ce fromage est à l'origine du groupe Bongrain, devenu Savencia.","c":"Cuisine"},{"id":"w025epqu","t":"En quelle année les ordonnances fondatrices de la Sécurité sociale ont-elles été signées en France ?","v":1945,"u":"","annee":true,"a":"Les ordonnances, préparées par le haut fonctionnaire Pierre Laroque, sont signées sous le ministre Alexandre Parodi ; Ambroise Croizat, ministre du Travail à partir de novembre 1945, en conduit ensuite la mise en place.","c":"Culture générale"},{"id":"39ztpyng","t":"En quelle année sort « James Bond 007 contre Dr No », premier film de la saga ?","v":1962,"u":"","annee":true,"a":"La scène où Ursula Andress sort de la mer en bikini blanc, en Jamaïque, est devenue l'une des plus célèbres du cinéma.","c":"Cinéma & séries"},{"id":"vb922lu9","t":"En quelle année Queen a-t-il sorti le single « Bohemian Rhapsody » ?","v":1975,"u":"","annee":true,"a":"Le single dure près de six minutes, bien plus long que ce que les radios passaient alors.","c":"Musique"},{"id":"dbrf6346","t":"En quelle année a été lancée l'application de rencontres Tinder ?","v":2012,"u":"","annee":true,"a":"Son geste emblématique, glisser vers la droite pour dire oui, a été repris par de nombreuses autres applications.","c":"Autour de la fête"},{"id":"xagax1qn","t":"En quelle année Henri Poincaré a-t-il formulé la conjecture qui porte son nom ?","v":1904,"u":"","annee":true,"a":"Il a fallu un siècle pour la démontrer, et elle reste à ce jour le seul des problèmes du prix du millénaire à avoir été résolu.","c":"Sciences"},{"id":"e32dkomc","t":"En quelle année la loi Naquet a-t-elle rétabli le divorce en France ?","v":1884,"u":"","annee":true,"a":"Le divorce, autorisé en 1792 sous la Révolution, avait été supprimé en 1816 sous la Restauration ; Alfred Naquet a mené la campagne pour son retour.","c":"Autour de la fête"},{"id":"r85gzfft","t":"En quelle année l'abbé Pierre a-t-il lancé son célèbre appel à « l'insurrection de la bonté » pour les sans-abri ?","v":1954,"u":"","annee":true,"a":"L'appel fut lancé en plein hiver, à la radio, et provoqua un immense élan de dons.","c":"Histoire"},{"id":"pdqf94s5","t":"En quelle année Jacques Brel a-t-il fait ses adieux à la scène, à l'Olympia ?","v":1966,"u":"","annee":true,"a":"Il a ensuite tourné au cinéma et monté en 1968 la comédie musicale « L'Homme de la Mancha ».","c":"Musique"},{"id":"2mmr5i3n","t":"En quelle année Luis et Walter Alvarez ont-ils publié l'hypothèse d'un astéroïde responsable de la disparition des dinosaures ?","v":1980,"u":"","annee":true,"a":"Leur indice : une fine couche d'argile très riche en iridium, un métal rare sur Terre mais abondant dans certaines météorites.","c":"Nature"},{"id":"n2rln691","t":"En quelle année sort « Bambi », le film d'animation de Disney ?","v":1942,"u":"","annee":true,"a":"Le film est adapté d'un roman de l'écrivain autrichien Felix Salten.","c":"Cinéma & séries"},{"id":"2e7xdv3h","t":"En quelle année l'Académie française a-t-elle été fondée ?","v":1635,"u":"","annee":true,"a":"C'est le cardinal de Richelieu qui l'a fondée sous Louis XIII. Sa mission première était de donner des règles à la langue française.","c":"Culture générale"},{"id":"3ulr3tb5","t":"En quelle année le PACS a-t-il été créé en France ?","v":1999,"u":"","annee":true,"a":"Ouvert dès l'origine aux couples de même sexe comme de sexe différent, le Pacs est devenu très courant.","c":"Autour de la fête"},{"id":"35dlmxte","t":"En quelle année Daft Punk a-t-il sorti l'album « Random Access Memories » ?","v":2013,"u":"","annee":true,"a":"L'album contient « Get Lucky », enregistré avec Pharrell Williams et Nile Rodgers.","c":"Musique"},{"id":"bbvjzz7t","t":"En quelle année est sorti le tube « Y.M.C.A. » de Village People ?","v":1978,"u":"","annee":true,"a":"Le sigle désigne la Young Men's Christian Association, dont la chanson évoque les foyers.","c":"Autour de la fête"},{"id":"r95f6y7f","t":"En quelle année Mariah Carey a-t-elle sorti « All I Want for Christmas Is You » ?","v":1994,"u":"","annee":true,"a":"La chanson figure sur l'album « Merry Christmas » et revient dans les classements chaque mois de décembre.","c":"Autour de la fête"},{"id":"s6k696mb","t":"En quelle année l'Américain William Lawrence met-il au point le cream cheese, futur Philadelphia ?","v":1872,"u":"","annee":true,"a":"Fabriqué dans l'État de New York, il prit le nom de Philadelphie, ville alors réputée pour ses produits laitiers.","c":"Cuisine"},{"id":"ws1i8bqu","t":"En quelle année le comté obtient-il son appellation d'origine contrôlée ?","v":1958,"u":"","annee":true,"a":"Le comté est le fromage AOP le plus produit de France.","c":"Cuisine"},{"id":"y9jkxhp8","t":"En quelle année l'assistance vidéo à l'arbitrage fait-elle ses débuts en Coupe du monde ?","v":2018,"u":"","annee":true,"a":"Le premier penalty accordé grâce à elle en Coupe du monde l'a été à la France, pour une faute sur Antoine Griezmann contre l'Australie.","c":"Sport"},{"id":"8xx8ywsz","t":"En quelle année le Moulin Rouge a-t-il ouvert ses portes à Paris ?","v":1889,"u":"","annee":true,"a":"Le cabaret a ouvert la même année que la tour Eiffel, à l'occasion de l'Exposition universelle de Paris.","c":"Arts & lettres"},{"id":"xrtkvp1n","t":"En quelle année le ballet Raymonda a-t-il été créé à Saint-Pétersbourg ?","v":1898,"u":"","annee":true,"a":"Marius Petipa règle ce ballet d'inspiration médiévale sur une partition d'Alexandre Glazounov.","c":"Arts & lettres"},{"id":"ig87q8rm","t":"En quelle année paraît la première édition du Petit Larousse illustré ?","v":1905,"u":"","annee":true,"a":"Il a été conçu par Claude Augé. Sa célèbre devise « Je sème à tout vent » accompagne une semeuse soufflant sur un pissenlit.","c":"Culture générale"},{"id":"8nl93vpw","t":"En quelle année la boisson énergisante Red Bull a-t-elle été mise en vente en Autriche ?","v":1987,"u":"","annee":true,"a":"Red Bull s'inspire d'une boisson thaïlandaise, le Krating Daeng, dont le nom désigne le gaur, un grand bovin sauvage.","c":"Cuisine"},{"id":"sn5f504v","t":"En quelle année la rumba congolaise a-t-elle rejoint la liste du patrimoine immatériel de l'UNESCO ?","v":2021,"u":"","annee":true,"a":"Le dossier a été porté conjointement par les deux Congo, de part et d'autre du fleuve.","c":"Musique"},{"id":"qqtk7qi2","t":"En quelle année paraît la première édition du Dictionnaire de l'Académie française ?","v":1694,"u":"","annee":true,"a":"Le dictionnaire a été dédié au roi Louis XIV. L'Académie a achevé sa neuvième édition en 2024.","c":"Culture générale"},{"id":"rbwd8awm","t":"En quelle année eBay a-t-il racheté le service de paiement en ligne PayPal ?","v":2002,"u":"","annee":true,"a":"Les deux sociétés se sont séparées en 2015, et PayPal est redevenu une entreprise indépendante.","c":"Jeux & pop culture"},{"id":"6o7wuyww","t":"En quelle année Elizabeth II a-t-elle fêté son jubilé d'argent, pour ses vingt-cinq ans de règne ?","v":1977,"u":"","annee":true,"a":"Pour l'occasion, la reine a parcouru le Royaume-Uni et le Commonwealth, et des fêtes de rue ont été organisées partout dans le pays.","c":"Autour de la fête"},{"id":"41rqs0yn","t":"En quelle année sort « Avengers: Endgame », qui conclut l'arc narratif de l'univers cinématographique Marvel ?","v":2019,"u":"","annee":true,"a":"Il a réuni la plupart des héros de Marvel apparus au cinéma depuis plus de dix ans.","c":"Cinéma & séries"},{"id":"r0z279y0","t":"En quelle année se court le premier Tourist Trophy sur l'île de Man ?","v":1907,"u":"","annee":true,"a":"La course se déroule sur des routes ordinaires fermées à la circulation.","c":"Sport"},{"id":"a48s8uyy","t":"En quelle année Wilhelm Röntgen a-t-il découvert les rayons X ?","v":1895,"u":"","annee":true,"a":"L'une des premières radiographies montrait la main de son épouse, avec sa bague. Röntgen reçut en 1901 le tout premier prix Nobel de physique.","c":"Sciences"},{"id":"n3gzxoq5","t":"En quelle année le crapaud doré, petit amphibien orange du Costa Rica, a-t-il été observé pour la dernière fois ?","v":1989,"u":"","annee":true,"a":"Il ne vivait que dans la forêt de nuages de Monteverde, et seuls les mâles étaient d'un orange vif.","c":"Nature"},{"id":"2qnmv5xq","t":"En quelle année les premiers omnibus à chevaux circulent-ils à Paris ?","v":1828,"u":"","annee":true,"a":"Le nom vient du latin omnibus, « pour tous » ; l'idée serait née à Nantes, devant la boutique d'un chapelier nommé Omnès.","c":"Histoire"},{"id":"b27z3hap","t":"En quelle année le « Ice Bucket Challenge », où l'on se renversait un seau d'eau glacée sur la tête, a-t-il envahi les réseaux sociaux ?","v":2014,"u":"","annee":true,"a":"Ce défi visait à faire connaître la maladie de Charcot et à récolter des dons pour la recherche ; il a rapporté des millions de dollars.","c":"Jeux & pop culture"},{"id":"h00jc63n","t":"En quelle année la France a-t-elle instauré le numerus clausus en médecine ?","v":1971,"u":"","annee":true,"a":"Il fixait chaque année le nombre d'étudiants admis en deuxième année ; l'expression latine signifie « nombre fermé ».","c":"Culture générale"},{"id":"lt42q1rg","t":"En quelle année Jean-Baptiste Clément a-t-il écrit les paroles du « Temps des cerises » ?","v":1866,"u":"","annee":true,"a":"Clément a plus tard dédié la chanson à une infirmière nommée Louise, rencontrée pendant la Semaine sanglante de la Commune.","c":"Musique"},{"id":"6fgo6y1v","t":"En quelle année sort « Et Dieu… créa la femme », le film qui fait de Brigitte Bardot une star ?","v":1956,"u":"","annee":true,"a":"Le film est réalisé par Roger Vadim, alors mari de Brigitte Bardot, et tourné à Saint-Tropez.","c":"Cinéma & séries"},{"id":"92dh2anz","t":"En quelle année le canal Saint-Martin, à Paris, a-t-il été inauguré ?","v":1825,"u":"","annee":true,"a":"Voulu par Napoléon Ier pour alimenter Paris en eau, le canal Saint-Martin passe en partie sous terre, sous le boulevard Richard-Lenoir.","c":"Géographie"},{"id":"0ra67t4u","t":"En quelle année Adele a-t-elle sorti l'album « 21 » ?","v":2011,"u":"","annee":true,"a":"L'album contient « Rolling in the Deep » et « Someone Like You ».","c":"Musique"},{"id":"q5cc3z6e","t":"En quelle année le jeu télévisé Fort Boyard a-t-il été diffusé pour la première fois ?","v":1990,"u":"","annee":true,"a":"L'émission est tournée chaque été en mer, entre l'île d'Aix et l'île d'Oléron.","c":"Jeux & pop culture"},{"id":"d9r6g53b","t":"En quelle année la maison Suchard lance-t-elle le chocolat Milka ?","v":1901,"u":"","annee":true,"a":"Son nom vient de la contraction de « Milch » et « Kakao », lait et cacao en allemand.","c":"Cuisine"},{"id":"2gzsrd79","t":"En quelle année la Convention a-t-elle adopté le calendrier républicain ?","v":1793,"u":"","annee":true,"a":"Le poète Fabre d'Églantine a trouvé les noms des mois, inspirés des saisons, comme brumaire, floréal ou thermidor.","c":"Culture générale"},{"id":"3lm9jouk","t":"En quelle année Kanye West a-t-il sorti l'album « 808s & Heartbreak » ?","v":2008,"u":"","annee":true,"a":"L'album mise sur l'Auto-Tune et la boîte à rythmes TR-808, loin du rap habituel de l'époque.","c":"Musique"},{"id":"bj6obzhs","t":"En quelle année meurt Voltaire, peu après un retour triomphal à Paris ?","v":1778,"u":"","annee":true,"a":"Rousseau, son grand rival, est mort la même année, quelques semaines après lui.","c":"Arts & lettres"},{"id":"gsxdc6gh","t":"En quelle année Nintendo a-t-il sorti la console portable Game Boy ?","v":1989,"u":"","annee":true,"a":"En Occident, la Game Boy était vendue avec le jeu Tetris.","c":"Jeux & pop culture"},{"id":"yc1t8fg5","t":"En quelle année le squelette original du Spinosaure, conservé à Munich, a-t-il été détruit par un bombardement ?","v":1944,"u":"","annee":true,"a":"Le paléontologue allemand Ernst Stromer avait décrit l'animal d'après des fossiles d'Égypte ; il n'en restait ensuite que ses dessins et ses photos.","c":"Nature"},{"id":"dk30j0t4","t":"En quelle année Moby a-t-il sorti l'album « Play » ?","v":1999,"u":"","annee":true,"a":"Les dix-huit titres de l'album ont été utilisés dans des films, des séries ou des publicités.","c":"Musique"},{"id":"6uuuorem","t":"En quelle année la télévision en couleur est-elle arrivée sur les écrans français ?","v":1967,"u":"","annee":true,"a":"La France a choisi le procédé SECAM, différent du PAL allemand.","c":"Jeux & pop culture"},{"id":"65hchm50","t":"Sous quelle température corporelle parle-t-on d'hypothermie ?","v":35,"u":"°C","a":"La température normale du corps humain tourne autour de 37 °C ; le froid, mais aussi l'eau ou le vent, la font baisser.","c":"Sciences"},{"id":"ckeyljhc","t":"À quelle fréquence oscille le courant alternatif du réseau électrique français ?","v":50,"u":"hertz","a":"Aux États-Unis, la fréquence du réseau est de 60 hertz.","c":"Sciences"},{"id":"tgylu212","t":"Combien de kilomètres mesure le Pô, le plus long fleuve d'Italie ?","v":652,"u":"km","a":"Le Pô traverse la plaine du Nord de l'Italie et forme un vaste delta sur la mer Adriatique.","c":"Géographie"},{"id":"cxnnjtxc","t":"Combien de mètres mesure un mille marin ?","v":1852,"u":"m","a":"Il correspond à environ une minute d'arc de latitude, mesurée le long d'un méridien.","c":"Culture générale"},{"id":"qrqtdwy6","t":"Sur combien de cases se joue une partie d'échecs ?","v":64,"u":"cases","a":"Une légende indienne raconte qu'un sage demanda un grain de riz sur la première case, deux sur la deuxième, et ainsi de suite : une quantité impossible à fournir.","c":"Jeux & pop culture"},{"id":"eldijkmt","t":"À quelle altitude, en kilomètres, tournent les satellites en orbite géostationnaire ?","v":36000,"u":"km","a":"L'écrivain Arthur C. Clarke a popularisé en 1945 l'idée d'y placer des satellites de télécommunication.","c":"Sciences"},{"id":"ofmhn8s1","t":"À quel âge le peintre Raphaël meurt-il, à Rome, en 1520 ?","v":37,"u":"ans","a":"Raphaël repose au Panthéon de Rome, honneur rare pour un artiste.","c":"Arts & lettres"},{"id":"01961i1i","t":"Quelle est la largeur d'un lit deux places standard en France, en centimètres ?","v":140,"u":"cm","a":"Ce lit mesure traditionnellement 190 cm de long, mais la longueur de 200 cm s'est beaucoup répandue.","c":"Culture générale"},{"id":"4l8y557p","t":"Combien de quilles numérotées compte un jeu de Mölkky ?","v":12,"u":"quilles","a":"On ne lance pas de boule au Mölkky : on renverse les quilles avec un bâton de bois, le mölkky, qui donne son nom au jeu.","c":"Jeux & pop culture"},{"id":"ygp2fvld","t":"Quelle est la somme de tous les entiers de 1 à 100 ?","v":5050,"u":"","a":"On l'obtient en groupant 1 + 100, 2 + 99, 3 + 98… : cinquante paires qui valent chacune 101.","c":"Sciences"},{"id":"2onbfjle","t":"Quelle hauteur atteint le jet d'eau de Genève, en mètres ?","v":140,"u":"m","a":"L'eau du lac Léman y est projetée à une vitesse d'environ deux cents kilomètres à l'heure.","c":"Géographie"},{"id":"rsjv11r5","t":"Quelle longueur, en centimètres, mesure environ un grand dauphin adulte ?","v":300,"u":"cm","a":"Les petits naissent par la queue, et leur mère les aide à remonter respirer à la surface dès les premières secondes.","c":"Nature"},{"id":"maj8qbks","t":"Combien de mains de deux cartes différentes peut-on tirer d'un jeu de 52 cartes, sans tenir compte de l'ordre ?","v":1326,"u":"mains","a":"Au Texas hold'em, ces 1 326 mains de départ se regroupent en 169 types distincts.","c":"Sciences"},{"id":"twpg501m","t":"En 1987, combien d'équipes participent à la toute première Coupe du monde de rugby ?","v":16,"u":"équipes","a":"Cette première édition se dispute sur invitation, sans phase de qualification.","c":"Sport"},{"id":"jlg3rxnd","t":"Combien font 7 + 5 ?","v":12,"u":"","a":"Le signe « + » est une forme abrégée du mot latin « et ». On le trouve imprimé dès la fin du XVe siècle.","c":"Sciences"},{"id":"j1i1tb07","t":"Que vaut la somme des angles extérieurs d'un polygone convexe, quel que soit son nombre de côtés ?","v":360,"u":"degrés","a":"On peut le sentir en marchant : qui fait le tour d'un polygone en tournant à chaque coin revient face à son point de départ après un tour complet.","c":"Sciences"},{"id":"k1wg4sx5","t":"Quelle est l'altitude du Kilimandjaro, toit de l'Afrique, en mètres ?","v":5895,"u":"m","a":"Le géographe allemand Hans Meyer et l'alpiniste autrichien Ludwig Purtscheller en ont atteint le sommet pour la première fois en 1889.","c":"Géographie"},{"id":"84s01wzi","t":"Quelle largeur, en pixels, a une image vidéo Full HD ?","v":1920,"u":"pixels","a":"Une image Full HD contient plus de deux millions de pixels, soit plus de deux fois celle de la HD 720p.","c":"Sciences"},{"id":"zldktt7r","t":"Combien d'heures compte une journée ?","v":24,"u":"heures","a":"Les Égyptiens de l'Antiquité découpaient déjà le jour et la nuit en douze parties chacun.","c":"Culture générale"},{"id":"bck6bas0","t":"À quel rythme la comète de Halley revient-elle près du Soleil ?","v":76,"u":"ans","a":"Elle doit son nom à l'astronome anglais Edmond Halley, qui avait annoncé son retour pour 1758.","c":"Sciences"},{"id":"o5tlu3tv","t":"Combien de desserts compte la tradition provençale de Noël ?","v":13,"u":"desserts","a":"Le chiffre rappelle Jésus et ses douze apôtres ; on y trouve des fruits secs, des nougats et la pompe à l'huile.","c":"Cuisine"},{"id":"38lc9wt9","t":"En combien de livres sont réparties les Fables de La Fontaine ?","v":12,"u":"livres","a":"Le dernier livre, publié en 1694, est dédié au duc de Bourgogne, petit-fils de Louis XIV.","c":"Arts & lettres"},{"id":"xxd5v4kb","t":"Quelle taille, en centimètres, mesure environ un girafon à la naissance ?","v":180,"u":"cm","a":"Il naît debout et chute de près de deux mètres, puis se lève en moins d'une heure.","c":"Nature"},{"id":"6sefl9di","t":"Combien de kilomètres le Tibre, fleuve de Rome, mesure-t-il ?","v":405,"u":"km","a":"Selon la légende, Romulus et Rémus furent abandonnés sur le Tibre, puis recueillis par une louve.","c":"Géographie"},{"id":"vopyzuy5","t":"Combien d'heures dure la célèbre course d'endurance automobile du Mans ?","v":24,"u":"heures","a":"Les équipages se relaient au volant : les pilotes se succèdent dans la même voiture du départ du samedi jusqu'à l'arrivée du dimanche.","c":"Sport"},{"id":"vtgbcfjc","t":"Combien de secondes compte une demi-heure ?","v":1800,"u":"secondes","a":"Le mot « seconde » vient du latin secunda : la deuxième division de l'heure, après la minute.","c":"Culture générale"},{"id":"j9ia7b8x","t":"Combien de touches compte le piano Bösendorfer Imperial, qui descend plus bas que les pianos ordinaires ?","v":97,"u":"touches","a":"Sur certains modèles Bösendorfer, les touches ajoutées dans le grave sont noires, pour que le pianiste ne se trompe pas.","c":"Musique"},{"id":"4mvm523u","t":"Combien d'arêtes possède un icosaèdre régulier, polyèdre à vingt faces triangulaires ?","v":30,"u":"arêtes","a":"Les dés à vingt faces des jeux de rôle ont la forme d'un icosaèdre régulier.","c":"Sciences"},{"id":"qm478jfv","t":"Combien de petites facettes colorées compte en tout un Rubik's Cube classique de 3 × 3 × 3 ?","v":54,"u":"facettes","a":"Il a été démontré en 2010 qu'on peut toujours résoudre le cube en vingt mouvements au plus.","c":"Jeux & pop culture"},{"id":"mls9pbah","t":"À quelle température, en degrés Celsius, l'aluminium pur fond-il ?","v":660,"u":"°C","a":"Au XIXe siècle, avant le procédé d'électrolyse, l'aluminium valait plus cher que l'or ; Napoléon III aurait réservé des couverts en aluminium à ses hôtes de marque.","c":"Sciences"},{"id":"4kgk827b","t":"Combien de côtés compte un dodécagone ?","v":12,"u":"côtés","a":"Dodéca, « douze » en grec, se retrouve dans « dodécaèdre », le solide à douze faces.","c":"Sciences"},{"id":"cljxago3","t":"Combien d'aliens compte la grille ennemie au début d'une partie de Space Invaders ?","v":55,"u":"aliens","a":"Les envahisseurs avancent en rangs serrés et accélèrent à mesure que le joueur en élimine.","c":"Jeux & pop culture"},{"id":"0b95tmjq","t":"Combien d'étages compte la Burj Khalifa, la tour de Dubaï qui scintille à minuit le 31 décembre ?","v":163,"u":"étages","a":"Elle a été conçue par le cabinet d'architectes américain Skidmore, Owings & Merrill.","c":"Autour de la fête"},{"id":"q0t3hbfs","t":"Combien de sélections Lilian Thuram a-t-il disputées en équipe de France de football ?","v":142,"u":"sélections","a":"Champion du monde 1998 et champion d'Europe 2000, il dispute son dernier match avec les Bleus à l'Euro 2008.","c":"Sport"},{"id":"tiprb4z3","t":"À quel âge Alexandre le Grand meurt-il, à Babylone ?","v":32,"u":"ans","a":"Roi à vingt ans, il avait bâti en à peine plus de dix ans un empire qui s'étendait jusqu'à l'Inde.","c":"Histoire"},{"id":"5o3dsc3g","t":"À quel âge le guitariste Jimi Hendrix est-il mort ?","v":27,"u":"ans","a":"Il a joué l'hymne américain, déformé à la guitare, devant le public de Woodstock en 1969.","c":"Musique"},{"id":"dwfujlnh","t":"Quelle part de la surface de la Terre les océans recouvrent-ils environ ?","v":70,"u":"%","a":"L'hémisphère Sud est bien plus océanique que l'hémisphère Nord, où se concentre l'essentiel des terres émergées.","c":"Sciences"},{"id":"zocs8v9l","t":"Combien de kilomètres la Tamise mesure-t-elle ?","v":346,"u":"km","a":"À Oxford, on surnomme la Tamise « Isis ». Son estuaire s'ouvre sur la mer du Nord.","c":"Géographie"},{"id":"kn3agws0","t":"Combien de mètres mesure la Sky Tower d'Auckland, d'où partent les fusées du réveillon néo-zélandais ?","v":328,"u":"m","a":"Les plus téméraires peuvent sauter du haut de la tour, retenus par des câbles.","c":"Autour de la fête"},{"id":"ehiqxb8r","t":"À partir de quel âge peut-on commencer la conduite accompagnée en France ?","v":15,"u":"ans","a":"Le jeune doit rouler au moins 3 000 kilomètres avec son accompagnateur avant de passer l'examen.","c":"Culture générale"},{"id":"bzoozkrs","t":"Une voiture roule à 90 km/h pendant 20 minutes. Quelle distance parcourt-elle ?","v":30,"u":"km","a":"Convertir une vitesse en mètres par seconde est simple : il suffit de diviser par 3,6. 90 km/h font donc 25 m/s.","c":"Sciences"},{"id":"9gc22bml","t":"Combien de pixels de hauteur compte une image en ultra-haute définition 4K des téléviseurs ?","v":2160,"u":"pixels","a":"Ce format compte exactement quatre fois plus de pixels que le Full HD : deux fois plus en largeur, deux fois plus en hauteur.","c":"Sciences"},{"id":"reyxr853","t":"Combien de Danses hongroises Johannes Brahms a-t-il écrites ?","v":21,"u":"danses","a":"Brahms les a d'abord écrites pour piano à quatre mains ; il en a lui-même orchestré quelques-unes.","c":"Musique"},{"id":"za1vox84","t":"Combien d'épisodes compte au total la série « Dr House » (2004-2012) ?","v":177,"u":"épisodes","a":"Le personnage de House s'inspire de Sherlock Holmes : son ami Wilson rappelle Watson, et il vit au 221B.","c":"Cinéma & séries"},{"id":"guas6s89","t":"Quelle est la hauteur, en mètres, de la statue de la Liberté, du sol du socle à la flamme de la torche ?","v":93,"u":"m","a":"Gustave Eiffel a conçu la structure métallique interne qui soutient la statue.","c":"Arts & lettres"},{"id":"5dxdncg0","t":"Combien de centimètres cubes contient un litre ?","v":1000,"u":"centimètres cubes","a":"Un litre est un décimètre cube : un cube de dix centimètres de côté.","c":"Culture générale"},{"id":"coibp37v","t":"Quel est le cube de 3 ?","v":27,"u":"","a":"On parle de cube parce que 3 × 3 × 3 donne le volume d'un cube de 3 unités de côté.","c":"Sciences"},{"id":"v74pjmc2","t":"Depuis 2006, quel est l'âge minimal pour se marier en France, pour les femmes comme pour les hommes ?","v":18,"u":"ans","a":"Avant la loi du 4 avril 2006, les femmes pouvaient se marier dès 15 ans, les hommes à 18 ans.","c":"Autour de la fête"},{"id":"owgzq8v9","t":"Quelle longueur, en mètres, peut atteindre une baleine bleue adulte ?","v":30,"u":"m","a":"Son baleineau boit des centaines de litres de lait par jour et prend du poids à une vitesse spectaculaire.","c":"Nature"},{"id":"837n6iwh","t":"Jusqu'à combien de mètres peut mesurer une feuille du palmier Raphia regalis ?","v":25,"u":"m","a":"Ce palmier d'Afrique centrale possède les plus longues feuilles du règne végétal.","c":"Nature"},{"id":"cywf4c4c","t":"Avant la loi de 1974, à quel âge devenait-on majeur en France ?","v":21,"u":"ans","a":"C'est Valéry Giscard d'Estaing, tout juste élu, qui fait abaisser la majorité à 18 ans, en juillet 1974.","c":"Histoire"},{"id":"4psidls3","t":"Combien de cartes compte la boîte du Dobble classique ?","v":55,"u":"cartes","a":"Le principe repose sur la géométrie : chaque paire de cartes partage un seul symbole.","c":"Jeux & pop culture"},{"id":"fczjzsq5","t":"Quelle est la température normale du corps humain, à peu près ?","v":37,"u":"°C","a":"Le médecin allemand Carl Wunderlich a fixé ce repère au XIXe siècle, en relevant la température de milliers de patients.","c":"Sciences"},{"id":"ot1m24ro","t":"À combien de mètres culmine le puy de Sancy, en Auvergne ?","v":1885,"u":"m","a":"La Dordogne prend sa source au pied du Sancy, née de la rencontre de deux torrents, la Dore et la Dogne.","c":"Géographie"},{"id":"pvzbrwdw","t":"Combien de baisers Johnny Hallyday promet-il dans son adaptation d'un succès d'Adriano Celentano, en 1961 ?","v":24000,"u":"baisers","a":"Le titre original, « 24 mila baci », avait été présenté par Celentano au festival de Sanremo.","c":"Musique"},{"id":"qthuuah8","t":"À quel âge devient-on majeur en France ?","v":18,"u":"ans","a":"La majorité est passée de 21 à 18 ans en 1974, sous la présidence de Valéry Giscard d'Estaing.","c":"Autour de la fête"},{"id":"rvuwzphg","t":"Quel est le rayon moyen de la Terre, en kilomètres ?","v":6371,"u":"km","a":"Ératosthène, au IIIe siècle avant notre ère, a estimé la taille de la Terre en comparant la longueur d'ombres à deux endroits d'Égypte.","c":"Sciences"},{"id":"hzw8thi0","t":"En 1998, combien d'équipes disputent la phase finale de la Coupe du monde, en France ?","v":32,"u":"équipes","a":"De 1982 à 1994, 24 équipes y participaient ; auparavant, elles n'étaient que 16.","c":"Sport"},{"id":"b29162cf","t":"Combien d'emojis comptait la toute première série, dessinée par Shigetaka Kurita pour l'opérateur japonais NTT Docomo ?","v":176,"u":"emojis","a":"Le musée d'Art moderne de New York, le MoMA, a fait entrer ces premiers emojis dans ses collections en 2016.","c":"Jeux & pop culture"},{"id":"b88tavue","t":"Au volley-ball, à combien de points se joue le tie-break, cinquième et dernier set ?","v":15,"u":"points","a":"Comme les autres sets, le tie-break exige deux points d'écart : il peut donc dépasser son score prévu.","c":"Sport"},{"id":"f641rzbv","t":"Environ combien d'œufs une femelle de poisson-lune peut-elle pondre en une seule fois ?","v":300000000,"u":"œufs","a":"Le poisson-lune, ou môle, est le plus lourd des poissons osseux : ses œufs minuscules sont dispersés en pleine mer, et très peu de larves survivent.","c":"Nature"},{"id":"brg0edw0","t":"Combien de grammes compte un kilogramme ?","v":1000,"u":"grammes","a":"À la fin du XVIIIe siècle, le gramme fut d'abord défini comme la masse d'un centimètre cube d'eau.","c":"Culture générale"},{"id":"owdn09zp","t":"Quel est le diamètre intérieur, en centimètres, d'un cercle de panier de basket ?","v":45,"u":"cm","a":"Les premiers paniers de basket étaient de vrais paniers à pêches : il fallait aller chercher le ballon après chaque point.","c":"Sport"},{"id":"nc9ox20x","t":"Avant le système métrique, en combien de lignes se divisait le pouce français ?","v":12,"u":"lignes","a":"La ligne a survécu chez les horlogers, qui mesurent encore parfois la taille d'un mouvement de montre en lignes.","c":"Culture générale"},{"id":"1srf1f2s","t":"Combien pèse, en grammes, le javelot féminin en compétition ?","v":600,"u":"g","a":"Le javelot masculin a été redessiné en 1986, son centre de gravité avancé, car les meilleurs jets menaçaient de sortir des stades.","c":"Sport"},{"id":"ca4nxl98","t":"En Corée, à quel jour de vie du bébé fête-t-on le baek-il, avec des gâteaux de riz ?","v":100,"u":"jours","a":"Autrefois, passer ce cap voulait dire avoir survécu à la période la plus fragile ; on partageait les gâteaux avec les voisins.","c":"Autour de la fête"},{"id":"ihv2hce7","t":"Combien de dents compte le bord du Petit Beurre de LU, sans ses quatre coins ?","v":52,"u":"dents","a":"Ses quatre coins évoquent les saisons, ses dents les semaines et ses vingt-quatre trous les heures d'une journée.","c":"Cuisine"},{"id":"ohhk7pte","t":"Combien de cartes compte le jeu du Mille Bornes ?","v":106,"u":"cartes","a":"Parmi elles, quatre bottes, comme l'As du volant, protègent définitivement contre une attaque.","c":"Jeux & pop culture"},{"id":"0t2ut7f3","t":"Combien font 100 − 37 ?","v":63,"u":"","a":"Les signes + et − sont imprimés pour la première fois en 1489 dans un livre de l'Allemand Johannes Widmann.","c":"Sciences"},{"id":"s2kgp18d","t":"En combien de temps environ la Station spatiale internationale fait-elle le tour de la Terre ?","v":90,"u":"minutes","a":"Ses occupants voient donc environ seize levers de Soleil par jour.","c":"Sciences"}]};
window.TABLEAUX=[{"q":"Q1167907","t":"Le Déjeuner des canotiers","p":"Auguste Renoir","a":1880,"an":"La scène se déroule sur la terrasse d'un restaurant de Chatou, au bord de la Seine."},{"q":"Q1231009","t":"Le Sacre de Napoléon","p":"Jacques-Louis David","a":1807,"an":"David est le « premier peintre » de l'Empereur ; il a représenté Napoléon couronnant Joséphine, et non lui-même."},{"q":"Q12418","t":"La Joconde","p":"Léonard de Vinci","a":1503,"an":"Le voleur, le vitrier italien Vincenzo Peruggia, avait travaillé au Louvre ; il fut arrêté à Florence en voulant vendre le tableau."},{"q":"Q1245354","t":"Un bar aux Folies Bergère","p":"Édouard Manet","a":1882,"an":"Le reflet de la serveuse dans le miroir ne correspond pas à sa position de face, ce qui a longtemps intrigué les spectateurs."},{"q":"Q1368055","t":"Des glaneuses","p":"Jean-François Millet","a":1857,"an":"Le tableau montre trois paysannes courbées pour ramasser les épis laissés après la moisson."},{"q":"Q1452762","t":"Rue de Paris, temps de pluie","p":"Gustave Caillebotte","a":1877,"an":"Fortuné, Caillebotte a acheté des toiles de ses amis ; sa collection est entrée dans les musées de l'État après sa mort, en 1894."},{"q":"Q157541","t":"Les Tournesols","p":"Vincent van Gogh","a":1888,"an":"Il les a peints pour décorer la chambre de son ami Gauguin, venu le rejoindre dans la Maison jaune."},{"q":"Q164517","t":"La Danse","p":"Henri Matisse","a":1910,"an":"La toile n'utilise que trois couleurs : le rouge des corps, le bleu du ciel et le vert de la colline. Elle fut commandée par un collectionneur russe."},{"q":"Q167605","t":"La Laitière","p":"Johannes Vermeer","a":1660,"an":null},{"q":"Q17277950","t":"Les Joueurs de cartes","p":"Paul Cézanne","a":1893,"an":"Les modèles étaient des paysans des environs d'Aix-en-Provence ; une version a battu en 2011 un record de vente privée."},{"q":"Q185372","t":"La Jeune Fille à la perle","p":"Johannes Vermeer","a":1665,"an":"Son modèle reste inconnu, et la perle pourrait n'être qu'une imitation en verre ou en étain."},{"q":"Q208758","t":"Les Ménines","p":"Diego Vélasquez","a":1656,"an":"Picasso en a donné cinquante-huit variations en 1957."},{"q":"Q212616","t":"Le Radeau de la Méduse","p":"Théodore Géricault","a":1819,"an":"Pour peindre son tableau, Géricault a interrogé des survivants, dont Savigny et Corréard."},{"q":"Q219831","t":"La Ronde de nuit","p":"Rembrandt","a":1642,"an":"Le titre est trompeur : la scène se déroule en plein jour, mais le vernis noirci par les siècles lui donnait l'allure d'une nuit."},{"q":"Q220859","t":"Les Époux Arnolfini","p":"Jan van Eyck","a":1434,"an":"Au mur, il a tracé « Jan van Eyck fut ici, 1434 », comme un témoin de la scène."},{"q":"Q2339059","t":"Pluie, Vapeur et Vitesse","p":"William Turner","a":1844,"an":"Le tableau représente un train sur le pont de Maidenhead, sur la Tamise, dans la brume."},{"q":"Q2571560","t":"L'Angélus","p":"Jean-François Millet","a":1858,"an":"Salvador Dalí était si obsédé par cette toile qu'il lui a consacré un essai, Le Mythe tragique de l'Angélus de Millet."},{"q":"Q257580","t":"Le Dernier Voyage du Téméraire","p":"William Turner","a":1839,"an":"Le Téméraire avait combattu à Trafalgar en 1805 avant d'être remorqué pour être démoli. La toile figure aujourd'hui à la National Gallery de Londres."},{"q":"Q29530","t":"La Liberté guidant le peuple","p":"Eugène Delacroix","a":1830,"an":"La toile, achetée par l'État en 1831, fut jugée trop subversive pour être exposée pendant plusieurs années."},{"q":"Q311243","t":"Le Voyageur contemplant une mer de nuages","p":"Caspar David Friedrich","a":1818,"an":"Le voyageur est vu de dos, procédé cher à Friedrich pour inviter le spectateur à se placer devant le paysage."},{"q":"Q354396","t":"Portrait d'Adele Bloch-Bauer I","p":"Gustav Klimt","a":1907,"an":"Saisi par les nazis, le tableau fut rendu en 2006 à Maria Altmann, nièce du modèle, après une longue bataille judiciaire."},{"q":"Q45585","t":"La Nuit étoilée","p":"Vincent van Gogh","a":1889,"an":"Le paysage est celui que l'artiste voyait de la fenêtre de sa chambre à l'asile, mais il a ajouté le village de mémoire."},{"q":"Q464782","t":"American Gothic","p":"Grant Wood","a":1930,"an":"Ses modèles étaient sa sœur et son dentiste ; la maison existe à Eldon, dans l'Iowa."},{"q":"Q471379","t":"Le Cri","p":"Edvard Munch","a":1893,"an":"Munch a décliné son Cri en plusieurs versions : deux peintures, deux pastels et des lithographies."},{"q":"Q476458","t":"Le Serment des Horaces","p":"Jacques-Louis David","a":1784,"an":"Le tableau a été peint à Rome, avant d'être envoyé à Paris pour le Salon."},{"q":"Q500985","t":"Chasseurs dans la neige","p":"Pieter Brueghel l'Ancien","a":1565,"an":"Le tableau appartient à une série consacrée aux saisons ou aux mois de l'année."},{"q":"Q523974","t":"Vue de Delft","p":"Johannes Vermeer","a":1661,"an":"Marcel Proust la jugeait le plus beau tableau du monde et l'évoque dans « La Prisonnière »."},{"q":"Q683274","t":"Bal du moulin de la Galette","p":"Auguste Renoir","a":1876,"an":"Le moulin de la Galette était un lieu de danse populaire de Montmartre."},{"q":"Q698487","t":"Le Baiser","p":"Gustav Klimt","a":1907,"an":"Klimt a fondé la Sécession viennoise en 1897 et s'est inspiré des mosaïques byzantines de Ravenne."},{"q":"Q699091","t":"La Tour de Babel","p":"Pieter Brueghel l'Ancien","a":1563,"an":"La tour y ressemble au Colisée de Rome, que le peintre avait vu lors de son voyage en Italie."}];
